/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20060515-9","meetingId":"h18-cm05","date":"2006年5月15日","dateIso":"2006-05-15","committee":"文教委員会","time":"午後１時０４分～午後３時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"最初に、（１）「まもるっち」の機種変更","agenda":"最初に、（１）「まもるっち」の機種変更","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"でも、実際に持って歩くのは子どもたちですから、子どもたちに対してどういう考え方で説明をしていくのかということをお聞きしたいと思います。ですから、メリットが多分にあると思いますので、それをどういうふうに説明されるつもりなのか。","respondent":"市川庶務課長","answer":"子どもの安全を守るこの子機に、ちょっとまだ時間がありますので、よく現場と相談しながら検討してまいりたいというふうに思っております。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"ＹＯＺＡＮの経営状況というんですか、お話しできる範囲で教えていただきたいということと、旧体制のものも誤動作が結構あったんですね。機種が全部変わりますのでそこら辺の調査をしているのだろうと思うんですが、それに対しての確認等はどうされるのかということです。","respondent":"市川庶務課長","answer":"この初期投資として投ずるものがどういうふうにビジネスとして成立をして投資を開始するのか、そういうことを見込んだ上での話だと思いますので。","id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"さらに確認したいんですが、要は、それから下手をするとこの事業が途中でなくなってしまうというようなことがないのかどうかということなんです。そこら辺の保証は契約上どういうような約束事でＹＯＺＡＮの方はやっているのかなということを最後にお聞きしたいと思います。","respondent":"市川庶務課長","answer":"このＹＯＺＡＮが「まもるっち」の機種変更をする背景に、ＰＨＳ通信方式から携帯電話に変えた。ちょっと変な言い回しですけれども、通常、契約内容を移行してくれる契約を行えば十分対応していけるものだというふうに考えてあります。","id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"１つは、システム全体がどう変わったか、ちょっと流れを聞かせてほしいんですけれども。ＧＰＳを新たに利用するということとの関係で言うと、どういうこと、ちょっと何かここのところがよくわからないんですけれどもとの意見を述べました。","respondent":"市川庶務課長","answer":"今回の機種変更によりまして、通信そのものは通常の携帯電話と同じアンテナで行います。それから、位置の確認はＧＰＳを使って行っていく、こういう変更点です。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"費用負担の件でちょっとお伺いしたいんですが、やっぱり安かったですかね、ＰＨＳの方が携帯よりは。さっきのＹＯＺＡＮは、実際には事業としてどういう収入のところに位置するのかちょっとわからないんですけれども、ちょっと教えてもらいたいんです。","respondent":"市川庶務課長","answer":"ただ、当然のことながら、こういうシステムの変更をするときには、右側の部分が大分変わります。事業者の事業投資ということで対応するということで、私ども、説明を受けているところです。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"変わらないはずがないんじゃないかなというふうに、ボーダフォンを使うわけですから違うわけですよね、料金体系も何も。もう１つどうもよくわからないので、例えば、今度は幾らになるのかというのがわかったらちょっと説明を求めました。","respondent":"市川庶務課長","answer":"少しつかみの話で申し上げますと、１人の子ども、１台につき約１,０００円の基本料金というのがかかっているんです。こういうことになります。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、これはもっと全国展開すれば数のメリットが出てきますから、多少ある程度そこで吸収しているというふうに見ていいんですかね。多少ここで赤をかぶっても、将来を見通せば必ず返ってくるというのがほんとうのところではないかと思いますけれども、そこら辺はいかがか尋ねました。","respondent":"市川庶務課長","answer":"結論としては、私もそういうふうに受けとめてあります。どこの自治体でも使うことができるわけですから、こういうことを見込んでの今回の措置だというふうに私は受けとめております。","id":"exchange-007"}]},{"id":"topic-02","title":"校舎改築事業の進行状況","agenda":"校舎改築事業の進行状況","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ここ数年、非常に改築が進んで、オープンスペースというのを盛んにつくっていると思うんです。どういうふうに教育に役に立っているのか、影響を含めて、その辺はいかがなんか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"１０分間ぐらいちょっとグループで話し合って、また全体でとか、そういった活用をするということが一番オープンスペースでは多いですね。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"今の子どもたちにとってどういう環境がいいのかということで、その辺をちょっとご説明いただいた方がいいかなというふうに思っています。そこら辺を変えるべきところは次に生かしてほしいんですが、その辺はどういうふうに今後、その辺はどういうふうになっているのか尋ねました。","respondent":"市川庶務課長、吉村小中一貫教育担当課長","answer":"１点目のご質問ですけれども、この小山小に限らず、いずれの改築も設計に当たってはそういう取り組みをしているということがまず１つあります。やはり１つの経験案件を増やす中、不断の取り組みということで… 先ほどのオープンスペース等の取り組みですけれども、今、いつでも子どもたちが見られるようにするというような活用の仕方もあるんですね。ですから、そういったことの方がむしろ重要なのかなというふうに思っています。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"２時になったので、非常に質問しづらいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"率直に言ってどこにあるのかなというのが非常に見つけにくいというのが１つあったので教えていただきたいんですけれども、しかし、つくっている姿。","respondent":"市川庶務課長","answer":"給食室については、１階平面図のアリーナの下のところにあるわけですけれども。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"ほかに２枚平面図が紹介されていますけれども、そういう改築が終わったところもちょっと見てくると、そういう気がしてならないんですね。私は改めてそこを、その辺もう１回、その辺の重要さというのをどういうふうに認識されているかをちょっと伺って終わりにしたいと思います。","respondent":"市川庶務課長","answer":"それから主事室、用務室、当然のことながら一定の条件の中ではそれに優先して設計上のポジションを与えるということはないと思います。","id":"exchange-012"},{"speaker":"南委員","kind":"意見","question":"子どもたちに対するそういう問題を後に押しやるということではなくて、やっぱり大事な柱として位置づけるべきだというふうに思います。これからもこの問題については研究もしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/670410?Template=document&Id=4570#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":21592,"voices":53}},{"id":"h18-20060515-5","meetingId":"h18-cm05","date":"2006年5月15日","dateIso":"2006-05-15","committee":"総務委員会","time":"午後１時０２分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"を議題といたします。 (1)国際救援センターの閉所","agenda":"を議題といたします。 (1)国際救援センターの閉所","exchanges":[{"speaker":"三村委員","kind":"質問・要望","question":"敷地面積がかなり広いんですけれども、返還後の予定等、もし情報があれば教えていただきたい。","respondent":"堀越行財政改革担当課長","answer":"ＪＲ東日本にはちょっと接触していないんですけれども、外務省、それから、難民事業本部によりましてもまだ未定で、外務省のほうも承知していないです。","id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"一つだけ教えてください。商品券が出されるというお話だったんですが、その辺もあわせて、ひとつ教えていただきたい。","respondent":"中川原広報広聴課長","answer":"集会の出席率は、大体多いときで４５名、少ないときで３５名の幅です。出席した方に、謝礼として地域商品券を差し上げているです。","id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"そうすると、これは個人で応募されますよね。１年間で何回か出席しなきゃならない、途中でどうのということがあるのかどうかも含めて、ちょっと説明を求めました。","respondent":"中川原広報広聴課長","answer":"モニターアンケートにもお答えいただくということを想定しているわけですが、大体、皆さん１回か２回のお休みです。そういうことを確認した上で委嘱をさせていただいていますので、そういった意味では、ご協力をしていただきやすい方に委嘱をしているという状況です。","id":"exchange-003"},{"speaker":"藤田委員","kind":"質問・要望","question":"６名の願いがかなわなかったというか、この選択は非常に難しいと思うんですが、何か基準みたいなものがあって決めるんでしょうか。その辺の経緯だけ、ちょっと説明を求めました。","respondent":"中川原広報広聴課長","answer":"今までの過去のデータとか全部蓄積されていますので、見ますと、６０歳代とか、７０歳代の方は、過去に経験されている方がかなり多いんです。できるだけ経験が少ない方からやっていただくというで、ご案内をして、納得していただいているところです。","id":"exchange-004"},{"speaker":"藤田委員","kind":"質問","question":"これは、ご本人に対しては通知が行くわけですか。今回、非常に残念でしたけれども、また次回という内容の通知を何かされているのか、どうか説明を求めました。","respondent":"中川原広報広聴課長","answer":"はタウンミーティングとか、そのほかのこともやっておりますので、どうぞそういった機会にもお出でくださいということでご案内しています。","id":"exchange-005"}]},{"id":"topic-02","title":"所管事務調査に入ります。 契約事務","agenda":"所管事務調査に入ります。 契約事務","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと伺いますけれども、１０％に引き上げたということですけれども、１０％というのはどういう根拠なのかということを説明していただきたい。３の課徴金減免制度の概要のところでは、あとのＧ７諸国、ちょっと教えてほしいと求めました。","respondent":"中島経理課長","answer":"課徴金の説明の中で申し上げましたけれども、例えば入札価格の６％ぐらいは当然得ているだろうということで、６％と設定してございました。ということは、では６％よりもっと利益を得ているんだろうと公正取引委員会が考えまして、思い切って１０％まで引き上げた。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"１０％自体がどうなのかというのは、それで十分なんだろうかという気も一方ではするんです。ちょっと外国との比較があると助かりますけれども、なければとりあえず次にとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"三村委員","kind":"質問","question":"今の説明の中で、売上高というのは、工事の売上高ですか。そうではなくて、会社全体の売上高の１０％か尋ねました。","respondent":"中島経理課長","answer":"要するに談合に係わった不当な行為に基づいた売上げという意味です。ですから、会社全体の売上げということではございません。","id":"exchange-008"},{"speaker":"三村委員","kind":"質問","question":"工事の売上げの１０％ということだと、まだまだ低いなと、聞いていて思ったんです。入札や何かが今後どういうふうになっていくのか、その辺について、お考えをお聞きしたいんですけれども。","respondent":"中島経理課長","answer":"現在、品川区の中で、入札の関係で大きな問題が生じているという認識は持っておりません。常にそういった適正、あるいは公明な入札制度を目指して、今後も進めていきたいと考えております。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"この減免制度の第１号がこの資料にありますけれども、これで直るのかなと、またこういう仕組みというのはどうなんだろうというふうに思うんですよ。それから、私は、発注側の姿勢の問題に大きなものがあるんじゃないかと思っているんですけれども、その辺は、いかがお考えか尋ねました。","respondent":"中島経理課長","answer":"これはこれで、そういった体質を改善していくという部分では、非常に効果があるものではないかなと考えています。最近、価格プラス品質の問題も含めて考えながらやっていく必要があるのかということを検討するのは、今後の課題になってくるのかなと考えております。","id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"品川区では、そういう構造的な仕組みをなくしていかなくちゃいけないと私は思うんですが、その辺はどうでしょうか。たまたまきょうのニュースもあるわけですけれども、当事者としては、どうか尋ねました。","respondent":"本間総務部長","answer":"先ほどちょっと経理課長も言いましたけれども、予定価格を事前に公表しておりますし、現説の禁止等々。経理課長が説明した課徴金の減免制度だけで、今回、さらに厳しくした制度を導入しましたです。","id":"exchange-011"},{"speaker":"本田委員","kind":"質問・要望","question":"日本の新しい仕組みづくりの中に、今みたいな形で残っているという構造的なものというのは、何かを変えていかなければならないと思います。幹部職員だけではなくて、当該の皆さん方が心して対応して、信頼が落ちるようなことのないようにやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"その他に入ります。 後ほど、前回、議題でありました学校改修の取り組み等","agenda":"その他に入ります。 後ほど、前回、議題でありました学校改修の取り組み等","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"９ページの同和問題のところで、この質問は非常に恣意的というか、そもそも質問としておかしいと思うんです。改めて、今、いわゆる被差別地区、同和地区というのは、今、どうなっているのかというのを、ちょっと説明していただきたい。","respondent":"武内人権啓発課長","answer":"現状において、同和対策特別措置法が平成１４年に終了いたしましたけれども、同和地区そのものの事業がその時点で終了したということではありません。現在も、一般施策で各自治体では実施されている。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"１０ページの質問は、私たちが質問する場合には、こういうふうにはしないですよね。こういうのは、私はやめたほうがいいと思いますし、この冊子そのものをどういうふうにするのか、お伺いしたいんです。","respondent":"武内人権啓発課長","answer":"同和地区対策事業ということで、４,１６０カ所を同和地区として国が指定して、そういう事業を行ったという事実もあります。それから、こちらの冊子につきましては、私どもの啓発の事業でお配りしたり、内部の研修等で利用します。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"それを見ると、ちょっと言葉に語弊がありますけれども、そういうふうにして終わらせないというふうな気がしてしようがないですね。改めて、こんなものはまくべきじゃないと言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"三村委員","kind":"質問","question":"今年も、１２ページにあるような講演を計画されているかと思うんですけれども、今年度の議題だとか、そういうのを教えていただけますか。","respondent":"武内人権啓発課長","answer":"５月９日に、憲法週間、講演と映画の集いを実施済みであります。１２月も人権週間がございまして、予定をさせていただいていますけれども、１２月の事業につきましては、現在、検討中です。","id":"exchange-016"},{"speaker":"三村委員","kind":"質問","question":"映画等のほうは「ＡＬＷＡＹＳ 三丁目の夕日」ということで、映画の設定の人権の絡みがよくわからなかったんですが、どうしてこの映画だったのかなというのがちょっと疑問だったので、その辺ちょっとお聞きしたいなと思います。","respondent":"武内人権啓発課長","answer":"昭和３３年当時の時代、そういう夢だとか、希望だとかという部分が非常に感動的に描かれた映画ですので利用させていただきました。","id":"exchange-017"},{"speaker":"三村委員","kind":"意見","question":"もうちょっと具体的に人権に関するシビアな問題とか、そういうものを問題提起しているような映画があるかと思います。人権について深い内容が含まれているとか、そういったような映画設定をしてほしいなということを、意見だけ述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"原委員","kind":"質問","question":"かけてないんですか、入れる方はいいけれども、入れない方はそれなりにいろいろ文句を言われていたようです。去年もそうだったということですから、今後もまた、十分に考えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"意見","question":"よくわからないのは、Is値０.６以上の耐震工事をやっているということで、これは法的なところでクリアしているという説明なんですよね。国庫補助の理由なんですけれども、Is値０.７という線が出ていますけれども、ここの関連というのが何かよくわからないんですとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"そういう意味では、当初のIs値０.６を目標値にしたというのと、人命を損なわないように避難できるだけの耐震強度を目標として対策を打ったと。さらにIs値０.７という数値に上位修正をして、今年、さらにしていくという違いです。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"では、学校施設はどうしろという基準なんですか。それとも、Is値０.７は最低基準ということでやっているのか、どうなんか尋ねました。","respondent":"宍戸施設担当課長","answer":"Is値０.７という数値が出てまいりまして、避難所としての機能も加味した上で、Is値０.７というのを推奨しているです。法的に定められているのは、あくまでもIs値０.６です。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"そのときには、もうちょっと補強工事を強化しようとか、そういう発想にはならなかったんでしょうか。何でIs値０.６というふうに考えたのか、もうちょっと強化しようとならなかったのか、そのときの判断はどういうことなんか尋ねました。","respondent":"日下部企画財政課長","answer":"緊急対策として耐震化をやろうということで、少なくとも法基準のIs値０.６をクリアするという前提で取り組みをさせていただいたです。やはりこれは耐震化の取り組み、基本的には国庫補助もいただくという前提でIs値０.７をクリアするということで、取り組んでいるです。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それを早期にやってほしいと求めましたけれども、その場合、Is値０.６まではしたわけですね。Is値０.６からIs値０.７にする場合の補助になるのか、平成１３年度までにかけてきた費用も対象になるのか、そこのところはどうなんか尋ねました。","respondent":"日下部企画財政課長","answer":"基本的には、今、Is値０.６の水準に達していますので、これを改修してIs値０.７にする。いわば相差の部分にかかる工事費についてを補助対象にしているという考え方です。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問・要望","question":"平成７年の阪神・淡路大震災の際には、努力をしてきたというふうに、私は受けとめていたわけです。平成２０年までにすべて耐震化Is値０.７以上にするということですから、ぜひ促進をしていただきたいと、お礼を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816536?Template=document&Id=1718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":23955,"voices":89}},{"id":"h18-20060516-11","meetingId":"h18-cm05","date":"2006年5月16日","dateIso":"2006-05-16","committee":"自治制度特別委員会","time":"午後１時０５分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査、(1)基礎的自治体（特別区としての品川区）のあり方に関すること","agenda":"特定事件調査、(1)基礎的自治体（特別区としての品川区）のあり方に関すること","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"教えていただきたいのですが、最後に締めくくられているんですが、これがどういうふうに動いていくと思われているのかというのが１点。これは何で特区なのかということがわかれば教えていただきたいのと、もし、そこら辺の考えをどのように持っているかというのを教えていただきたい。","respondent":"日下部企画財政課長","answer":"それを進めていこうとしているんですが、今、非常に難しい状況にはなっていると承知しております。それから二十三区、お互いにどうしていくのか、しっかりした検討なり何なりが必要ではないかと認識をしております。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"しっかりとした自立をしてほしいということになってくると、その地域にお金がある程度落ちるような、私は必ずやってくるんじゃないかと思っています。財調自体をどういうふうにするんだ、それは要望ですけれども、何かご意見があればお願いします。","respondent":"日下部企画財政課長","answer":"大変大事な指摘だと思います。これから都区のあり方の検討ということも含めて、改めて進めていくわけですので、しっかりと対応してまいりたいと考えています。","id":"exchange-002"},{"speaker":"本田委員","kind":"質問・要望","question":"説明を１回受けただけで終わるのも何ですから、委員長の最初の問題提起ですから、こういう大きな問題を議題にあげたのは一体どういう意味か。次の委員会でこれは継続してやっていくんだというようなことなのか、大変恐縮ですけれども、その辺を最初にお聞かせいただきたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"二十三区のあり方に大きな影響を与える枠組みの話ですから、メンバーは変わりますけれども、各会派の代表ということで参加しているわけですから。委員長はどうお考えになるのか、ご意見をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問・要望","question":"ちょっとお尋ねしたいと思うのは、区長もこの１２年改革を決着させるためには、新たなスタートを都区間では切ったところですよね。どういう姿を描いているというのか、その辺の行政サイドの考えというものがもしあるならば、聞かせてほしいと求めました。","respondent":"日下部企画財政課長","answer":"私ども地方分権をしっかり推進すべきだという基本的な考え方のもとで、この間も都区制度改革等に取り組んできたわけでありますし、とらえてあります。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、いま少しその姿というものを地方自治体、国の姿を私どもにわかるように描いていただきたいなと思うんです。１,０００万人以上の大分割で、分権一括の時代には想定していなかったような現行の枠でもと思うんですけれども、どうなんでしょうね。","respondent":"日下部企画財政課長","answer":"先ほどもご説明させていただきました、最後の第４章で、非常に慎重な言い回しがされております。具体的なこれから問題を考えていくと、そういった意味では、議会でもいろいろな形で議論いただくのが大事なのではないかと受けとめているところです。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"論議があったものですから、さらにこれからそういうのが出てきたときに対処していこうと、その走りとしてご説明があったと理解いたします。東京都に対してやっている以上に、迎え撃っていかないとえらいことになるなという感じを持っているんですが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"１つには、その辺の人の配置の問題とか、そういうこともいずれは具体的な段階では抜きにできなくなってくるというふうに思います。今、私どもいろいろな形で議論してまいりましたけれども、この道州制の問題についてもとらえていくということが重要ではないかと考えております。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"お話を伺って、その権力がどこにあるかということを考えていけば、だんだんこっちの方がいいということ。例えば島根県あたりは数十万単位の県があるわけですから、そこで県になってしまっているというのは。","respondent":"日下部企画財政課長","answer":"１つの判断の基本的な考え方として出されておりますのが今の視点でございまして、つまり今の地方自治法の制度でも、都道府県の合併は可能であると。ただエリアを大きく広げればいいというだけでは済まないというのが、今回の道州制の基本的な答申の大きな柱になっているです。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"私のイメージでは基礎的自治体というのは県ではないわけですから、生活レベルの決めごと、権力を集中して。もう少しその視点でお答えがあればと思います。","respondent":"日下部企画財政課長","answer":"そういう本来、国でなくちゃできないものに絞り込む、重点化する。国と道州の問題ということではなくて、地方自治全般、基礎自治体にかかわる問題としてもしっかり受けとめていくべきだと認識しています。","id":"exchange-009"},{"speaker":"木下副委員長","kind":"質問・要望","question":"１つ質問させていただきたいんですが、それでここのところの小さな政府とか、行財政改革で道州制というのがクローズアップされてきたと思うんです。どういう形で進んでいるのかなということで、どういう形のイメージを考えていらっしゃるのか、教えていただきたいと思うんです。","respondent":"日下部企画財政課長","answer":"今回、答申で出てきたような道州よりも、州が非常に独立性が高いという１つの考え方に基づいて構成をされている。その程度のことしか承知しておりませんので、大変申しわけございませんが、よろしくお願いしたいと思います。","id":"exchange-010"},{"speaker":"木下副委員長","kind":"質問","question":"何か例があれば、どういう方向づけになるのかというのがわかれば、ちょっとイメージ的にもとられやすいかなと思って質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"特定事件調査、(2)清掃制度に関すること","agenda":"特定事件調査、(2)清掃制度に関すること","exchanges":[{"speaker":"井上委員","kind":"質問","question":"この処理基本計画のところで３つの柱が出ているわけですけれども、区としてこのことに対して、どのような働きかけをされてきているのかということをまずお伺いしたいと思います。","respondent":"中山資源循環推進課長","answer":"おっしゃられた、リサイクルの充実等々というのは、基本的には各区の同じく一般廃棄物処理計画の中で定めていくものという形になります。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"リサイクルのルートがないわけですから、区として計画を立てて、独自でするということにはならないんですよね。二十三区でそういうことこそ先に率先してやるべきではないかというような考え方はないのかということなんです。","respondent":"中山資源循環推進課長","answer":"国会でも検討されているところですけれども、現在では、処理の過程で出てくる資源の回収はより徹底していくことがこの計画の中に入っているわけです。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうルートをつくっていくことでの最小化というものも考えていくべきではないかという意見を持っていますので、二十三区としても考えていくというようなことを考えていっていただきたいということで、意見ということにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"土井委員","kind":"意見","question":"ブリキ缶の一番手間のかかる、どうしようもないのだけ集めていて、肝心なちょっとした塊になっている鉄はどこにも持っていかない。これはやっぱりどこかで考えなくてはならないことので、今日はちょっと問題提起だけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"この際ですから、これの意味する内容をある程度教えていただきたいのと、「パブリックコメント」というのは一般用語になっていますから。意味内容と日本語に訳すとどういう表現か。","respondent":"新美企画部長","answer":"あるいはいろいろな方針を出すときは、最近はホームページという大変便利なものが普及してまいりましたので、今の区としての認識です。お答えになっているかどうかあれですが。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"私も確かではありませんもので、今のお話を伺いながら、重ねて伺いますけれども、パブリックって、どっちを言うんですか。ちょっとややこしい話ですが、想定外の質問でしょうから、お答えほしいと求めました。","respondent":"新美企画部長","answer":"ちょっと最近ですが、法制化としては行政手続法の改正ということで、法的な整備が行われたということです。我々側がこういう考えをしています、その結果が計画になるとか、最終方針になるとかいう一連の手順的なプロセス的な考え方であると理解をしています。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから認識としてはきちっと、そのことを返すというふうに判断をしてほしいと求めましたが、その辺はまたいろいろな議論があるかと思います。普通はそうじゃないか尋ねました。","respondent":"新美企画部長","answer":"よりよい方針ということがあって、その中のやりとりを一定していくという、それが基本。回答式でやるのか、これはそれぞれの本体の性格と内容によることであって、絶対こうでなければならぬということはない。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問・要望","question":"財政計画の概要について確認をさせていただきたいんですけれども、今、廃止をしていくということを言っていらっしゃったのかということが２つ。３つ目にこの計画の中で、費用が上がるほどのものではないということなのか、ちょっとその辺の説明をほしいと求めました。","respondent":"中山資源循環推進課長","answer":"２４時間制で３交代で運転管理というのをやるんですけれども、職員数を３割ぐらい減らしていくというのがご説明で最初に申し上げた点です。新たに平成２２年度から、平成１８年度からずっと下がってくるわけですが、平成２１年から平成２２年にかけてはまた財政規模が上がります。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"お聞きしたいんですけれども、廃プラスチックの焼却が区長会で１年前倒しで確認したのか、それは区長会で決めたということですから。近々のことで、今の時期でないと、このことについてお伺いできないので、お願いします。","respondent":"中山資源循環推進課長","answer":"平成１９年度の２年間の中でモデル実施を行い、公表していくという方針だったわけですけれども、その段階で名乗りが挙がったのが４区だったです。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"廃プラスチック見直しの撤廃を求めて、区長会会長である高橋区長に要望書を提出するということで、なかなかどういう場面なのかということ。さまざまな条件がある中で、不安を抱える区民がいる中で、担当課長レベルで決めたということのポイントはどういうところなんか尋ねました。","respondent":"中山資源循環推進課長","answer":"区としてモデル収集は方針をとったですから、そのことを区の中で分別を変更する地区を設けるということについては、先ほど申し上げた一般廃棄物処理計画の変更等々というところでやっていくためのモデル収集についての方針決定を現在していますが。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"したら、一般廃棄物の処理計画は品川区は２０００年につくっただけで、そういったところでの是非を問う議論というものも必要だと思うんです。５月３１日に区からの説明会というのが第１回というか、その後のスケジュールなんかはどんなふうに計画をされているのか、お伺いいたします。","respondent":"岩崎環境清掃事業部長、中山資源循環推進課長","answer":"是非を問う議論というのは、そういうことで手順を追って進めてまいります。ですので、是非ではなくて、そういうふうにご理解をお願いしたいと思います。一般組合の方へのご説明ですけれども、区民の方への分別変更、こういうモデル収集も行う状況も含めたご説明をしていくという形です。","id":"exchange-022"},{"speaker":"木下副委員長","kind":"意見","question":"１年間、本当にありがとうございました。本当に理事者の皆さん、委員の皆さん、１年間ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/148286?Template=document&Id=5594#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":33573,"voices":55}},{"id":"h18-20060516-16","meetingId":"h18-cm05","date":"2006年5月16日","dateIso":"2006-05-16","committee":"街づくり特別委員会","time":"午後１時０３分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"東急目黒線（武蔵小山駅周辺・西小山駅周辺）に関すること","agenda":"東急目黒線（武蔵小山駅周辺・西小山駅周辺）に関すること","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今日、いただいたカラーの資料ですけれども、この資料自体はどこの資料なんでしょうか。どこの会議資料といいますか、それをちょっと教えていただきたい。","respondent":"浜脇街路事業担当課長","answer":"私ども、これは都、区、それから東急等の連立に関する事業の事務連絡会というのがありますが、その中で使われたものでございまして、これが一番最新の資料ですので、皆様にお配りしたものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっとそこがどういう計画なのか、進んでいるのかどうか、伺えればと思ったんです。解消時期は７月２日なので、３０号線はどういう計画なのか、計画のとらえ方があれば教えていただきたい。","respondent":"浜脇街路事業担当課長","answer":"これは、今日も行ってみていただいて、歩く場所にあるんですが、一部３０号線で、駅の周辺で狭いところがありますので、それで区の目黒区の方が主体となってやっているものでございまして、それも今回拡幅しながら、７月からやっていくですので、それが入っているものです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"要は３０号線の計画はどういう状況になっているのか、現状の１１メートルを１５メートルにするというのではないかいうのは推測できるんですけれども、現状を教えていただきたいんですけれども。","respondent":"浜脇街路事業担当課長、宮崎委員長","answer":"今、ありましたように、目黒方の方が１１から１５メートルで、進捗率が約半分、５０％前後というふうに言ってあります。約５０％ぐらいの進捗というふうに伺っております。 ほかにございませんか。この後、視察の予定をしておりますが、以上で特定事件調査を終了いたします。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/847285?Template=document&Id=6324#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":3921,"voices":17}},{"id":"h18-20060517-14","meetingId":"h18-cm05","date":"2006年5月17日","dateIso":"2006-05-17","committee":"行財政改革特別委員会","time":"午後１時０２分～午後１時１９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"行財政改革に関することのうちの、(2)の行政評価の検証に関すること","agenda":"行財政改革に関することのうちの、(2)の行政評価の検証に関すること","exchanges":[{"speaker":"沢田委員","kind":"提案","question":"行政評価は国会という話ではないですけれども、反対してきたことがあるので、せめてそれだけは入らないかなという気がするんです。もっと広範な区民の声が反映するような住民参加の仕組みが必要なんじゃないかということを提案させていただいたのですが、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"一応そういう段取りを含めて来ていますので、あまり無理を言うつもりはないんですけれども、それならばこういうことで決めたので、ご了承願いますというのならいいんですけれども、ご意見ございませんかというから、ならありますよということですので、一応発言だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"意見が出たので、議長が間に入って調整をしてやるということを言ったにしては、かなり期間がたっていると。６月議会ということになれば、今までどういう動きを何回してきたのかということを聞きたいなと思ったのですが、委員長は何か聞いていますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"中島委員","kind":"質問・要望","question":"今、委員長のほうから、積極的に議長が調整をされているというご発言をいただきました。どういう点で積極的にとおっしゃったのか、ちょっとその辺だけお聞かせいただきたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中島委員","kind":"質問・要望","question":"出された以上は、ぜひ、その後の経過をまた聞いていただきたいと思うのです。到底積極的とは思えないということがありますので、ぜひ、その辺のところをよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原副委員長","kind":"質問","question":"諸先輩方の質疑もお伺いしまして、あと、任期は１年ですけれども、何かもう１回議員になりたいなと、改めて思うような委員会でありました。ほんとうは副委員長ですからもっともっと補佐しなくちゃいけなかったんですけれども、委員長、ほんとうにどうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"川西副委員長","kind":"質問・要望","question":"民間委託、行政評価、区民の要望を取り入れて、財政効率を上げながら、適正運営という大変大事な委員会であったと思います。今、藤原副委員長もおっしゃったように、あまり委員長を助けられなかったのですが、ほんとうにありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/218784?Template=document&Id=5798#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":5231,"voices":19}},{"id":"h18-20060519-8","meetingId":"h18-cm05","date":"2006年5月19日","dateIso":"2006-05-19","committee":"建設委員会","time":"午前１０時０２分～午後３時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"の「都市計画公園・緑地の整備方針」","agenda":"の「都市計画公園・緑地の整備方針」","exchanges":[{"speaker":"堺委員","kind":"意見","question":"この戸越公園の未供用部分の現状の国文学資料館に関連して少しお尋ねしたいのは、どういうふうにここをしようとしているのかということですね。どうするのかということなんですが、その辺をお願いしますとの意見を述べました。","respondent":"松代管理工事課長","answer":"きょう説明しました、優先的に整備するです。その後の整備内容等についても、今後、詳細に詰めていきたいという状況にあります。","id":"exchange-001"},{"speaker":"堺委員","kind":"質問","question":"さっきも申し上げたように、隣接には戸越公園がありますから、私が一番最初に一般質問で取り上げたのは昭和６３年か６２年でしたね。当時の区長も、一体化した公園にしたらどうでしょうかというお話を申し上げたときに、そういう方向で考えておりますとおっしゃったんですね。","respondent":"松代管理工事課長","answer":"払い下げということで交渉してまいりますが、区への譲渡というような正式の回答は、向こうからは出されておりません。その回答があって、詳しく内容を詰めていくということになろうかと思いますが、そういうスタンスで引き続き交渉していきたいと考えているところです。","id":"exchange-002"},{"speaker":"堺委員","kind":"質問","question":"今後１０年の間に、予定通りだと平成２０年２月には移転するということですから、なるべく早くという希望がある。事業計画が２７年ですから、まだ７年間期間があるから、どうぞひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"具体的方針がまだ決まっていないということなんでしょうかね。実際にある都営住宅をどうしようかという具体的な方針が決まらずに整備区域に指定するという考え方の、そこだけ聞かせてください。","respondent":"松代管理工事課長","answer":"東京都の方に問い合わせをしましたところ、東京都の方では、この民生住宅については、１８年度、廃止の方針決定をしたというように聞いてございまして、今後、それに基づいて、今現在住んでいらっしゃる居住者の方と移転等の折衝に入っていくという予定にあると聞いてあります。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"小山台公園のところでちょっとよく理解していないところがあるんですが、ここは、住民の方たちと、ここではないけれども、公社だと思うんですけれども、裁判があるエリアのところとは全然違うということでよろしいんか尋ねました。","respondent":"松代管理工事課長","answer":"訴訟のところの区域とは全く違うところです。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"3)のところの民設公園制度というところで、そういうのに該当するようなところを把握はされていると思うんですけれども、そういうような場所というのは品川区にもあると認識されているんか尋ねました。","respondent":"松代管理工事課長","answer":"まだ現在検討中だということですので、１歩踏み込んで、このように受けとめているところです。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"今のところでは、どのぐらいの件数があるのかということと、こういうところに民間とか企業の人たちがつくるのか、そこにまた何らかの形で協力というか、連携をとるという仕組みなのかどうなのかというところはどうなんか尋ねました。","respondent":"松代管理工事課長","answer":"具体的なそういう対象となるようなケースは、まだ具体的には把握はしてございません。２点目に、具体的なものとしてはまだお示しすることはできませんし、具体的な細かなところでは検討してございません。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ、形を変えるようなことのないような残し方をしてほしいという要望がたくさん届いていますので、その辺を押さえておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"の「東京河川改修促進連盟」の総会および促進大会の開催","agenda":"の「東京河川改修促進連盟」の総会および促進大会の開催","exchanges":[{"speaker":"菊地委員","kind":"確認","question":"一つだけ確認させてもらいたいんですけど、この委員会での前段での資料の配布というのは、これも不可能なんでしょうか。ちょっとそこだけ。","respondent":"原田下水道河川課長","answer":"それは、案ということで事務局でもある程度中身は把握しておりますので、特に不可能というものではございません。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、会場で配られる資料を前段にこの委員会で配布をするということは、今後可能だということでとらえてよろしいんか尋ねました。","respondent":"原田下水道河川課長","answer":"我々としては案ということでいろいろともらっていますので。必ずしも本番と全く同じ資料というわけではないんですが。","id":"exchange-010"}]},{"id":"topic-03","title":"中央環状品川線の事業説明会","agenda":"中央環状品川線の事業説明会","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"環境の問題ですとか、そういったことの問題についての質問に答えられる方が都なり株式会社の方から出てくるということでとらえていいのかどうか。ちょっとこの３点だけ聞かせてください。","respondent":"阿部都市計画課長","answer":"１点目の説明の問題ですけれども、品川線の整備推進室という実施機関ができましたので、ここが当然所管して説明していく。３点目の、３カ所以外にあるのかですけれども、現在、この３カ所でやる予定だというふうに聞いております。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"今、ちょっと地元のところで、沿線５０ｍ、半径なのか直径なのかわからないですけど、要は、山手通りに沿って、帯状に５０ｍの範囲というお話ですね。","respondent":"阿部都市計画課長","answer":"今回の事業説明会につきましては、事業が実施されますと、例えば建築の制限とか、そういう権利上の制限が出てくるわけです。今回の事業説明会につきましては、今申し上げたとおり、片側５０ｍ範囲で説明会をするというふうに聞いています。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"前段でお聞きしたときに、当然、そのことをお聞きした環境問題についても質問は出るであろうということを前提にしての話だと思うんですね。ですから、都に対しても、こういうことはしっかりと伝えてほしいと思いますので、要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"この説明会がありますということは、区としてはどのような広報を予定しているのか。どういうところでこれが住民の方に、終わってしまった」ということはよくあるんですけれども、それはどういうふうにされる予定か尋ねました。","respondent":"阿部都市計画課長","answer":"区のお知らせ「しながわ」の５月２１日号で、この説明会をやるということを周知する予定ですので、広報を使いながら周知をしていきます。当然東京都の広報に載せるというふうに聞いてありますが、そういう意味では、区民に広くこの説明会を周知するという考えです。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうふうに、これだけぱっと見ても、気がつかれるようなニュースになっていると思いますので、そういう形で、広く。近隣の広報「しながわ」を置いている場所とか、そういうＰＲすることも考えていただくような手立てをしていただきたいと要求したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-04","title":"の大崎駅東口第３地区地区計画（Ｃ地区）の変更","agenda":"の大崎駅東口第３地区地区計画（Ｃ地区）の変更","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"改めて、この東口第３地区に投入される補助金総額を教えていただきたいのと、その中で、この大崎、Ｃ地区はどの程度なのかを教えていただけますか尋ねました。","respondent":"上野都市開発課長","answer":"第３地区、再開発事業につきましては、今、手元にございませんので、後日改めてご説明したいと思います。第３地区のＣ地区につきましては、補助金を投入する予定はございません。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"それはどういうものなのか。あわせて大きな変更となるのかということが、ここがちょっとわからないんですけど、どういうことなんか尋ねました。","respondent":"上野都市開発課長","answer":"従来、東口第３地区Ｃ地区につきましては、地区計画の方針だけが定まってございました。あくまでもＣ地区に関連する部分についての変更です。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"ということは、大崎の第３地区計画のこういったものと比べていくと、この第３のページにあります、拡幅だとかそういったところが、以前もう少し違ったものが、新設か、幹線の１号だなという部分で、一部新設して、あるいは前の段階で広くしますよということで理解してよろしいんか尋ねました。","respondent":"上野都市開発課長","answer":"延長関係につきまして、一部変更がございましたので、網かけとしては全体のところに網がかかってありますけれども、延長についての一部変更でございまして、それにつきましても、説明会では詳細に合わせて事業者によって説明される予定です。","id":"exchange-018"}]},{"id":"topic-05","title":"の二世代住宅取得等助成および環境共生住宅助成の募集","agenda":"の二世代住宅取得等助成および環境共生住宅助成の募集","exchanges":[{"speaker":"井上委員","kind":"質問","question":"申し込みのところのページで、公開抽選というようにありますけれども、これはどういう形で、どういうことか尋ねました。","respondent":"齋藤住宅課長","answer":"会議室で、皆さんいらっしゃる前でガラガラポンということです。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"ちなみに、ほかにいろいろなモニターとか、作文があったりするようなところ、この場合には、そういうことがないので簡単にできるのかもしれないですけれども、ほかで、区の方で公開抽選というのをやっているという事例をご存じであれば、教えてほしいと求めました。","respondent":"齋藤住宅課長","answer":"区営住宅、区民住宅が公開抽選です。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965541?Template=document&Id=3848#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":14065,"voices":68}},{"id":"h18-20060605-6","meetingId":"h18-cm06","date":"2006年6月5日","dateIso":"2006-06-05","committee":"区民委員会","time":"午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"番目、事務事業概要を行います。 進め方でございますが、説明・質疑を事業部ごとに一括で行いたいと思います。 この事務事業概要につきましては…","agenda":"番目、事務事業概要を行います。 進め方でございますが、説明・質疑を事業部ごとに一括で行いたいと思います。 この事務事業概要につきましては…","exchanges":[{"speaker":"南委員","kind":"質問","question":"商店構成が随分変わってきまして、パトリアというあれになっているようなんですけれども、随分あいているスペースもあるんです。ああいう状況について、区ではどういうふうにとらえていられるのか、ちょっとその辺だけ伺っておきたいと思っているんです。","respondent":"金子産業振興課長","answer":"あるいは品川シーサイドの駅のところに、それ以外の店舗もありますから、そういったところを利用されている方も多いと認識しております。私どもとしましても、どんな手立てがあるかということは検討しなければなりませんが、何らかの検討をしていく必要はあるかなと思っています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"それからパトリアに出店している個店の育成というのか、そういう観点というのは、どういうふうに考えているのか。そこもちょっと、さっき質問すればよかったんですけれども、。","respondent":"金子産業振興課長","answer":"パトリアは、ちょっとうろ覚えで恐縮ですけれども、あそこ自体が商店のグループを構成しております。私どもの何らかのメニューが考えられれば、何かありましたら、ご案内等をしていただければと思います。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"私個人の感覚で申しわけないんですけれども、あそこの個人商店には、あまり魅力を感じるということが少ないんですよね。ですから、個店の方々からどういうご相談があるかわからないですけれども、配慮していただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"林（和）副委員長","kind":"質問","question":"そして平成１７年度には１８件の過料を取っているわけですけれども、どういうふうにして、どうやって取っているのか。ちょっとそこのところを説明を求めました。","respondent":"金子生活安全担当課長","answer":"内容的には、いろいろ指導をしても、それに従わないような悪質な過料に直に匹敵するような方が少なくなっていると考えております。具体的には、徴収要領につきましては、生活安全サポート隊の指導の回数を定期的に計画しまして、適宜指導しています。","id":"exchange-004"},{"speaker":"林（和）副委員長","kind":"質問","question":"その取った状況といいますか、それはわからないんですか。よっぽど言うことを聞かないから、１８人なら１８人から取っているわけですから、指導しても全然言うことを聞かない、その経過というのは。","respondent":"金子生活安全担当課長","answer":"一つは、明らかに吸ってはいけない地域であることを認識しているにもかかわらず吸っているような方、指導も含めて過料を取っているところです。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"今、問題になっている保険料の免除の問題、これは、先ほどのご説明では、区のレベルでこの事務をやっているんですか。どこかの２３区で名前が挙がっているところもあるけれども、区は全く関知しないと理解してよろしいんか尋ねました。","respondent":"原国保年金課長","answer":"例えば回答がない場合に、返ってこない方について免除申請の意思があったということで、申請を社会保険事務所のほうで行ったです。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247239?Template=document&Id=2458#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":39177,"voices":74}},{"id":"h18-20060605-7","meetingId":"h18-cm06","date":"2006年6月5日","dateIso":"2006-06-05","committee":"厚生委員会","time":"午後１時０３分～午後４時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"いろいろお聞きすることもあると思いますが、なるべく活発な委員会になるように頑張っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"三上委員","kind":"意見","question":"どうぞよろしくお願いいたします。久しぶりの厚生委員会ということで、しっかり取り組んでまいりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"三村委員","kind":"質問・要望","question":"生活者ネットワーク所属の三村りつ子です。私も厚生委員会は今回初めてですので、ぜひ皆さんに知識をいろいろ教えていただきながら、。","respondent":"古川児童保健事業部長、谷田部健康課長、諸岡児童課長、小林保育課長、高橋幼保一元担当課長、青山品川区保健所長、山岡品川区保健所衛生課長、倉橋品川区保健所保健サービス課長、宮本品川区保健センター所長、高橋品川区保健センター衛生課長、川口品川区保健センター保健サービス課長、太田品川区保健センター大井保健相談所長、木下福祉高齢事業部長、蓼沼高齢福祉課長、冨岡高齢事業課長、上山介護保険担当課長、西島障害者福祉課長、志村生活福祉課長、福島福祉高齢事業部副参事","answer":"私から庁内の課長について、ご紹介を申し上げます。健康課の谷田部課長です。谷田部です。児童課の諸岡課長です。諸岡です。どうぞよろしくお願いいたします。保育課の小林課長です。小林です。幼保一元担当の高橋課長です。高橋です。私から保健所の幹部職員をご紹介申し上げます。山岡衛生課長です。山岡です。どうぞよろしくお願いいたします。倉橋参事保健サービス課長事務取扱です。倉橋です。私から保健センターの幹部職員をご紹介します。高橋衛生課長です。高橋です。","id":"exchange-003"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"確認だけ１点させてほしいと求めました。文教委員会との絡みで、どこまでお話ししてお答えできるものかという確認だけしたいと思います。","respondent":"小林保育課長","answer":"基本的には、人事、任用関係、それから研修等の一部につきましては、教育委員会指導課に属する部分がまだ残されておりますが、運営を含めまして、基本的には幼稚園はすべて保育課、当厚生委員会でご審議いただきたいと考えております。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"文部科学省での規定があるかと思いますけれども、今年の動きとして、こちらのほうで議論できる方向にはないという理解でよろしいでしょうか。何か大きく変わることはないと考えていいということでよろしいか尋ねました。","respondent":"小林保育課長","answer":"任用制度等について、例えば年度内という近い視野で大きく制度が変わるというふうには聞いておりません。ただ、研修等も含めて、一体の運営の中に密接不可分ですので、基本的には当委員会でご審議いただきたいと考えております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、前立腺がんが平成１８年度から始まるということで、先ほど報告がありましたけれども、この内容も教えていただきたい。今年の４月から胸のレントゲンが撮れなくなったということを言われているんですけれども、実際にどうなっているのか教えてほしいと求めました。","respondent":"諸岡児童課長、谷田部健康課長、倉橋品川区保健所保健サービス課長、小林保育課長","answer":"品川区内における出生率ですが、２００４年の統計ですが０.８８です。それから、前立腺がん検診の内容ですけれども、５５歳以上の男性を対象に、区民健診と一緒にやっていただきます。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日は事務事業概要ですから、ここの中で論議ができるような審議の場をぜひつくっていただきたいと要望をさせてほしいと求めました。相談件数がどんどん増えてしまって、その辺の体制は充実しているのか、その辺のところもあわせてお聞かせいただけないか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"対応の充実ですが、もともと保健所では事業の大きな柱が精神保健ということでございまして、母子保健等と並んで力を入れている分野の一つです。先ほどもご説明しましたけれども、複雑困難な相談案件が出てきておりますので、こちらのほうに重点的に対応するように努力しています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後にもう１点ですけれども、児童センターの問題ですけれども、中間のまとめが厚生委員会の中で報告がかなり厚い冊子で配られました。まとめはいただいていないし、児童センターのあり方についてのまとめの報告を今後していただきたいということを要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"三村委員","kind":"質問","question":"児童虐待についてお伺いしたいんですけれども、区に児童虐待の相談対応が移管されてきて、件数はどのように推移しているのか。現場はどのように対応されているのか、また課題等が見えてきていれば、その辺についてもお伺いしたいと思います。","respondent":"諸岡児童課長","answer":"２００件弱ですが、このような件数の虐待に係わる相談があったです。ネットワークを生かして情報交換等を行い、その中での経費負担等を行いまして、虐待等に対応していきたいと考えているところです。","id":"exchange-009"},{"speaker":"三村委員","kind":"質問","question":"実際の現場で対応されている方への研修とか、その辺のことについても説明を求めました。","respondent":"諸岡児童課長","answer":"子育て支援センターあるいは児童課の児童相談担当、そしてまた地域に密着したということで児童センターも相談窓口として開設しています。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"今日は事務事業概要の説明ということですから、大きく聞きません。全国の統計として１.２５という数字が出ている以上は、そこの数字は出してもいい数字じゃないの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"早く発見されて、その辺の連携とか仕組みがどうなっているのか、いろいろな事業所のところの連携がどうなっているのか。それから、早期発見、早期治療がどう進んでいるのかお聞かせほしいと求めました。","respondent":"諸岡児童課長","answer":"療育相談につきましては、児童課の品川区家庭あんしんセンターにあります子育て支援センターで相談業務として受けております。さらには、その内容によりまして、各セクションで連携を取りながら発達相談関係につきましては進めているところです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事務事業概要の１１ページのところで、今まで保険料５段階のところでは、構成比についても教えてほしいと求めました。この間、第２段階以外の方は皆さん値上げになったわけですけれども、その辺の苦情の件数と内容についてお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"保険料に関するお尋ねですけれども、新しい住民税の算定による通知につきましては、７月に通知をする予定です。それから、介護保険制度の保険相互扶助というような説明をさせていただいて、およその方はご理解をいただいていると認識しております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"構成比は７月に通知が行って、そこまでいかないとわからないということなので、わかった段階で教えてほしいと求めました。こういう形で半期ずつまとめて、ぜひ１７年度のまとめという形で報告もいただきたいということと、これは要望とします。","respondent":"冨岡高齢事業課長","answer":"正確な数はつかんでおりませんが、去年９月段階で４４件という数字をつかんでおります。これからそれぞれの方にどのように対応していくのかですけれども、高齢者住宅に入るにはそれなりの対応をするという形で。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"かなりの減収になっていて、その辺のところの把握と、それに対しての品川区の対応はどうなっているのかということが１点。地域生活支援事業が１０月１日から始まるにあたって区の考え方と、ここはどういう形でされるのかということも教えてほしいと求めました。","respondent":"西島障害者福祉課長","answer":"地域生活支援事業は１０月実施になりますので、今定例会で条例化するとなればかけなければいけないことになりますので、今定例会には間に合いません。事業の性格から言いまして、十分要綱で対処できるですので、品川区は要綱でいく考えで現在検討を進めているところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その辺のところは区としても把握していただきたいし、十分なサービスが受けられるように、ぜひよろしくお願いしたいと思います。中間の段階で報告をしていただいて、この委員会の中でも議論ができるような形でお願いしたいと思うんですが、その点を説明を求めました。","respondent":"西島障害者福祉課長","answer":"６月下旬ぐらいに第１回目の委員会が開ければということで、現在は進めているところです。基本計画検討委員会の検討の推移を見ながら、ご意見を承る機会がございましたら、またそれは委員長と相談してご報告をすることもあろうかと思います。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、よろしくお願いいたします。傍聴は可能な委員会になっているのでしょうか、そのことだけ最後にお聞かせほしいと求めました。","respondent":"西島障害者福祉課長","answer":"結論だけ申し上げますと、これから検討をすることになると思います。そういう意味ではプランバシーの問題とか、その辺は最終的には委員会で検討することになると思いますが、今後検討させていただきたいと考えています。","id":"exchange-017"},{"speaker":"木下委員","kind":"質問・要望","question":"条例だとか法律の改正で影響がある部分かなと思いまして、自分自身も確認しておきたいのでお聞かせ願いたいと思います。そういう方が９０年代の入管法の改定で日系人であれば永住することができる、結婚された方ですとか、いかがか尋ねました。","respondent":"蓼沼高齢福祉課長、志村生活福祉課長","answer":"火災等に備え、生活の安全を図る必要があるという状況を鑑みて設置しているということで、必要に応じて設置してきているところです。恐縮ですけれども、実績等については手元に資料がございませんので、その辺はご容赦願いたいと思いま… 先ほどご説明したとおり、報告は求められますけれども、その中で外国人をというのは特にございません。そうではございませんけれども、そういう傾向が多くなっているですので、数のほうはご勘弁願いたいと思います。","id":"exchange-018"},{"speaker":"木下委員","kind":"質問・要望","question":"苦慮されているというお話も出ましたので、これから問題にならないとも限りませんので、一応ある程度把握していただければありがたいと考えています。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけお聞きします。６６ページの高齢者住宅対策の中で(2)の高齢者住宅対策事業、1)住宅あっ旋のところで、その辺だけ確認を。","respondent":"冨岡高齢事業課長","answer":"その保証会社と契約を結んでいただいて、家賃の半分を保証金として取りまして、それを区が５万円を限度に助成するという制度です。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それから、５月１５日の厚生委員会は前期になってしまうのではっきりわかっていなかったんですけれども、これは区の広報として出ているんですか。例えば、今までのあっ旋事業のパンフレットに載っているのでしょうね、その辺はどうなんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"４月から制度化させていただきまして、これから徐々にですけれども、周知に努めてまいりたいと考えています。６月１１日号の広報「しながわ」に出す予定です。","id":"exchange-021"}]},{"id":"topic-03","title":"続きまして、報告事項","agenda":"続きまして、報告事項","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"施設の件について質問しますけれども、２階の畳の部屋はいつ抜けるだろうという状況だったんですが、安全面はどうなのかということです。どういう体制を取られているのかということは、６月に始まるということは、それについてもう少し詳しく教えていただきたいということ。","respondent":"蓼沼高齢福祉課長","answer":"こちらの施設は確か築５０年前後経っていたと思いますので、その辺については耐震補強等もして、安全に支障のないように改修工事をしております。","id":"exchange-022"},{"speaker":"西本委員","kind":"確認","question":"築５０年ということで、それなりに補強したということですので、きちんとしていただいただろうと信じております。その点を確認させてください。","respondent":"木下福祉高齢事業部長","answer":"そういうのは基本的に考えないということでありまして、あの中で新しい活動をしていくことはもちろん可能だと考えております。そういうような新しい団体が徐々に増えていって、あそこにおける支え合い活動がより広がっていければということが基本的な考え方になっているです。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"この地域の人間ですから、それから団体の方たちが地域にアクセスする術がなかなか難しいから広がっていかないという部分もあると思うんです。ある程度、一定の評価の方法も含めて運営を進めていかないと広がっていかないのではないかということがありますが、いかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"ただ、その趣旨について説明させていただきながら、賛同していただける方については徐々にあの輪の中に入っていただく形を考えております。したがって、社会福祉協議会が適切に相談に乗りながら、その輪の中に入っていただくような形を今後取っていくという考え方です。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に一つお願いがあるんですが、あそこにサクランボの木があるのをご存じですか。そういうものもありますので、切らずに有効活用していただきたいということで、その辺はお約束していただいてよろしいか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"その辺の趣旨を十分踏まえてやっていきたいと考えております。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285470?Template=document&Id=3146#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":57825,"voices":129}},{"id":"h18-20060605-8","meetingId":"h18-cm06","date":"2006年6月5日","dateIso":"2006-06-05","committee":"建設委員会","time":"午後１時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"伊藤委員長","kind":"確認","question":"建設委員会所管事項のうち、街づくり特別委員会との仕切りにつきましては、既に調整・確認をしておりますので、ご了承ください。理事者の説明をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"これからの課題だと思うんですが、一つだけ疑問に思ったのでお伺いしたいんですが、３３ページのしながわ水族館の運営が掘削指導係というふうになっているんですが、こういう係とか、そういう所管を決める時点で、これはどういう理由からこういうふうになっているんか尋ねました。","respondent":"藤田道路公園課長","answer":"組織の中で、そこから事務を分担しているということで、そういう名称になっているものです。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"そうすると、この掘削指導係というのがここの庶務係というようなことをされているということでいいんですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一つは交通安全事業のことなんですけれども、初めから聞いてあれなんですけれども、一から伺いたいのは、大崎駅周辺地区再開発事業の目的ですね。一からの質問になるかと思うんですけれども、そこを教えていただきたい。","respondent":"上野都市開発課長","answer":"ただいま事務事業概要説明の中で申し上げましたとおり、昭和３０年代後半以降、その跡地にマンション等が建設される動きがあった。以上です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"経緯は先ほども伺ったんですけれども、この再開発事業で進んでいる商業地だったり、分譲だったり、賃貸だったり、ありますよね。それがどのような住民需要や必要性があってそうなっているのかというところを教えていただきたいんですけれども。","respondent":"上野都市開発課長","answer":"区の考えだけでなくて、地元ではまちづくり推進協議会などができまして、これまでさまざまな地区での再開発が行われてきたところです。お手元の６９ページ、あるいは７３ページに、これまで区と連携しながら再開発事業を進めてきたです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、大崎駅東口第３地区だったら、業務棟、分譲、賃貸があるわけですから、そこを伺っているので教えていただきたいんですね。同時に教えていただきたいのは、例に出した大崎駅東口第３地区では、例えば分譲住宅や賃貸住宅の最多価格帯というのは幾らなんか尋ねました。","respondent":"上野都市開発課長","answer":"賑わいを形成するとか、活性化されたまちをつくるだとか、そういったものを目指すための具体的な用途として位置づけられているものです。それから、今、価格につきましては手元に資料がございませんので、後ほど資料を示します。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたかったんですけれども、どうしても、そこを啓発するのはすごく大事なことだと僕自身思っています。それはそれぞれありますけど、教えていただきたいんですけれども。","respondent":"上野都市開発課長、松嶋交通安全担当課長","answer":"それぞれの幅広い需要層がありますけれども、そういったものの中での購入される方がおられるということで、売り手として販売されているものです。 例えば交通安全のキャンペーンだとか、安全講習、そういったもので実施をしています。特に安全管理者講習会とかそういったものは定期的に実施をしておりまして、副管理者、講習会というものを継続的に実施しています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"は装飾品というんですか、シールを張ったり、そこをぜひ強めていただきたいなと思っているんですね。この間交通安全協議会ですか、どういう問題点が出されているのか、なかなか僕自身も知る余地がないんですよね。","respondent":"上野都市開発課長、松嶋交通安全担当課長","answer":"ある一定の需要を調査して、その需要があるということを見込んで販売しているわけですから、販売されているものについては適切だと考えております。 件数につきましてはちょっと資料がありませんので、この場ではお答えできませんけれども、現実に実施をしているです。これも引き続き、実のある協議会として、今後も実施をしていきたいと考えています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"これを、議事録を含めて原則公開して、問題点や注意をみんな自身が共有できるような取り上げ方をするべきだと思うんです。これだけ答弁をお願いします。","respondent":"松嶋交通安全担当課長","answer":"例えば、交通安全対策会議は７月に実施をするんですけれども、これは基本計画として、現実に公表をして、冊子として出しています。交通安全協議会の方につきましても、これは交通安全運動の今回の重点施策だとかそういったものをあわせて公表して出しております。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"１７８名というところで、区の予算ですとか人事がここで入っているんだなと思って、何となくわかりました。１８年度は１７８名ということで、その辺の概要を教えていただきたいのと、概要だけ教えていただきたいんですけれども。","respondent":"松代管理工事課長、片田建築課長","answer":"私が一応庶務の方も兼ねておりますので、概要をご説明申し上げます。そういったものがこの中には、細かな数字はわかりませんけれども、そういった有資格者を職員としております。 管理工事課長のほうから有資格者ということでの説明がございましたけれども、あるいは一級建築士といったような資格があります。ただ、それ以外の形と資格をもって区長から任命されれば、きちんとした業務ができるものです。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"民間から区の方に建築確認の申請がふえたというようなお話だったんですけれども、今も建築確認が区のほうに増えてきているという関係で、ちょっと説明をいただきたいんですけれども。","respondent":"片田建築課長","answer":"先ほど概略説明させていただきましたけれども、建築物確認申請等の件数ということで、平成１７年度までの過去３年間の実績を表示しています。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"確認","question":"区側の確認申請にかかる体制じゃなくて、体制が実際にどういうふうになってきているのかというのをあわせてお聞かせいただければ。１.５倍から２倍ぐらいの感じに増えているのかなと思うんですけど、体制もどうなっているのかと心配なんですが、そこら辺のところどうでしょう。","respondent":"片田建築課長","answer":"３２名ということで、トータルで３３名という布陣の中で、構造の相談に当たっているという状況です。審査１係、２係という体制を組んでおったんですけれども、現実的に十分対応できるものと考えています。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"これは私も幾つか質問していますが、１３０ページの入居者数のほうを見ると、ここら辺の考え方というのが聞きたいなと思ったんですけどね。ここのところをちょっと、改めて考え方というのを聞きたいんですけれども、どうでしょう。","respondent":"齋藤住宅課長","answer":"低所得者層向けの公営住宅ですが、東京都、区として実施しています。今後、現在の住宅を改築する場合には、容積率を可能な限り利用して、高層化で対応したいと考えております。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"２３区の中の一定水準というようなお話ですが、何か指標というか、そういうものというのは何かあるんか尋ねました。","respondent":"齋藤住宅課長","answer":"これに対してすごく地域差がありまして、公的住宅につきましては４分の１近くを占める区もあれば、１割に満たない区もありますので、地域特性、住宅取得がどれだけ可能か、こういった状況でも変わりますので、指標という関係ではございません。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"例えば２３区の中では地域格差があるけれども、確かに、用地確保等難しい。少ないところと比べれば、そこら辺の、ほかの自治体と比べる必要性というのはなぜなんか尋ねました。","respondent":"齋藤住宅課長、福田まちづくり事業部長","answer":"したがいまして、４３億円で４６戸。建設すること、費用対効果を考えますと、なかなか四十数戸のために４３億円のお金を投入すべきなのかどうなのかということです。現在の品川区を取り巻く環境にとって傾聴すべきものだろうと考えていますので、そのような方向で考えるときではないかと考えております。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"意見","question":"これは一体どういうふうに考えたらいいか。その辺はどうなんでしょうとの意見を述べました。","respondent":"福田まちづくり事業部長","answer":"この住宅付置義務によって設置をされた住宅数、その後区民住宅の建設、借上げなども進みました。ことしの３月３１日をもってこれを廃止したものでございまして、官から民へ、公的供給から民間供給へという流れとは相当違う話です。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問・要望","question":"都営住宅、区営住宅は非常に要望が強いというのははっきりしているわけで、政治そのものが何のためにあるのかというのが問われる話だと思います。増やしていくこともあるみたいな、そういう説明だったと思うんですけど、ストックをもう一度確認していきたいんですけれども。","respondent":"齋藤住宅課長","answer":"１３１ページの都営住宅の区移管のところで、品川区が東京都から都営住宅を移管できる場合は、戸数増など将来の利用可能性が高い団地を一つの目安としています。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"１階、２階は障害者用の施設になっていますけれども、容積率をもうちょっと増やすことができたんじゃないか。あまり高いものを建てると、そういうふうに考え方が変わってきたのかなと思うんですけれども、そこのところはそういうことでよろしいか尋ねました。","respondent":"齋藤住宅課長","answer":"建て替え時の件はそのとおりです。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"今までの議論の経過から言うと、ちょっと気になるんですけど、以前あった構想というのがまた復活したというふうに考えていいのかどうか。どうなんか尋ねました。","respondent":"上野都市開発課長","answer":"現在、ＪＲの社宅を中心とする地域についても検討していますけれども、将来の開発に向けてのあり方についての検討をしています。この南側の広町の社宅を中心とする地区についての検討はやってみようということで、まずその中の南側の一角についての具体化の検討を、しているです。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"広町地区の開発の問題は、広町地区開発に当たっては、品川区としてはどういうことを期待しているんですか。そこら辺の区の側の動機というんですか、そこのところを改めて聞いておきたいんですが。","respondent":"上野都市開発課長","answer":"区といたしましては、大井町全体の活性化に寄与できるようなまちづくりを進められるように、品川区の中心核にふさわしい構想の実現に向けての検討をしていくといったところです。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"この広町地区の開発の品川区とＪＲ東日本との話をしているところなんですけれども、全体のニーズ調査とか、住宅も含めて、オフィスだとか、そういう動きはどういうふうにされていますかとの意見を述べました。","respondent":"上野都市開発課長","answer":"ある地区の開発を行うに当たっては、さまざまなレベルでの需要動向の調査もあわせて行うのが普通です。広町につきましても、段階はさまざまですけれども、そういったような需要の動向についてもアンテナを張りながら検討しています。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この広町の地域では、こういうものが今求められているんだ、そういうものははっきりしていないんですか。これからつかんでいくということなんか尋ねました。","respondent":"上野都市開発課長","answer":"まだ、開発の構想の策定に向けての検討をＪＲと共同してやっているものでございまして。その需要につきましても、引き続き検討を進めていくこととしています。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"案じゃなくて、今、この品川区全体のまちづくりだとか、あるいは経済状況だとかいろいろ見て、今、ここにこういうものが求められているとか、そういうのが本来最初にあるのかなと思うんですけれども、そういうところはよくわからないみたいに伺ったんですが。","respondent":"上野都市開発課長","answer":"手法はともかくといたしまして、いずれかの段階で具体的な内容としてまとまったものができました段階では、当委員会も含めまして、区民の意見なども聞きながら開発をまとめていく考えですので、今段階では、そういったものをお示しする段階には至ってございません。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"意見","question":"ＪＲ東日本が自分たちでどういうことをやるか、それはそっちの話よ、そういうことじゃないでしょうということを言っているんです。だから聞いているんですとの意見を述べました。","respondent":"岩田まちづくり事業部次長","answer":"ここのところに大井プレイス構想全体構想は無理としても、今の住宅のところを中心に、開発を検討していきましょうというのが両首脳の合意事項です。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"意見","question":"だから言っているんです。ここの住宅のところだけの話だとか、それはごまかす話ですよとの意見を述べました。","respondent":"岩田まちづくり事業部次長","answer":"だから、こういう計画をベースに個別開発を行う場合に、この広町の住宅部分でどういう開発が望ましいかということを検討しているわけです。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"景観というものをどうするのかというのが、どうしていこうとされているのか、そこを教えてほしいと求めました。","respondent":"阿部都市計画課長","answer":"一応２カ年の予定ではありますけれども、私どもも当然中心になってまいりますけれども、その合意を目指してやっていきたいと思います。具体的に、いつまでに何をやるというのはまだ決まっていませんけれども、この２年間の中でどこまでやれるのか、取り組んでいきたいと思います。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"総合的には品川区のまちづくりをどうするのかということは、区の方針としてあるべきだと思うんですが、どういうもので持たれているのか。よく声を聞くんですけれども、そういう意味では、その旧東海道の景観ガイドプランというものをどういうふうに位置づけたのかということを伺います。","respondent":"阿部都市計画課長","answer":"区としてどういうふうな景観まちづくりを進めていくのかという部分ですけれども、市街地整備基本方針の中で、寺社がある。私ども、このようにまちづくりを考えています。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"区としてどういうふうに考えるかというふうにしていかないと、地域の方の合意がなければできないんですというものとはまた別なものだと思うんですね。区としてどういうふうに旧東海道をとらえるのかということがすごく、一度壊してしまったら、そういうところの考え方というのを伺いたいんですね。","respondent":"阿部都市計画課長","answer":"それはあくまでも地元の方々が考える、これが基本ですので、そこは大事にしておきたい。それは地元の方がまちづくりの一つの手法として考えたものですから、まちをつくっていきたいというのが私どもの考えですので、その辺ご理解ください。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"積極的に支援をしていただくという成果もあるので、働きかけていただいて、一緒に検討してほしいと求めました。","respondent":"福田まちづくり事業部長","answer":"そう考えたときに、せっかく旧東海道の第一の宿場町なんでありますから、観光ということに区としても力が入れられればいいのではないか。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965541?Template=document&Id=3850#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":43418,"voices":121}},{"id":"h18-20060605-9","meetingId":"h18-cm06","date":"2006年6月5日","dateIso":"2006-06-05","committee":"文教委員会","time":"午後１時０３分～午後３時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"原副委員長","kind":"意見","question":"副委員長を務めします原です。よろしくどうぞお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"武内委員","kind":"質問","question":"それから何かあった場合の報告、体制とか、そうしたものというのはどういうふうになっているのか説明を求めました。","respondent":"古里学務課長、富田生涯学習課長、工藤品川図書館長","answer":"それぞれ点検日を報告させたところ、５月の中旬に所定の点検を行っているという報告がございました。きちんとした点検をさせていただいているです。 歴史館と二つの区立体育館にエレベーターが設置されておりますが、いずれも毎月１回法定点検を行い、不具合はなかったということを確認しております。 品川区の図書館は１０館あります。私どものほうも月１回点検をしておりまして、今のところ不具合等の報告は来てございません。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"そうすると、エレベーターの会社みたいなのは、ある程度学校だったら同じところとか、施設によっては違うんでしょうか。それとも、大体同じところなんか尋ねました。","respondent":"富田生涯学習課長、古里学務課長、工藤品川図書館長","answer":"生涯学習施設につきましては、メーカーが同一ということではなく、概ね４社のメーカーが入っております。 学校におきましては、業者はたまたま一つの業者です。 生涯学習課と同様、私どもも業者はそれぞれ異なってあります。４社です。","id":"exchange-003"},{"speaker":"武内委員","kind":"確認","question":"いわゆる施設においてのエレベーターは安全だということであると思うんですけど、ああいった事件がありましたので、またその辺の確認をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"どこがコーディネーターというのかな、まとめ役というか、そういう形にはならないんですか。どこがもとというのかな、扇のかなめになるという、そういうことはあり得ないんか尋ねました。","respondent":"市川庶務課長","answer":"実施計画の中で、ただいま委員からご指摘のございましたハードからソフトにわたる事業の取りまとめを行ってあります。実際の事業の運営の中で関係する課がそれぞれ調整を図りながら、実際これを進めているという状況です。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"庶務課長が言われたように、どこかが中心になってというか、中心にもっとやっていってほしいとお願いしておきます。一番後ろに出ている教育委員会の予算というのを別にして、事業別に出ている予算というのは、人件費は入っているんか尋ねました。","respondent":"長田教育次長","answer":"人件費の部分につきましては、昨年度から事業費の中にすべて入れて集計をしていますので、この部分のあれも当然数字の中には人件費が含まれているというふうにご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、例えば１１ページから予算が出てくるんだけども、一番わかりやすく、一番上の７～９年生の福祉教育、この内容はいい、内容を聞いているんじゃなくて、この８６万４,０００円というところに人件費は入っているんか尋ねました。","respondent":"長田教育次長","answer":"全体の中には人件費がそれぞれの事業に分散されておりますけれども、個別の事業で見ていただいたときには、特に１１ページのいろんな事業が入っていますけれども、この部分は直接の事業費だけです。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"それを僕たちはどういうふうに見分ければいいんですか。これの見方。","respondent":"市川庶務課長","answer":"私から説明をしますけど、委員からご質問がございました教育委員会事務局のいわゆる従来の職員費に相当する金額はお示ししてございません。ちょっと来年度以降、その辺の記載の仕方については、検討させていただきたいと思います。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"７１ページの、例えば１事業には入っていないんだけど、そんなに急ぎませんから後で知らせてください。同じ１１ページの下から五、専門家というのは、何の専門家なのか教えてくれませんか。","respondent":"河野指導課長","answer":"ここで挙げている専門家とは、学校経営、教育課程、法律、財務を対象としております。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"それから、２２ページの上の表がありますよね、小学校の分の。この増加というのは、こういう傾向にあるんだというふうに考えていてよろしいんか尋ねました。","respondent":"古里学務課長","answer":"就学指導委員会の説明がございましたけれども、そちらで就学指導を検討する中で、生徒がこちらのほうに入っております。ちょっと予測ができないことですので、あわせて特別支援教育の関係がありますので、その辺のことも含めながら。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"なぜ聞いたかというと、いわゆる制度が変わってきて、これからどういうふうにしていくかというのに傾向をつかんでいなきゃ困るんですよ。だから、大事なことに絡むので、来年以降はこうじゃないという今判断を教育委員会は持っているというふうに受け取っていいんか尋ねました。","respondent":"古里学務課長","answer":"こちらの就学相談の段階の中で、あるいはこれまでの状態のところもつかんですけれども、そしてもう一つは、東京都の養護学校の動向もあります。こちらの再編に伴って、区立小中学校のほうに通学してくる心身障害児が増加傾向に今後も転じていくというふうに考えております。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、全体的に幼保一元という一つの形態にとらえていくのかというのをここで聞いていいのかどうか悩んでいるんだけど。教育委員会としてはどう考えているのか、聞かせてくれませんかとの意見を述べました。","respondent":"古里学務課長","answer":"品川区では、幼保一元の事業をこれからも進めていくというふうに聞いてあります。したがいまして、その予定で今保育課の事業の計画を立てているというふうには聞いてあります。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"４０＋１８＋９かな、数字がわからないんだけど、どういうのか教えてください。長くなってすみません。","respondent":"河野指導課長","answer":"教育実習の受け入れ数ですが、これは８３名です。それに見合った実習生をできる限り受け入れるという形をとってありますので、すべての学校に必ず実習生が入るということではございません。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっともう一回関連、今の、いいですか。そうすると、日野学園は既に４月に開校して文部科学省の教育、全部特区として認められたというふうに理解しておいていいわけか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"今委員のお話にありましたとおり、すべての学校が特区と認定を受けているです。","id":"exchange-014"},{"speaker":"築舘委員","kind":"質問・要望","question":"昭和５６年度から八ヶ岳ですか、昭和６２年から千葉県ということで、今後それぞれそういうふうな形で継続していくのかどうかということ。それからあと、その点の推移と、それからその辺の教職員住宅がしっかりと埋まっているのかどうかという現状をお聞かせいただきたい。","respondent":"古里学務課長、市川庶務課長","answer":"その辺を勘案しながら今後その活用方について検討していかなければいけないというふうに考えてあります。したがって、今後もこのような低農薬野菜の学校給食への使用は継続をするつもりでおります。 教職員住宅に関係するご質問ですが、昨年度は私のほうで担当しておりました事業ですので、私のほうから説明します。概ね単身では３年、世帯寮では４年程度の入居実績、このようになってあります。","id":"exchange-015"},{"speaker":"築舘委員","kind":"質問・要望","question":"３９ページのところですけれども、もっと増えてきたら、そこのところをお聞かせいただきたい。これはほんとうにいい生徒と言ってはいけないけど、そういう方々に対するアプローチというのはどんなことをやっているんでしょうか、説明を求めました。","respondent":"河野指導課長","answer":"それから２点目のマイスクール八潮関連のご質問ですが、もうしばらくの間施設等の改良等を見通しながら対応できるのかなという見通しです。","id":"exchange-016"},{"speaker":"築舘委員","kind":"質問","question":"じゃあ、それぞれわかりましたので、よろしくお願いします。質問ですが、これは平成１７年度は多少人数が減っておりますが、どういった形で今取り組みをしているのかということの話を聞かせてください。","respondent":"富田生涯学習課長","answer":"１回１００人弱の回がありましたりですとか、今年度の第１回は４００人近い参加ですので、新たなコースの開拓等もあわせて行っていきたいと考えています。","id":"exchange-017"},{"speaker":"本間委員","kind":"質問・要望","question":"その都度、３年に１回専門家による評価の実施というのが出ておりましたが、具体的な中身についてちょっと教えていただければというふうに思います。小中学校各２校というような形を中心に交流を進めていく、派遣対応が１年とか数年とか、そういうようなことについても教えていただきたい。","respondent":"古里学務課長、河野指導課長、吉村小中一貫教育担当課長、富田生涯学習課長","answer":"選択制に伴って入学者が少なくなっているところですけれども、選択制は教育改革の柱の一つというふうなことで進められてきてあります。… 専門外部評価委員会と校区外部評価委員会の違いについてご説明します。地域保護者との連携、学校教育に反映させていくということで… 友好協会との連携と、友好協会のほうにお願いをして、ここで日本語のある程度の一定の指導をしてもらうということがあります。","id":"exchange-018"},{"speaker":"本間委員","kind":"質問・要望","question":"それから、新しく借りられるのは、どのくらいの規模といいますか、１面ですか、それとも複数面ですか。というようなことをちょっと教えていただきたい。","respondent":"富田生涯学習課長","answer":"２カ分申し込みを受けましたところ、１１件ほどの申し込みがあり、港湾局のほうに申し込みさせていただいたところであります。","id":"exchange-019"},{"speaker":"本間委員","kind":"質問","question":"専門家による校長、副校長からヒアリングを受けるということなんですが、そうすると、この部分が３年に１回ということでしょうか。悩んでいるような部分の学校は３年に１度ぐらいではなく、そんなことを思ったものですから、わからないので説明を求めました。","respondent":"河野指導課長","answer":"トータル５８校、都合５８校になるわけですが、一応今のところ３年に１回という形でやっております。その校長が目指す学校経営について、できるだけ実現できるよう、我々としても支援をしています。","id":"exchange-020"},{"speaker":"本間委員","kind":"質問・要望","question":"特に新年度の採用が１けたで終わってしまうとか、地域の人たちの協力等々を加えてもらいながら、生き生きとした学校運営をやってほしいな。生活、風土と習慣が生きた形で伝わっていくような形で連携をとっていただきたいというふうなことを思ったものですから、質問させていただきました。","respondent":"若月教育長","answer":"これについても、まさに跡施設の利用といったようなことが当然出てまいります。教育委員会だけの考え方では事がなかなか進まない部分もありますが、また地域住民の方々の要望にもこたえられ、こんなふうに考えているところです。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"では、幼稚園も保育園もなくすという考えを品川区も持つんですか、それとも３種類に増やしていくんですか、基本的なところなんだ。所管が厚生委員会だとかなんだとかじゃなくて、子どもの就学前の形をどうとらえるか、プラス在宅があるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/670410?Template=document&Id=4572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":40778,"voices":90}},{"id":"h18-20060605-5","meetingId":"h18-cm06","date":"2006年6月5日","dateIso":"2006-06-05","committee":"総務委員会","time":"午後１時０３分～午後２時４１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"若林副委員長","kind":"意見","question":"副委員長を仰せつかりました若林と申します、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"山路委員","kind":"意見","question":"公明党の山路良成です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"初めての総務委員会になりますので、ちょっとお願いをいたします。４ページの５番目、(5)のところですけれども、ちょっとここの説明だけお願いをしたいと思いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"ご指摘のとおりでございまして、自治制度特別委員会でも都区制度改革、これはもちろんですけれども、地方自治制度全般についても、とりわけ２３区に関係のあるような内容についてはご報告していますけれども、そういったものについて取り扱いをしているというものです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"どのぐらいの数値で出ているのか、情報をきかせてください。お願いしますとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"数値につきましては、階によっても違いますし、それから、いろいろ弱い部分の数値を言うことになりますので、誤解を生ずるということで、差し控えさせていただきたいと思いますが、先ほど経理課長からも申し上げたとおり、補強が必要だという判断になってあります。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"そうではなくて、耐震補強工事をするんでしょうけど、今、多くの人たちが働いているわけです。その辺の目安というんですか、例えば本当に危険なら危険という話を出していかなきゃいけないかと思うんですけど、その辺をお願いします。","respondent":"宍戸施設担当課長","answer":"次の総務委員会で詳しく報告させていただきたいと思いますが、補強が必要だというふうな判断です。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと２点だけ教えていただきたいんですけれども、企画のほうの区民相談室のところで人権身の上相談は昨年度の実績で１６件ということです。それともう１点、国民保護計画を平成１８年度中に策定するということで、予定ですと５月から動き出したんか尋ねました。","respondent":"武内人権啓発課長、桑村総務課長兼秘書課長兼危機管理室長","answer":"同和生活相談のほうにつきましては同和地区出身者という方を対象に実施している相談でありまして、なかなか一般の区民の方の相談と一緒にするということは、歴史的経過のなかでまだまだ難しいのかなと考えております。 基本的にはもちろん策定し終わった後の報告というのはすると思いますけど、途中で、一定の案がまとまったところで委員会等にご報告ということでも事務局としては考えているところです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"ただ、実際の流れから言えば、区民相談室でやる人権身の上相談というのは年間１６件ぐらい。年間３００件と言いましたから、これからの流れの中でもいいんですけれども、報告をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"住宅ですから、建築課に入るんですけれども、今問題になっているのは、点検業者が報告を上げていなかったということで、非常に問題になっている。その辺のチェックはどういうふうにされているかをお伺いしたい。","respondent":"宍戸施設担当課長","answer":"月１回の点検が義務づけられておりますが、それぞれの施設を管理している主管課に報告が行くようになってあります。そこでしっかりチェックをし、問題があるのであれば、私ども技術のほうに相談があるというふうなシステムになってあります。","id":"exchange-008"}]},{"id":"topic-03","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"そういった基準に沿ってそもそも設計をされているのかどうか、ちょっとその辺の流れがよくわからないので教えていただきたい。平成２０年までに全部１００％やるんだというお話でしたけれども、そうすると、ちょっとその辺を教えていただければ。","respondent":"宍戸施設担当課長","answer":"避難所機能も保持するというようなことで０.７を目標値として、耐震診断というものを個別で行いまして、その分が実施設計の件数が増えてきたと。","id":"exchange-009"},{"speaker":"菊地委員","kind":"意見","question":"さっきのIs値というやつなんですけれども、今、耐震偽装問題で騒がれている１.０というような感じで、マイナス幾つとかと、そういう基準で解体しなくちゃならないとかという話がありますので。","respondent":"宍戸施設担当課長","answer":"それで、耐震補強の場合は既にある建物をどう補強していくかなので、また全然違う考え方で、０.６というのが目標。だから、全然違う考え方で、新築の場合と耐震の場合とは取り扱っているです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"２番目の鉄筋コンクリート造耐震壁ということで、どこかを新しく鉄筋コンクリートの壁をつくるということではないのかと思うんですけど、これは間違いありませんかとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"で、一体的に構造として厚い壁で耐力を持たせるというように、上から下まで全部通したような壁をつくって、それによって補強するといったような意味。ですから、厚くする表現に間違いはないです。","id":"exchange-011"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田委員長","kind":"質問","question":"調査事項等につきまして皆様からご意見を伺って、日程も大分厳しいわけでありますが、日程を考慮して調査していきたいと考えています。皆様も何かお考えがあれば、ぜひどうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"逆に、その辺の入札制度のあり方について品川区としても、当委員会としても検討していただくような時間を持てればいいなと考えております。他の自治体でも取り組みはじめたので、常々先進的な品川区、当総務委員会でその辺をもしご討議できればありがたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"山路委員","kind":"質問","question":"子育てとか、福祉関連なんかでやっているんでしょうか。一体どれだけの補助金を出して、どれだけの運営をしてどういう実績があってとか、そういうものを何か総務課で１本にまとめてもらえないかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"塚本委員","kind":"意見","question":"今後ここを調査するんだよということをお立ていただければという、そういう方針立てでいいんではないかと。年初にすべてが決めなければいけないということだけ、申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"石田委員長","kind":"提案","question":"私も１つの方法だと考えていますので、そこら辺も含めまして提案するような形をとらせていただきたいと考えていますので、よろしくお願いいたします。運営の方法、本来の趣旨であります現地調査は私も必要と考えていますので、実施するという方向で進めさせていただいてよろしいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816536?Template=document&Id=1720#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":31305,"voices":92}},{"id":"h18-20060606-11","meetingId":"h18-cm06","date":"2006年6月6日","dateIso":"2006-06-06","committee":"自治制度特別委員会","time":"午後１時０４分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"宮崎副委員長","kind":"意見","question":"副委員長の宮崎です。どうぞ、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"教えてほしいんですけど、都区協議の中で、大都市事務の割合をどうしているかというのが財調の配分に影響してくる。具体的には都側は何を主張し、区側はどういうふうに判断しているのかというのがわかったら、教えてほしいです。","respondent":"日下部企画財政課長","answer":"それは法令の一般的な解釈であって、実体の問題を見ると、この大都市二十三区というのは８５０万人の人口を抱えている。その辺が大きな一つの主張の違いになってあらわれてくるという状況です。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"都側の言う任意共管事務ですか、それを法令で東京都がやらなければならない事務以外の、しかし実体的には二十三区がかなりやっているんだというあたりの具体的なものがもう少し細かくわかったら教えてもらえますか。","respondent":"日下部企画財政課長","answer":"１つの例としてよく挙げられますのは、例えば上野動物園については、大都市事務でやっているんだと。一番わかりやすい例は今の動物園の例です。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"本来シナリオ２のように全部やっちゃうというのは、その考え方というのは、筋としては筋だと思うんですね。大変なところというのは、それじゃ困るよというのが強いんじゃないかと思いますが、その辺の考え方としてはいかがなんか尋ねました。","respondent":"日下部企画財政課長","answer":"シナリオの１と２ということで、そういった意味で、お互いに合意を見い出すこともなかなか難しい面があります。ただ第二次の地方制度調査会の方では、そちらの方でいろいろな議論はされていくのではないかと見込んでいるところです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"例えばこういう考え方があるという、２つの考え方を示す程度なんですか。ちょっとそこら辺はいかがか尋ねました。","respondent":"日下部企画財政課長","answer":"区長会からいろいろな調査検討をお願いしてということで、そういう性格を私どもは十分わきまえた上で、この辺の内容については受けとめていくということは重要ではないかと考えています。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"意見","question":"平成１２年の改革が、二十三区が協議会なり区長会なりで、きちんと方向を一にしているのかどうかというのが１つ。私はそういうふうに受けとったんだけど、どう違うのか説明を求めました。","respondent":"日下部企画財政課長","answer":"特に大都市における自治制度はどうあるべかということを、実は区長さん方がそれぞれ分科会をつくって検討・研究・勉強を結構進めてきてあります。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"この問題についてどういう形で委員会の意思を高橋区長なり、特別区協議会に伝えていくかということができないですよ。議会のご意思を諮ってくださいという形でやっていかなければ、流れだけ説明されても、私たちはここで何をやってもしようがないと思うとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"その辺は第１回目でどうだったのかということと、区長も公選区長ですから、まちまちだったですよね。理論的には基礎的自治体はどうあるべきかという点では、どんなふうにとらえているのか、聞きたいと思うんです。","respondent":"日下部企画財政課長","answer":"第１回目の状況ということでありますけれども、その辺を議論の１つの素材にもして、今後の検討が進んでいくと理解しております。今回の都区のあり方検討会というのは、比較的月１回のペースで、これからの検討が進んでいくと受けとめているところです。","id":"exchange-008"},{"speaker":"本田委員","kind":"意見","question":"どういうふうに動いていくのか、この辺がこれからの１年間、非常に重要になっていくんじゃないかなと思っているんです。制度調査会はもう既に４回やったということですけれども、どういうことが検討されているのか、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"新美企画部長","answer":"前回都区協議の合意事項に基づく都区の共同の検討組織につきましての検討の進め方について、私どもが現在聞いているところで、少しご説明いたします。","id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと１点だけ質問をさせていただきたいのですが、東京都の方で副知事を３人そろえてきたというところに、この意義というのは大きいと思うんです。いい点はあると思うけど、それをどういうふうにとらえていらっしゃるのか。","respondent":"新美企画部長","answer":"その中で都区制度、どう担い合うべきかということが基本テーマということで、そういう意味では仕事をどのようにそれぞれがやっていくべきか。","id":"exchange-010"},{"speaker":"原委員","kind":"意見","question":"これから議論をしていく上で、それぞれの分担の中で、それぞれのスペシャリストが３人そろっているというふうに解釈していいのかどうかと思うんです。","respondent":"新美企画部長","answer":"次回が６月末というふうに聞いておりますが、議事録という形ではなく、それぞれが整理をして次に進む。今後、開かれる状況を見ながら、私どももどう推移していくのかを見きわめていきたいと考えているところです。","id":"exchange-011"},{"speaker":"原委員","kind":"意見","question":"会長がそこのところを今後どう持っていくのかというので、この３副知事をそろえたのかなと思っているんですが、非常に期待をしているところです。ぜひ、報告もよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"皆さんからいろいろ出ていて、私の理解は大分違うのかなと、ちょっと不安になってきたので、確認をさせてほしいと求めました。これを踏み込めば、この最後の部分は別な話で切り分けてやるんじゃないかなとちょっと思っているんだけれども、そこら辺の感覚はどう思われますか。","respondent":"日下部企画財政課長","answer":"このあり方検討会の中でどこまで踏み込むのかというお尋ねでありますけれども、恐らくこれは論議の対象にはなってくると思います。ざっくばらんにいろいろな議論になるとは思いますけれども、どこまでそれが展開されるのか、ちょっとその辺は不明の状況です。","id":"exchange-013"},{"speaker":"石田委員","kind":"質問・要望","question":"そういうのを立ち上げるぐらいの気持ちで臨む時期なんじゃないかなと思うので、それはぜひ議長会とかあれば、やっていただきたい。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"三村委員","kind":"質問","question":"基本的なことを質問するんですけど、ここの「清掃とリサイクル」の２ページの持ち込みというのは産業廃棄物ということか尋ねました。","respondent":"中山資源循環推進課長","answer":"これは清掃工場に直接持ち込まれる区が、清掃事務所が収集するごみでない、事業系の一般廃棄物です。","id":"exchange-015"},{"speaker":"三村委員","kind":"質問","question":"汚泥などはどういうふうにリサイクルだとか、自動車の部品だとか、それの都だとか区だとかの働きかけはどのようにされているのかをお伺いしたい。","respondent":"中山資源循環推進課長","answer":"建築資材として使われるような、汚泥スラグというような形で、工事等に利用される。基本的には、汚泥ですから、残った固形物についてはそういうのが主流になっていると伺っております。","id":"exchange-016"},{"speaker":"三村委員","kind":"質問・要望","question":"今回の説明の中にはなかったんですけれども、廃プラスチックを燃やして、東京ガスと合弁会社で電気を売っていくという話が出ているかと、清掃一部事務組合から出資をしてという話があるかと思うんですけれども、その辺についても詳しいご説明をいただきたいと思うんですけれども。","respondent":"中山資源循環推進課長","answer":"経営感覚的なものをもって、より高く売るような意識を持ってやっていくような方向性の会社の設立を今、検討しているです。これについてはまた、しかるべき段階でご説明ができるかと思います。","id":"exchange-017"},{"speaker":"三村委員","kind":"質問","question":"清掃一部事務組合の方にお話を伺いに行って、こういった会社が必要だというような話も出ていたんですけれども、その辺について判明していることであれば。","respondent":"中山資源循環推進課長","answer":"今働いている職員の受け入れが現状でできないという説明の意味がちょっと私は理解しかねる部分がありますけれども、いろいろな人材確保の方策を考えるということはあろうかと思いますけれども、ちょっと私はこの場では説明しかねるところがあります。","id":"exchange-018"},{"speaker":"沢田委員","kind":"意見","question":"二十三区のごみ量が４９０万トンから３４０万トンに、年々減ってきている。今度、廃プラスチックを全量燃やす方向だということを聞いたんですけれども、そこらの事情についてちょっと説明していただけますかとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"平成２０年度を目途に、熱利用していくという方針が、昨年１０月の区長会で二十三区の方針として定めてあります。その分別変更への影響であるとかを確認すべく、モデル収集を行い、住民説明も行っていくという段階になっているという状況です。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"それで、今後燃やすので全然変わらないんだという。出して、結局は燃やしているのでは同じじゃないかと思うんですが、その辺はいかがなんか尋ねました。","respondent":"中山資源循環推進課長","answer":"ごみの流れから考えると、さらに熱効率が大田工場よりも高い品川清掃工場での技術的な対応も十分可能であるという形になっております。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"すごく求められているときに、どうも燃やしちゃうというのは、もう一つよくわからない。問題が残るのではないかと思うんですけど、コメントがありましたら、お願いしたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"２０年度実施ですので、７月から品川ではモデル地区を定めまして、そこではプラスチックは可燃ごみとして収集するということになっております。新海面処分場に持っていくごみが２１万４,２００トン、もう一つは、これを分別の現場で徹底した説明をできていなかったんです。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"ドイツで熱処理というのは燃やすということなんか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"いろいろあります。","id":"exchange-022"},{"speaker":"沢田委員","kind":"意見","question":"あるいはそれをこの間も１週間ほど前に、そういうことも含めて、やっぱり燃やさない。処分場の寿命をなるべく延ばすというのは、それはそれとしてよくわかるんですけれども、一応意見だけ出させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問","question":"１点だけ。必ず表に出して、一般の人にぱっと一目でわかるぐらいのデータをここに載せることをしてほしいと思うんだけど、どうか尋ねました。","respondent":"中山資源循環推進課長","answer":"実は品川工場も稼働を開始して、埋立処分場の中にきちんと防水をしたり、区画を整理したりという工事があります。そういうものも見習いながら、これからの課題ですので、清掃一部事務組合にも十分その辺は伝えながら考えていきたいと思います。","id":"exchange-024"},{"speaker":"三村委員","kind":"意見","question":"先ほど廃プラスチックの方で７月からモデル実施をして、その中で影響やなんかを調査していくということだったんですけれども、特に環境に与える影響についてどういう調査をされていくのか、その辺についてお考えがあればお願いしますとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"区民委員会に分別の変更であるということでご報告申し上げておりますので、公表していくというふうになっておりますので、分別工程そのものについては区民委員会でご報告を申し上げております。","id":"exchange-025"},{"speaker":"三村委員","kind":"意見","question":"分別モデルとかというのではなくて、プラスチックを燃やすことに対して、環境負荷を周りに与えるかどうかという調査やなんかは、区としては考えているか、いないかということなんですとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"基本的には品川区のごみについては、品川清掃工場に入りますので、品川清掃工場の方でモデル事業の開始以降もデータをとり、これは公表していくと考えておりますので、その辺は区としても必要に応じてお伝えしていきたいと考えております。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"委員長にまずお聞きしておきたいんだけど、清掃制度に関することという調査事項をいろいろやっていくんだけど、どういうことをしていくんですか。それによって、いろいろともらう資料だとか、議論していく内容というものが違ってくると思うんですが、その辺をちょっと説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"意見","question":"年に２カ月はしなければならないという、その計画等が相当な金額、絡んでくるわけです。６年間という猶予期間があったにもかかわらず、これをこの委員会としてどういうふうに議論していくのかというのが、どの辺まで資料が出ていますかとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"まずは当分の間の継続の中での効率的な運営というものがどうなのかというところが１つのポイントだと思います。まずは大もとの今のフレームなり、そこが実質たり得るのかというところをご検討いただくところがスタートではないのかなと、私は思っております。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"先ほどから言うように、清掃一部事務組合の存続についても、私たちは議論したいわけですよ。ですから、いわゆる清掃一部事務組合に要請をしてもらえば、入ってくるというふうに考えていいんか尋ねました。","respondent":"中山資源循環推進課長","answer":"ご検討が難しい部分もあろうかと思いますから、またその時々で新しいものが出れば、お示しできるかというふうに思います。","id":"exchange-029"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"土井委員","kind":"質問","question":"ごみがどう動いたとかいう個別の話は、ここら辺は大事に、なぜこういうことをやっているのかということをとらえていくべきだろうなと思います。お願いで恐縮ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問・要望","question":"ここからこっちの中間処理の問題と、東京都との関連は、ここで資料を示してほしいし、議論ができるようにした方がいいんじゃないかなと思います。一応要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/148286?Template=document&Id=5596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":40778,"voices":84}},{"id":"h18-20060606-16","meetingId":"h18-cm06","date":"2006年6月6日","dateIso":"2006-06-06","committee":"街づくり特別委員会","time":"午後１時０４分～午後２時３３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"大西委員","kind":"意見","question":"今の近隣セキュリティシステムの中で、執行実績で私立１２７人というふうになっているんですけれども、この私立というものは具体的にはどういう感じで、これがなっているのかを知りたいとの意見を述べました。","respondent":"金子生活安全担当課長","answer":"具体的校名になるかと思いますけれども。","id":"exchange-001"},{"speaker":"大西委員","kind":"質問","question":"これは１２歳未満の品川区に親御さんとともに居住している方であれば、何か、品川区の区報のみか尋ねました。","respondent":"金子生活安全担当課長","answer":"広報関係につきましては、区報のみです。それと、具体的な配布につきましては、日時と場所を指定しまして、電話をちょうだいするような形であたっております。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっとその辺を教えていただきたいのと、平成１７年度６０件ということで、助成分が３６０万円になるんでしょうかね。これは少なくなると見込んでいるのかどうかというのをちょっと教えていただきたいのと、それと、その辺を教えていただきたいんですけれども。","respondent":"伊勢住環境整備担当課長、片田建築課長","answer":"ただ、それから３７年度までに７０％というようなことが言われていまして、そういう面ではまだまだそこには行かないということになります。将来的にはそれに向かって、密集事業の助成等はございませんが… 特に１７年度、かなり実績として当初予算の１.５倍という数字になったわけありますけれども、これは補正を行いまして対応させていただいたと。当面、私どもとして、５０件として予算を進めていくということを考えてあります。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"都と区のところも、国から２分の１、そのままストレートに入ってくるということか尋ねました。","respondent":"片田建築課長","answer":"都を通してですけれども、都を介して国に申請を行っておりますので、その枠で６万円の２分の１という形で補助金の助成額となっています。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっともう１点それにあわせて、最終的にその意見の集約というのは、その辺のシステムをちょっと教えていただきたいんです。それから、今の耐震診断の助成なんですけれども、２分の１が国から出てくるということは、区は１円も出していないということになるんか尋ねました。","respondent":"片田建築課長、伊勢住環境整備担当課長","answer":"東京都の補助、これは参考ですけれども、東京都はまだ補助を診断については１７年度はやってきてございませんでした。区の方の支援は診断については区内全域を対象に実施していますので、診断も改修も… その後にその地域全体の説明会を開いて、西大井地区ではそういう形で昨年の１２月に地域全体の説明会をして、今年の４月から事業を開始したと。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"それなりの例えば資機材となると、１７万８,０００円ではちょっと足りないような気もしたので、その辺の絡みですか。５月、２カ月ですけれども、１８年度の状況はどうなんか尋ねました。","respondent":"片田建築課長","answer":"したがいまして、これは継続的にそういうものが必要になってくるだろうと、常に日常的に備えを用意しているといったような考え方です。２つ目のご質問ですけれども、平成１８年度の実績は、４月の時点で１０件ぐらいが届け出が出ているというようなところを把握しています。","id":"exchange-006"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今の耐震の件ですけれども、４月の１カ月だけですから１０件ということになるんだろうけれども、全体を通さないと全体のことはわからないのかもしれませんが、感触としてやっぱり増える傾向に、それとも何となく減少傾向に、その辺の感触はどうか尋ねました。","respondent":"片田建築課長","answer":"４月２１日からたしか進めてありますが、なおかつ１２月には町会を通して、それが１つのきっかけみたいなところもあるんでしょうか。そういう１つの社会的な現象も含めた中での動向で、いろいろ機会を通してＰＲしてまいりたいということで考えてあります。","id":"exchange-007"},{"speaker":"堺委員","kind":"確認","question":"それからわんぱくパトロール隊員１３９人と載っておりますが、こういう人は各学校を通じて生徒さんたちを参加者として応募してもらったんですか。この仕組みというんですか、それはどういうふうになっているのか、ちょっとそれの参加についてお願いします。","respondent":"金子生活安全担当課長","answer":"したがいまして、ネットワークを持つ警察をはじめ、そういった関係者等に働きかけまして、この数字になりました。個々の小学校等にも声をおかけいたしまして、区内の小学校、全体のバランスがとれるように図っていきたいと考えております。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"おやりになる事業ですから、確かに品川は４０の小学校がありますから、子どもたちが地域の安全マップをつくっていましたよね。だから学校長を通じて対応していくのは、より効果のある形になるのかななんていう気がするんですが、その辺はいかがか尋ねました。","respondent":"田村地域活動課長","answer":"思いのほかやっぱり夏休みのうちはそれぞれ予定があるので、それ以外は地区委員会が６６名、警察のルートがあるのが６０名ということです。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"この協会に参加をされている方たちはどういうところから委員をなさっているのか、この際、ちょっと教えてほしいと求めました。区から１６０万円それぞれ出ておりますけれども、どこからどれだけ出ているのか、詳細がわかったら説明を求めました。","respondent":"金子生活安全担当課長","answer":"これはいずれも品川の４つの防犯協会のそれぞれ会長が協議会のメンバーとなっております。特に、こういったものを実施して、この際のいろいろな区民の方に内容を知らしめる広報活動等のリーダーを選出するお金がほとんどであるようです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"どのぐらいのスパンで計画をつくりかえようとしているのか、その辺のことをもし知っていたら教えていただきたいと思っているんです。地域防災計画の関係は区民委員会のほうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"常任委員会との仕切りということでお伺いしたんですけれども、委員長のお考えとして、調査概要というかを伺ったときに。委員長のお考えとして、それとも違うんですかと、委員長のお考えをまずお伺いさせていただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"それから８番目にある備蓄ですとか、災害に強い街づくりに関する問題として、ぜひ取り扱っていっていただきたいなと思うんです。その辺も行われていくんでしょうけれども、ぜひこの部分もあわせて、この委員会で取り上げていっていただきたいなと要望したいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"築舘委員","kind":"質問・要望","question":"そういったことはまだそんなに大きな事件はないわけですが、それは常にそういった体制をしっかりしていないといけないという部分での安心・安全のまちづくりを、特に地域の防犯ネットワークを重要視してやっていっていただきたいと私は希望しているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"それと、いつ起きてもおかしくない地震ということですから、その辺のところも１つ大きなポイントになってくるのではないかなという気がします。それに対する対策というんですか、うちでは安心・安全のまちづくりですから、今申し上げた公園あるいは公共の建物というんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"何ていうんでしょうか、私の思いとしては、こちらを非常に進めていく必要があるんじゃないかなと思っています。地震が起こった後、あるいはそのための対策がどういうふうな手が打たれているかというところも含めて、ぜひそこを検討していただいてと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大西委員","kind":"意見","question":"私は２項の安心・安全のまちづくりということに関して、また地域としてどういう形で抑制し、そういうものを研究して調査していくというようなこともよいのではないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"委員長、その前に、今日を入れないで委員会はあと何回あるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"そうすると、今、南委員からもお話が出ましたけれども、そこで視察等もいいんですよね。私は、今、皆さんが出していただいたことを正副委員長でまとめていただければ結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"どうでしょうかね、各自治体でそろえて、用意もやはりしておかなきゃいけないんじゃないかと。すいません、ちょっと具体性がなくて申しわけないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/847285?Template=document&Id=6326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":25270,"voices":83}},{"id":"h18-20060607-14","meetingId":"h18-cm06","date":"2006年6月7日","dateIso":"2006-06-07","committee":"行財政改革特別委員会","time":"午後１時０４分～午後３時３４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"川西委員","kind":"提案","question":"ですから、区の組織の中のプロジェクトで計画案をつくるのと、この特別委員会の機能がどういうふうに並行していくのか。３年、５年、７年ぐらいを見通して提案できなかったのかという点を伺いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認だけであります。あるんだったらいいんでしょうけれども、もう少し具体的に、拠点整備とする方向の考え方があるんでしょうかということを説明を求めました。","respondent":"日下部企画財政課長","answer":"１点目の区道の管理の関係ですけれども、土木事務所は廃止になりましたけれども、民間委託ということでやっております。今ご指摘のあった点については、いずれにしろ、トータルで地域の防災としての拠点の機能を有するという形で整備を進めるものと承知をしております。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"確認","question":"ここでは確認だけですが、防災拠点として整備をしていくんであれば、施設は既に今あるわけですね。ですから、費用対効果のことを考えていくと、そのことはぜひ検討してくださいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"皆さんから意見を求めて、１回検討する必要があるんじゃないかとか、そういう方向性をつくっていったらいいんじゃないかと思うんです。どういうふうに、正副委員長と常任委員会で、そのあたりは決められてきちゃったのかと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"１年間かけてどういうふうにするのかということも非常に大きな問題だろうと思うんですけれども、どういうふうに使われているのかとか、委員会として。そのあたりを、もしできたら、後の進め方のほうで考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちはそういう部分がわからないわけですから、そこをどういうふうに整理をされたのかということを、まず報告をいただきたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"そういうことであれば、昨年の街づくり特別委員会で、第一日野小学校の件はその先が全然明らかになっていないわけですから、そういう意味では、３番目の今後の委員会の運営というところで、公有地に関しては、本委員会で議論をしていくということもできると考えてよろしいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"６月２９日に原小学校の方向性を、というようなことも含めて、ちょっとその辺のことをお聞かせいただきたいのが１点。継続して今までもそういう部分で使われていたのか、どうかということを、ちょっとお聞きしたいと思います。","respondent":"日下部企画財政課長","answer":"次回の６月２９日に、それをもとにして議会のほうからいろいろご意見をいただくという手順で、いわばスタートをするです。今、ある意味で暫定的に使っている、そのまま使用を継続しているというものです。","id":"exchange-008"},{"speaker":"井上委員","kind":"確認","question":"では、旧土木事務所に関して言いますと、事務所として使っていたところが、今、あいているのかという確認。それから、資材置き場というのは、旧土木事務所以外にもいろいろなところにあるものなんか尋ねました。","respondent":"日下部企画財政課長","answer":"ごく狭いところ、例えば西大井の緑道がありますが、その脇に小さな資材を置いているところもあります。緊急用の資材をそういうところに保管をしておくとか、そういうものも、区内に幾つか点在はしています。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"特別委員会ですから、区民要望でこういうのがあるんじゃないか、議会としての意味がないのかなと思っているところです。売却するのは簡単だけれども、なかなか買えないものですから、もうこういう形でどんどん進んでいるというふうに理解してよろしいんか尋ねました。","respondent":"日下部企画財政課長","answer":"建物自体は、即、今、どうこうということにはなりません。庁内でいろいろ検討を進めてまいりたいということで、今、考えているところです。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"全部入り口にするわけにいかないでしょうから、残った敷地を有効活用すべきじゃないかと。企画財政課長は実際に見ているんか尋ねました。","respondent":"日下部企画財政課長","answer":"避難用の入口ということで、今、検討を進めているという状況です。その辺、詳細等、具体的なものがはっきりすれば、またご報告はさせていただきたいと考えています。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"やっぱり区民にとって貴重な財産ですから、立地環境や多角的な検討というのは、当然必要だと思っています。これを進めるときの区の基本的なスタンスを教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"それから具体的に会議の日程等を追って説明ですけれども、原小学校であれば、２９日に委員会のほうにご提案するです。私どもとしましては、そういう形で整理をさせていただきたいと考えています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"関係住民の意見、要望を第一義とすべきだと思うし、公聴会や審議会などの開催もきちんと視野に入れて進めていくということが大切だと思うんです。その辺の公聴会や審議会、今後の進め方はどういうスタンスをとっているのかということを、まず一つ伺いたい。","respondent":"日下部企画財政課長","answer":"地元のほうにもご説明をするということで、幅広くご意見を聞く形をとってまいりたいということで、ご安心をいただきたいと思います。もちろんまいりませんので、この辺も逐次、議会にもいろいろご報告をしながら進めていくべきであると考えているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ私がそう思うかというと、年末年始に、原小学校周辺でアンケートを行いまして、６６通の回答があったんです。やっぱり進め方に対して丁寧さを求めているというのが、それもぜひ踏まえていただいて、改めていかがか尋ねました。","respondent":"日下部企画財政課長","answer":"合意が大事だというご指摘でございましたけれども、十分にきちんとご説明をして、ご理解をいただいていく。通しまして、幅広いご意見をちゃんとお伺いする、そういう形はしっかりととっていきたいと考えております。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問・要望","question":"１番の旧品川大崎土木事務所の、国といえども売却するということは、やはりよく考えていただきたい。そういう点で、やはり空間、オープンスペースというのをぜひ代替で国にもらった後に、先ほどの案は進めていただきたいと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"同じく要望というか、単に防災の拠点という考え方はいいんだけれども、全体像として見ていくということもやはり必要だと思います。先ほど松澤委員がおっしゃったように、防災の拠点は拠点で構わないんだけれども、大きな視野で見ていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"先ほどからいろいろご意見を伺っていて、一つは、今後、ここは視察に行く予定になっているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中島委員","kind":"質問","question":"３棟とか建っているというので、その地域の方の反応というのはどういうのかというのは、どういう形でつかまれているのか。それだけお伺いしておきます。","respondent":"日下部企画財政課長","answer":"その辺の反応といいますか、直接的に、今の段階で区のほうに寄せられているというものはございません。","id":"exchange-018"},{"speaker":"中島委員","kind":"質問","question":"今後は、何か計画をするに当たって、区側とこういう議会で議論していくというだけなのか。原小学校は地元の方のご意見を聞いているということで、これは理解できるんですが、ほかの地域に対しては、どのようにお考えなんか尋ねました。","respondent":"日下部企画財政課長","answer":"これは当然のことながら、先ほど申し上げましたが、まず区民の代表である議会にご報告をしますが、中身にもよりますけれども、基本的にはやはり地域の皆様方のご意見も伺うような機会も含めまして、きちんとご理解いただくという努力をしてまいりたいと考えています。","id":"exchange-019"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは事務所ですけれども、この出張所というのは、今現在、生きているんでしょうかね。この辺だけ、ちょっと確認をいただきたいと思っているんです。","respondent":"日下部企画財政課長","answer":"すみません、記憶が定かでないところがありますが、かつては土木出張所という言い方をしておりました。これがいろいろな経過の中で、３月までは、土木事務所という形で名称が変わりましたので、実質的には同じものです。","id":"exchange-020"},{"speaker":"藤田委員","kind":"意見","question":"荏原土木出張所というのがあったと思うんですけれども、これは現在どのようになっているのか、ちょっと私も今記憶がないんですけれども。ちょうど東急大井町線のすぐ下にあるんですが、私も調べでみないと何とも言えませんとの意見を述べました。","respondent":"日下部企画財政課長","answer":"たしか、かつては荏原土木出張所という名称で存在していたと思いますが、今は清掃の関係の詰め所ということで、利用しているです。そういった区道の管理と公園の管理、この部分が一緒になって、３月までは荏原土木事務所という形で機能していたです。","id":"exchange-021"},{"speaker":"藤田委員","kind":"質問","question":"ですから、その辺も、私たちがもう一度、公有地についての意識をここでもう一度持つべきではないかなと思います。後ほどまた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"行政のほうでも住民の声をとらえてほしいし、ぜひ周りの方の声を十分に吸い上げて、その辺はほんとうに丁寧にやっていただきたいと思っています。作業をしていく拠点というのはどうなっているのか、その後がどうなっているのか、その辺を教えていただけたらと思います。","respondent":"日下部企画財政課長","answer":"ですから、ある意味で、今まで事務所として機能していた部分は、民間のほうに委託をしておりますから、そちらが実質的な一つの拠点になります。そういった面で、今、一部使用しているという状況です。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、委託をされた事業の部分で、必要な部分も、今後また残っていく部分もあると受けとめてよろしいんか尋ねました。","respondent":"日下部企画財政課長","answer":"基本的には、その辺は、一応委託で、相手方にちゃんと業務の遂行ということで移行しておりますので、それはいろいろな整理の仕方がしっかりとできるわけですから、今は、あくまでも一部を一時的に資材置き場として使っているというものです。","id":"exchange-024"},{"speaker":"井上委員","kind":"提案","question":"細かいところをちょっと１点と、委員会に対しての提案なんですけれども、どういう手続が必要なのか。行政のほうで、もう廃止しましたということで、できてしまうものなのか、どうかということが１点との意見を述べました。","respondent":"日下部企画財政課長","answer":"一言で申し上げれば、そのような手続になってまいります。この辺につきましては、何回も申し上げておりますが、２９日に具体的なご提案をさせていただきたいと考えております。","id":"exchange-025"},{"speaker":"井上委員","kind":"確認","question":"原小学校は３棟ある中で、すべてが区有財産なのか、どこかから借りているものもあるのかという確認なんです。いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"原小学校につきましては、土地、建物すべて品川区が所有する財産です。","id":"exchange-026"},{"speaker":"井上委員","kind":"提案","question":"これからは委員会への提案なんですが、そういったところではなく、平場で公聴会を開いていただきたいということは絶対に要望します。議会として外に出て行って、そういう場での議会運営というのも、特別委員会として議長に要望すれば可能な時代だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"川西委員","kind":"提案","question":"特別委員会なんですから、７割ぐらいの方向性が出てから報告をされて、つまらないそんな委員会では特別委員会の意味がないと思います。私たちは行政の事務作業の中にいないわけですから、一定の提案をされた中で討論をしていくということに、今考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"提案","question":"ですから、どういう仕事をしているかということ、私は思っています。ぜひお願いしたいのが、ここでも仕分けがあるはずですから、私たち委員会としても理解した上でないと話は進めていけないと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういうメリットがあって、どういうデメリットがあるのか、皆さん検討しやすいかと思うんです。区が思っているところをまずたたき台にして一覧表ができればなと、そういう資料を作成して、提出していただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"須藤委員","kind":"提案","question":"ですから、また隣近所の声でこうしちゃうという、ほんとうの方向性がない施策になってきちゃってもいけないだろうと思うんです。ぽつんぽつんと持ってきても、虫くいみたいになっちゃうんで、そのあたりは正副委員長がまた整理をしていただきたいと、提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと述べさせていただきたいんですけれども、やっぱりどう活用すべきかというのは、そのまちづくりという視点が欠かせないのかなと思うんです。どういうふうに活用していくのかという、専門家のご意見なんかのお話を伺う機会なんかも一緒に設けていくと、一言。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"もう一つ、すぐ前に国文学研究資料館があるわけですから、跡地利用がどうなるか。何かそんなことの取っかかりが、どこかこの行財政改革特別委員会の中で議論されればいいなと思っているんです、一つの意見として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"藤田委員","kind":"提案","question":"今あるのか、ないのかわからないけれども、当時は、あるという答弁があったものですから、その辺の資料も、できれば検討いただきたい。民間がここまでやるかというような、行政では発想もできないほど民間が提案をして、市民にサービスを提供しているとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"意見","question":"もう既に１年以上やってきているし、検証という立場で、１年間できたらいいのかなと思っています。あまり先走りして、中身をやっていくとは、あまり受けとめたくないなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"そこは特別委員会として取り組むべき課題であるということも新たにわかるということも、お聞きして、資料を出していただけばと思います。動きがあったり、そういったところは報告をいただくべきものだと考えておりますので、その辺の仕切りで進めていただければいいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-02","title":"の民間委託等に関すること","agenda":"の民間委託等に関すること","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"１点だけ、品川歴史館が区直営というような表現をされているんですけれども、直営でやる考え方、歴史的なものが何があるのか、どうかとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"今までの経緯でずっと直営でやっております。そういった部分的なところにつきましては、もちろん委託業者が入っておりますし、そういった形で運営しているものです。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問","question":"たしか前の区民委員会でも質問した記憶があるんですが、こういうことも含めて検討しなければいけない状況になってきたわけでありますね。ですから、こういう大きいなところで、品川区の基本的な考え方を説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"いろいろこれから検討していきますが、これから検討をしていく中で、随時やっていきたいと思っています。それから、検討を進める中で、当特別委員会に対しても、折に触れ、きちんとご報告をさせていただきたいと考えているところです。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、たしか去年でしたか、指定管理者制度についての基準をつくりましたよね。今度はこれをさらに拡大していく必要があるわけですから、もう少し答弁をほしいと求めましたが、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"検討を進めていきまして、また基本方針の改定、見直しについては進めていきたいと思っています。そのあたりをいろいろな角度から検討して、実施要項なりを、検討を進めていきたいと考えています。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ご理解していただきたいのは、十分な情報提供をしていただきたいということを要望をしておきますので、お願いいたします。ですから、この外部委託についてもありますので、そのことについての答弁をお願いいたします。","respondent":"堀越行財政改革担当課長","answer":"ホストコンピュータのアウトソーシングが予定されているということで、準備を進めているところなんですが、委託して。いろいろな民間委託の仕組みづくりの中で、こういった部分も取り込んで、しっかりとチェックしながら進めていきたいと思っているところです。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問","question":"有益的なパソコンの設計をどうしていくかということなんかにいけば、非常に専門的な知識を要求されてくることは間違いないわけですよ。ですから、将来、品川区の責任という立場で対処できる人材を準備していったらいいんじゃないでしょうかということをお伺いしておりますので。","respondent":"榎本人事課長","answer":"それをきちんとやらないと、委託の効果が十分に生まれないということは、十分に認識しているところです。それに対応する競争会社等がありますので、そういったものを考えたり、いろいろな手法を工夫をしながらやっていきたいと考えております。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"ちょっと単純な質問なんですが、行財政改革の計画が、品川区とどこか２カ所だけ提出されないという記事を読んだんです。あの辺のところは、品川区が進んでいるからかなと思って見ていたわけですが、その辺のところを説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"委員の皆様ご存じのとおり、品川区では昭和５８年からずっと不断の行財政改革を実施してきておりますので、数値目標ですとか。本日、説明申し上げましたように、いろいろな民間委託、こういった形のいろいろなあり方も幅広く検討して、やっていきたいと思っています。","id":"exchange-042"},{"speaker":"中島委員","kind":"質問","question":"ついこの間、５月２６日に成立をしているわけですから、これから新たな分野でしっかり事業の仕分けも展開されるのかなと考えています。どうかということをしっかりと見極めるという作業は大変難しいし、その辺のところは、どのようにお考えになっているのか説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"私どもで、今検討を始めているところは、まず視野といたしましては、全庁的に広げるという形で考えております。そういった形で洗い出しを行いまして、そういうことをいろいろ検証しながら、進めていきたいと考えているところです。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"留意点・課題の一番上のところで、ここでもう少し詳しく教えていただければと思ったのが、モニタリング・評価の仕組みですね。現状、どういう仕組みになっているのか、また、適切に行う必要があるとした背景ですね、そこを教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"それから、全庁的な仕組みを考えた背景というところですが、指定管理者制度が本格的に導入されて、品川区のほうでも６２施設でやっているということ。質の向上を図るために、今、検討を進めているです。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう項目といいますか、それぞれの所管と、指定管理者になった人のモニタリングの基準を教えていただきたい。そこをお願いいたします。","respondent":"堀越行財政改革担当課長","answer":"それから第２点目が、苦情に対する対応が適切であるか、具体的にはそういった項目が挙げられると思います。そういった点を、今、所管で対応しているというような状況です。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"契約の仕様書どおり履行されているかどうかとか、そのお話を伺うと、品川区が評価をするという形になっているんでしょうか。実際に契約どおりに履行されているかどうかというのは、そこをちょっと伺いたいんで、すみません。","respondent":"堀越行財政改革担当課長","answer":"現場で対応ということもありますし、それはいろいろな場面、場面がありますので、組み合わせてやっています。全庁的な仕組みづくりはどうなのかというのを、そういった点を、これから検討してやっていきたいと思っているところです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"情報公開の対象に含まれているのか、どうかということを、一つ伺いたい。一つひとつそうですけれども、その一つひとつに対してモニタリングの資料が情報公開の対象になっていくのかどうか、教えていただきたい。","respondent":"堀越行財政改革担当課長","answer":"今現在、個々で対応しているものを、今年度、きちんと整理して、仕組みづくりを行っていくです。それに対しては、今、ご指摘がありました図書館の窓口等、そういった面も含めていろいろ検討を進めていくです。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"問題なく伺うことができるんですけれども、いまいちそこがよくわからないので、教えていただきたいんです。厚生労働省がどんな労働環境を調査するのか、僕はそこまで知る余地はありませんけれども、そこをちょっと教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"その法人なり、企業なりが責任を持って、法令に則って対処する問題だと考えております。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料で１点だけ、お伺いしたいんですが、教えていただきたい。全体で何人ぐらい派遣職員が配置をされているのか、説明を求めました。","respondent":"榎本人事課長","answer":"そのうち選挙が５７６人ということで、両方で使っておりますので、その部分です。それ以外の部分が、主に保育園、清掃事務所、あとは人事課というか、本庁の育休欠員代替というものです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"意見","question":"保育園のところは、育休とか産休以外でも入っていますよね。その辺で、人材派遣を使っていく基準というものがあるのか、どうか、その辺も説明を求めました。","respondent":"榎本人事課長","answer":"主には育児休業の代替、それ以外に幾つか特別支援保育等の中で、若干スポット的に使えるものについては使っていくということで活用しています。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"具体的に基準は設けられていないんですか。基準というものを設けないで、判断でやっていくのかどうか、ちょっとその辺をお伺いします。","respondent":"榎本人事課長","answer":"正規の欠員については、人材派遣が必要であれば、そういう形でいく。アルバイトとかの対応もありますけれども、資格を持った方が必要な場合には、こういう人材派遣を使っていくという考え方です。","id":"exchange-051"},{"speaker":"中島委員","kind":"質問","question":"民間企業にテナントとして貸与し、賃料を得る方式とあるんですが、しながわ水族館がそのようなあれなんでしょうか。そうすると、入館された率に対してこちらに収入があるのか、その辺のところを説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"民間貸与、管理許可となっていますが、例とちょっと合わない部分があります。こちらについては賃料方式ではなくて、出てきた収益を、区とサンシャイン側で配分するというような構造になっております。","id":"exchange-052"},{"speaker":"中島委員","kind":"質問","question":"了解しました。ただ賃料だけだったら、一生懸命努力するかいがないなと思ったものですから、単純な質問で、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/218784?Template=document&Id=5800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":43780,"voices":129}},{"id":"h18-20060626-6","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"区民委員会","time":"","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"───────────────────────────── １ 議案審査 第４９号議案 品川区特別区税条例の一部を改正する条例 これより…","agenda":"───────────────────────────── １ 議案審査 第４９号議案 品川区特別区税条例の一部を改正する条例 これより…","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"これが今後、どんどん伸びてくるというか、安定的に伸びるかどうかというところがあるわけで、そういう中で、どういう評価をしているか。そこら辺をちょっと聞かせていただきたい。","respondent":"太田税務課長","answer":"平成１６年度統計で、国が６割ぐらい、そして地方が４割ぐらいという形になってあります。景気等の動向により、いろいろ左右される面はありますけれども、税の立場からの認識としては、１歩前進をしたのかなと考えているところです。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問・要望","question":"こちらの方に財源が少し移ってくるということですから、３兆円の移譲だというようなものですけれども、いろいろ議論があったところなわけですね。ここら辺を考えていくと、条例的には正しいんですけれども、制度的な理解も含めたことでは説明をきちんとしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"どういうふうな分布状況だったかというのをちょっと教えていただきたいというのが１点と、こういうところも一緒に見直してしかるべきだと思うんです。ですから、お答えにくいと思いますけれども、もし見解があればお願いしたい。","respondent":"太田税務課長","answer":"今年度に入っても、平成１１年度に導入をされた当初と状況が違ってきているということだろうというふうに、私ども認識しています。来年度、平成１９年度、２分の１がさらに全廃になったときの区の税収に対しての見込みですけれども、約１２億５,０００万ほどの増収になってくる。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"それぞれ教えていただいたんですけれども、現在の国民健康保険料の滞納状況というのはどの程度になっているんでしょうか。あるいは、悪化する方向を私は考えちゃうんですけれども、その辺の見解もちょっと伺っておきたいなと思います。","respondent":"原国保年金課長","answer":"平成１９年度の国民健康保険料の算定をする場合に影響が出てくるんですけれども、その辺がどうなるかというのは、その中で議論していく形になります。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"一番最初に教えていただいた課税対象表の２００万以下が５０％だということなんですが、税率的には一律になって１０％になるんですが、どういう内容であるかというのを一つ教えてほしいと求めました。","respondent":"太田税務課長","answer":"それで、住民税は９,０００円のままで、トータルとしては変わらない。詳細な調整等実施して、所得税を見ていただければ、その分減額です。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"最近の納税や国保等の区の窓口の対応といいますか、相談といいますか、これはどんな状況か尋ねました。","respondent":"太田税務課長","answer":"６月８日に、普通徴収の賦課通知をお出しいたしました。高齢者の方にある１２５万の非課税措置の廃止等によって、お問い合わせが多いのは、昨年に比べて税額が多くなっているというお話が一番多あります。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"定率減税が２分の１になっただけでも、お伺いしたいのは、三位一体改革でこの税の移譲が行われる。その辺はどうとらえているのか、もう一度、三位一体というほど単純なものではないだろうというふうに私は思っているんですけれども。","respondent":"山田区民生活事業部長","answer":"さまざまな社会保障制度と高齢少子社会に対応していく今後の社会構造の中で、必要なこと、税源のとらえ直しをきちっとしていかなければならない。","id":"exchange-007"},{"speaker":"本田委員","kind":"意見","question":"それがどういう形で行われていくか、東京２３区では財調制度なんかもあって、税制改正とあわさって税源移譲という形で住民税が大きくなってくる。区民の希望もそうですけれども、説明責任というものを明確にしていくことが必要だと思うんですけど、その点だけを説明を求めました。","respondent":"太田税務課長","answer":"詳しくは５月２１日の広報紙ないしホームページをごらんくださいというようなことを、私ども、考え得る限りのものをやらせていただきました。なぜ１０％になるのかから含めて、制度改正の内容等についても、十分なＰＲをして説明責任を果たしていきたいと考えています。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"それともこれから、よりわかりやすいリーフレットをつくられるのかというご予定の方を一つお伺いしたいのと、これは概要の方で示されています。そうすると、２２ページの１４条の４と５というのは、なぜこれが新しく区条例の中に書き添えられたのかというのを教えてほしいと求めました。","respondent":"太田税務課長","answer":"法令部分については改正をされてきている部分がありますけれども、細かな部分については、まだこれから詳細に検討をしていきたいと考えています。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"説明をされるような資料をぜひともつくっていただきたいし、地方が非常な役割を担っていくわけですから、お願いをしておきます。表現が今見つからないんですが、投資が盛んになるという社会情勢の中で生まれた、法に伴う条例の追加と考えてよろしゅうございましょうか。","respondent":"太田税務課長","answer":"その他１５％、利子１０％という、免税または５％が減税になる内容です。国内において、相手国との条約を整備する、基本合意に至ったことに伴う国内法の規定整備ということでご理解をいただけたらと思います。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"２点ほど確認をさせていただきたいのは、申告を求めた上」となっておりますので、中には漏れてしまう人も必ずいるのかなという気もするんですがね。確認をします。","respondent":"太田税務課長","answer":"１点目の住宅等借入の特別控除についてのご質問ですけれども、住民税は実施していないものですので、対象者等々の把握はしていないです。１年おくれで実施をいたしますので、実際に平成２０年の１月１日ということであれば、平成１９年の収入に対してということです。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"生計費には非課税だという原則に立ってつくるべきだと考えていますので、そして、ある程度の影響を及ぼしてしまうという問題点があるということ。そうだなと言って、なかなか賛成はし切れないと思いますので、反対ということで表明させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"今、車の事故のお話があったんですけれども、車には、東京二十三区清掃一部事務組合や清掃事務所などが所有している車と、雇上の車がありますね。雇上の車の事故等の場合にかかわる賠償交渉については、どのような仕組み、システムになっているのかということをちょっと伺いたいと思います。","respondent":"島袋品川区清掃事務所長","answer":"ただいまご報告いたしましたのは、車両の関係は直営だけです。清掃協議会で２３区として雇上げるんですけど、雇上会社各社が事故の対応をするということになっています。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"これ、平成１６年度から１７年度、１８年度と３年間にわたった報告なんですけど、それぞれの年度の作業員というか、清掃職員の人数ですね。どういうふうに変化しているのか、ちょっとそれを、平成１５年度もわかったら伺いたいと思います。","respondent":"中山資源循環推進課長","answer":"今、委員のご指摘は、正規職員で見ますと、平成１５年度は２４５名、平成１６年度は２５９名、平成１７年度は２４３名です。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"今回特に５件もあるし、お互いに動いているところの作業ですから、意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"もしおわかりになれば教えていただきたいんですが、清掃車が安全確認を怠ったとなっておりまして、経験というのがおわかりになれば。そういうデータみたいなものを把握されているんか尋ねました。","respondent":"島袋品川区清掃事務所長","answer":"１７号の清掃作業中の誤収集事故は、午前１０時半。それから報告１８号の清掃作業中に起きました乗用車のドアの破損は、午前１０時４５分です。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"再雇用の方で６５歳ですか、昭和１５年生まれの方が清掃車を運転されているようです。これは問題がないということでしょうかね。","respondent":"島袋品川区清掃事務所長","answer":"これは品川も荏原も同様に実施しております。ただ、いろいろな車種や収集作業がありますから、経験と年齢を含め、考えながら配置しているというところです。","id":"exchange-017"},{"speaker":"堺委員","kind":"確認","question":"一遍にこれだけ報告事項が出されちゃうとね、確認しないといけないなと思い、質問させていただきました。くれぐれも安全確認の励行は検討していただくようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"５件で９０万ぐらいの損害賠償というのが出ているんですけれども、事故ですから不可抗力のものもありますので、区のどのような部署で示談交渉が行われるのかというようなことを説明を求めました。","respondent":"島袋品川区清掃事務所長","answer":"作業中の事故なんですが、１７年で２件、１６年で２件、１５年で２件、ここ３年でこういうふうになっております。それから示談交渉ですけれども、当然、警察に届けて、その後、保険会社とやっています。","id":"exchange-019"},{"speaker":"林（和）副委員長","kind":"質問","question":"とにかくそのたびに十分に注意して、事故の起こらないように頑張りますということをいつも言われるんだけれども、全然減らないんだよね。とにかく、不注意からこういう問題が出ているんですから、こういう事故が少なくなるようにもっと努力してもらわないと困るなと思うんですけれども。","respondent":"島袋品川区清掃事務所長","answer":"こういうことが起こると、区民のためにも職員のためにも大変なことになりますから、徹底していきたいと思います。林副委員長の意見が出ましたことを、今後の朝礼等で徹底してまいります。","id":"exchange-020"}]},{"id":"topic-02","title":"７番目の、品川区都市型観光アクションプラン","agenda":"７番目の、品川区都市型観光アクションプラン","exchanges":[{"speaker":"本田委員","kind":"質問","question":"そこに行かないとなかなか、観光のことを教えるということにはならないと思うんですよね。だから、そういう押し出しがあってもいいのかなと思ったんですけれども、その点はどんなご議論、また、どういうお考えか尋ねました。","respondent":"金子産業振興課長","answer":"そこに設置できればどなたもよくわかるということがあると思いますが、品川区の場合には、どこに設けるというのは非常に難しい問題だと思います。ですので、その実施状況を検証しながら、また、今後の場所も含めて検討していきたいと考えているところです。","id":"exchange-021"},{"speaker":"土井委員","kind":"意見","question":"何かと思ったら、職員と間違われて声がかかったんですけれども、「ここに行くにはどうしたらいいんでしょう」と。そういうものがどこかに案内されているとか、そういうことが最初じゃないかなという感じもしますので、検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"伝えたいなと思って伺っていたんですけれども、商店に限らず、そういう角度からの工業活性化みたいな。ちょっと歩くと、東西４kmありますので、その辺はどうなのかなというのを伺いたいと思います。","respondent":"金子産業振興課長","answer":"ただ、２点目の件ですけれども、最近、まち歩きというのがブームで、歩こうという方が非常に多いです。考えておりますが、今後、検討していきたいと考えています。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"もう少し小型でしょうか、駅前から大体１００円ぐらいですか、そういうバスを運転しています。そういうところも一つご検討いただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247239?Template=document&Id=2460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":32478,"voices":74}},{"id":"h18-20060626-7","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"厚生委員会","time":"午前１０時０４分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を114件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それぞれ利用者の方がどれくらいだったのか、登録者と１日の利用人数、それからその利用者が例えば１週間のうちにどれぐらい通われているのかという利用実態というところを教えてほしいと求めました。","respondent":"西島障害者福祉課長","answer":"それから、かがやき園のデイサービスですが、定員は５人です。登録は出たり入ったりがどうしてもありますけど、現在は１０人ということで、利用状況は先ほどお話ししたような状況とほぼ同じような状況です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"同じように全く今までと同じように通い続けることができるということで確認をさせていただいていいんですね。区立の施設が社会福祉法人立の施設の事業の拡大というふうなところに問題なくなれるのかどうなのかという仕組み上のことを教えていただきたいのと。","respondent":"西島障害者福祉課長","answer":"第二さつき園も同じ品川総合福祉センターが実施をしているということで、実質的には心身障害者福祉会館で活動をしていただくという方策を考えたです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"デイサービスをそのまま利用者の方々が困ることなく続けていただけるという措置をとっていただいたというふうなことは本当に評価をすることができる…それともう一つは、確認なんですけど、それは今回の規定に変わったとしても負担そのものは同じだということで確認させていただいていいか尋ねました。","respondent":"西島障害者福祉課長","answer":"実質は２,４００円ぐらいということで、ここも若干利用料としては下がるという形になります。基本的には大きな変動はなくできるんではないかというふうに考えているところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、先ほどの質問の中で、第二さつき園は稼働率が悪いというお話がありました。それとも今後指定管理者制度を使うことによって、稼働率がかなり上げられるような見通しができているのかどうかということをお伺いしたい。","respondent":"西島障害者福祉課長","answer":"例えば天気が悪いと通わないということで、どうしても稼働率が１００％というのはなかなか確保できないというようなことがあります。生活介護と就労継続支援を選択できるという複数の多機能型の機能を、その辺も含めて、これからまた区の考え方も示しながら法人と協議をして。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"教えていただきたいのが、デイサービスが法的にも廃止になったという経緯ですね。それと、今回新しい方法になったという目的というのがどういうものだったのかというのを説明を求めました。","respondent":"西島障害者福祉課長","answer":"週に２回ぐらい通ってリハビリという側面がございましたけれども、自立活動支援センターに行って、このデイサービスについては廃止になったです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、今まで考えていたものと違っていたみたいな、そういうことが受けられている方が起きる可能性もあると思うんですね。はざまにかかる人は必ずいるはずなので、そこはきちんと調査をして対処していただきたいなということで、要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどのご説明の中で、新事業体系まで５年かかるというお話があったと思うんですが、５年の間に区がやっていくという形ですよね。品川区としては、これをどのぐらいの目途で考えていらっしゃるのかという点を説明を求めました。","respondent":"西島障害者福祉課長","answer":"その中で、現在ある施設をどのようにしていくのかという議論が集中的にされるですので、それを踏まえて、４年、５年はおそらくかけないでいこう。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"円滑な移行をできるようにお願いしたいのと、今度大もとの条例が自立支援法になったときに、これはやっぱりどこかで一本化していくのかな。すぐではないのかもしれませんけど、その辺はどういうふうに考えていますかとの意見を述べました。","respondent":"西島障害者福祉課長","answer":"一般的な援護施設条例と使っていますが、そういう言葉が法的にはなくなりますので、どういうふうにしたらいいかということも実は検討いたしました。次の提案のときには検討して、３施設、そのときに検討させていただきたいというふうに考えているところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、心障会館は通所更生というのもありますよね。心障会館もこの通所更生の拡大というわけにはいかないのか、そこら辺の仕切りはどうしてそうなるのかということを説明を求めました。","respondent":"西島障害者福祉課長","answer":"ただし、３カ月平均の稼働率が１０５％を超えると、金額が減額されてしまうというような要素がありますので、西大井福祉園の現在の稼働は８９％です。その辺を総合的に勘案して、一番有利な方法を選択させていただいたです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"よくわかりました。今現に通っている方は基本的には変わらないということで確認させていただいていいのか、このことだけ最後に説明を求めました。","respondent":"西島障害者福祉課長","answer":"基本的に現在受けている、ご本人が希望すれば別ですが、私は通所更生に行きたいとか、あそこに行きたいとか、毎年一定の時期に調査をしますので、本人が希望すればともかく、現時点では現在のいるところで同じサービスを受けるということで考えているです。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"私どももこれについては賛成をいたします。やはり、１人でも多くやはりそういう意欲がわき上がってくるような、そういう施策にぜひとも結びつけていっていただきたいとお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは法律の規定の中で整理をしなきゃいけないというふうなところの中で、デイサービスが廃止をされるという中での工夫をしながら今まで通ってこられている方がそのまま通い続けるという対応をしていただいているということで賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"木下委員","kind":"意見","question":"私も賛成いたします。法律の改正で、負担ですとか、どういう形になるか心配していたんですが、区のほうがその分賄うような形でやっていらっしゃるので賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"一番大切なのは、利用されている方々がどういう状況であるのか。やはり、これからのきめ細かい配慮をしていただいて、品川区としてはサポートをできるだけしていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"三村委員","kind":"質問・要望","question":"実際に社会に出ていけるところの人たちに対して一番負担の多い法律になっているということで、区の対応としては大変努力されているということは認めるものなんですけれども、今回の条例改正については反対をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この条例に対しても賛成です。本来自立支援法は、既に４月から応益負担に変わっているということで、基本的には負担割合が変わらないというふうなところで賛成をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"階層がありますので、預かり保育を仮に５時まで預かった場合、通常保育とどのぐらいの差があるのかというのがわかれば教えてほしいと求めました。それから、これは６時半とか７時半とかという形で延長保育、夜間にかかるようなところまでやることはあるのかどうかを聞きたいと思います。","respondent":"高橋幼保一元担当課長","answer":"これを実施するに当たりましては、水曜日については９時から１２時ということで、５時までということを設定しています。４００円掛けることの２０日間ということでありますと８,０００円、あわせますと１万６,０００円です、預かり保育をしたら。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"最低でも６時、そうすると、保育園のほうの待機児解消のほうに少し貢献できるかなというふうに思っているんですね。これは幼稚園のほうの側の判断で利用できるという形になるのか、その辺いかがでしょうとの意見を述べました。","respondent":"高橋幼保一元担当課長","answer":"これは効果としては私は就労支援の預かりで保育園に限定されることなく預かり保育ができる、待機児の解消も担うものだと考えているところです。ただ、証明書が出せない場合もあるけれど、それは園長との話し合いで今後決めていくものであると考えているところです。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"わかりました。預かり保育ですから、１日過ごすということになると、その辺の体制はどういうふうにされるんか尋ねました。","respondent":"古川児童保健事業部長","answer":"あるいは延長の７時半までを想定いたしませんと、今回７園でやります幼稚園の預かり保育が、幼稚園におけるいわゆる就労支援型の一つのとらえ方。したがいまして、３時から５時というのは幼稚園の中での預かり保育の一つの限界である、このように考えております。","id":"exchange-019"},{"speaker":"三村委員","kind":"質問","question":"定員３０名のところを何名かオーバーするんだけど、逆に保育園のほうから異動とかをしてきて、ちょっと逆にその辺のところが心配なんですけれど。現状、公立幼稚園のほうの定員の状況とかを教えてほしいと求めました。","respondent":"高橋幼保一元担当課長","answer":"３５名でとまっています。平塚幼稚園が４歳、５歳が３５名の定員ということになってございまして、そのほか、二葉幼稚園の年少組が７０名の定員になっているところです。","id":"exchange-020"},{"speaker":"三村委員","kind":"質問","question":"どういう基準で人数がオーバーしちゃった場合、受け入れをしていくお考えなのか、その辺のところをお聞かせ願えますか。","respondent":"高橋幼保一元担当課長","answer":"３２名という定員をつくっているのは、今後そういった３５名を超す場合におきましては、ほかの近くの幼稚園に移るなりということはあります。できたら、本当は３５名より少ない学級編成か望ましいかなと考えているところです。","id":"exchange-021"},{"speaker":"三上委員","kind":"確認","question":"ちょっと一つ考え方だけは確認させてもらいたい。先ほど５時までということだったのかな、そういう対象の拡大をこの７園において９月と来年の１月に実施しますと、そういう理解でよろしいんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"委員のおっしゃるとおりです。先に説明したように、そういった中では、今ご確認していただいたとおりです。","id":"exchange-022"},{"speaker":"三上委員","kind":"確認","question":"そこのところだけ確認させていただきましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７園の幼稚園で預かり保育ということなんですけれども、それからあと、預かり保育は何人までですよというような定員というのはあるのかどうか。現在の幼稚園の職員体制がどういう体制になっていて、預かり保育をやることによって、その体制がどう変わるのかということについて説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"７０名ですと大体１４名ぐらいという想定をしています。それから、５歳児１人という３人体制の中でありますので、幼稚園の先生はその辺を踏まえてその時間についての保育をしていただけると確信しています。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、４歳、５歳児で１４名ぐらいと。","respondent":"高橋幼保一元担当課長","answer":"遊びの中では２人だったりするということがありまして、目いっぱい５時まで、そういったことは考えていません。今後人数が１４名以上増えることになるようなことが起きましたら、その部分についてはまた人の検討はさせていただきたいと考えているところです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"有資格者の非常勤の方といずれかの先生の２人体制というものはきちんと確保されるというふうなことでいいのかということと、それと５時までとなると、どのように考えられているのかを説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"それで、３時なり４時ぐらいのおやつは出す予定です。保育内容については、今幼稚園の先生たちがどの部屋を使って預かり保育をするか、今ある施設の中で検討していただいています。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"台場幼稚園はというふうになっていたものですから、先ほど課長の答弁の中にも、今後待機児解消も含めてというお話があったと思います。ですから、もうちょっと働いている人も、働き方によっては入れる可能性もあるわけですね。","respondent":"高橋幼保一元担当課長","answer":"その部分において、預かり保育を教育課程、教育時間終了後に５時まで行っていますよということは明記してまいりたいと考えているところです。そういった意味での選択肢の中で、親御さんに選んでいただくということになるかと思います。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"これも考え方によっては、幼保一元化の一部ではないかなと私は理解していたんですが、そういう形でよろしいんでしょうか。ですから、もっと広い意味で幼保一元化に向けての一つの方法ですよというふうな見方でよろしいんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"幼保一体施設におきましては、０歳から５歳まで同じ時間帯の中で預かり、それから延長夜間の中での時間の枠ということをつくった施設である。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"そうすると、じゃあなぜ幼稚園の管轄が保育課になったのかなというところだと思うんですが。やはり幼保一元化という形でカリキュラム、そういう考え方ではなく、あくまでもこれはサービスの一環だというふうなとらえ方でよろしいんか尋ねました。","respondent":"古川児童保健事業部長","answer":"そういう二元体制の中で幼稚園がとり得る保護者のニーズに沿った一つの施策と私は考えておりますから、幼保一元化の一つの流れになる。利用者の方々に選ばれる保育園、幼稚園あるいは幼保一体施設を今後とも拡大していく、こういう考え方です。","id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２点にわたってちょっとお伺いします。子どもにとっての条件整備の基準があるのかどうか、あと基準があるのかどうか、そこの基準を教えていただきたい。","respondent":"高橋幼保一元担当課長","answer":"予算についてというと、今年度の予算については、実施時期が９月と１月ですので、１,５００万円程度を予定しています。幼児の心身の負担、家庭との密接な連携を配慮して実施する」というようなことが、必ずしも幼稚園の活動する時間が４時間には限られていないと。","id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"予算は１,５００万円、今年度のところということなんですけど、人件費以外に整備費も若干含まれているんですかね。非常に内容的にあいまいな点が心配をされているわけなんで、十分子どもの条件整備というところに力を入れていただきたいな、これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"我が会派として、目的の中に公立幼稚園における預かり保育、就労支援という問題、その充実、拡充を図るという点で賛成をしてまいります。ただ、その辺で園児の安全ということだけは十分注意をしていただきたいということをつけ加えさせていただいて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"三上委員","kind":"意見","question":"現状の区有財産をどのように有効活用するかという目的にあっては、こういった形で使われていくということは大事なことだと考えています。これからの問題でありまして、現状、そういった考え方でいくんだということであれば賛成したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"就労支援の充実、拡充というふうなところでは、やはり、必要だというふうなところで賛成です。ただ、子どもたちにとっては長時間保育という状況になりますので、職員の体制や子どもたちへの配慮を十分お願いをしまして、賛成といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"木下委員","kind":"質問・要望","question":"私も賛成いたします。そういう部分も施設というよりも、将来的にはそういう部分も含めてより一層の就労支援というのを考えていただきたいなというふうに個人的に思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、それから保育という観点からどういう内容であるべきなのかということは今後つくり上げていっていただきたいなというふうに思っています。どういうふうにこたえるべきかということは、限られた施設等々ありますけれども、考えていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"三村委員","kind":"意見","question":"そういうどこも行き先のない子どもたちが出ないように、そういった子どもたちを優先するような、そういった配慮をぜひお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"議員提出第４号議案、品川区保育の実施等に関する条例の一部を改正する条例についての提案説明をさせてほしいと求めました。年間ベースで総額１億円、施行日が平成１９年１月１日ということですので、今年度分としては２,５００万円という予算が必要だということですとの意見を述べました。","respondent":"須藤委員長","answer":"提出者を代表いたしまして、鈴木ひろ子委員から説明がありました。この件に関しまして、ご質疑等ございましたら、ご発言をお願いいたします。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"たしか平成１６年第１回定例会で議案提出されたと思ったんですが、もう一回理事者からちょっと改定の根拠みたいなものをご説明いただきたい。たしか公平性という観点から出たと思ったんですが、そこら辺についてもう一回ご説明いただきたい。","respondent":"小林保育課長","answer":"区の保育事業は、この間０歳児保育の充実のほか、各種のサービスを利用者の視点に立って進めてまいりました。平成１６年度におきましては、この適正な負担水準を維持するという趣旨で改定を要するという判断で第１回定例会のご審議をいただいたところです。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"ちょっと理事者のほうにお聞きしたいんですが、この保育料が改定になった後、例えば滞納率がかなり上がったりとか、あとは保育料が高くなって困るとかという苦情であるとかご意見とか、そういうのはいかがだったんか尋ねました。","respondent":"小林保育課長","answer":"平成１７年度の保育料の徴収率は現年度分で９９％となるところです。ただ、６カ月の周知期間を経て実施した結果、ご負担については一定のご理解がこの間得られたものというふうに自負しています。","id":"exchange-040"},{"speaker":"三上委員","kind":"質問・要望","question":"対象は２６人、共産党が試算した数字と区のほうが現実に毎月徴収しているわけですから、ちょっとその説明をしていただきたい。その１億円の支出でいいかということにちょっと基本的なことについてお答えいただきたい。","respondent":"小林保育課長","answer":"第三子が４６０万円ということで、全体としては１億７７０万円、１億１,０００万円弱という影響かと思われます。もちろん人数につきましては、秋に向けて若干増えてまいりますので、実際の影響額はこれを若干上回るものと想定されます。","id":"exchange-041"},{"speaker":"三上委員","kind":"質問・要望","question":"数字的にはもう少し増えるという考え方になってくるのかな、こういうことですね。３００万円程度であるのか、年間の所得というのがどういう数字に当てはまるのかと、そこらあたりのちょっと状況をご説明ほしいと求めました。","respondent":"小林保育課長","answer":"９、このＤ１０でご紹介いたしますと、給与の収入ベースで５９４万円から６３７万円前後になるものと思われます。最高階層はＤ２１ですが、その前のＤ２０、１,２６０万円から１,４４０万円ぐらいの範疇にはまるのかなと考えております。","id":"exchange-042"},{"speaker":"三上委員","kind":"意見","question":"もう一つ、昨年か一昨年、厚生委員会で出された資料というのが何かあったと思うんだけど、この改正問題について、その資料というのを委員長、よろしければ、ちょっともう一度お配りいただければありがたいんですがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"三上委員","kind":"質問・要望","question":"この基準のＣ３という項目を見たときに。保育園利用者は８３０万７,０００円という額の相違というのがとれるわけですけど、保育料についての考え方とあわせて、ちょっとご説明いただきたい。","respondent":"小林保育課長","answer":"保育料の改定につきましては、在宅子育て支援との公平性、負担をいだたく区民の納得ということを配慮しながらという形で方針をとってまいりました。","id":"exchange-044"},{"speaker":"三上委員","kind":"意見","question":"それは別としても、やはり家庭で育てていく人たちの応益部分については、もう少し拡大する必要があるという考え方はしていっていいということでいいわけですねとの意見を述べました。","respondent":"小林保育課長","answer":"ご指摘のとおり認識しています。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"これは働いている側とすると、いや、これだけでは評価はできないんじゃないかなというふうに思うんですが、その辺はいかがですか。どういうふうにこの数字を見ていけばいいのかなと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっとずれて申しわけないんですが、先ほどそういう形、数字だけを上げて、今保育料の話があって、保育料に対する施策の中の一端だと思うので、その考え方、この資料が出てきた関係上、これの読み方というのをもう少しご説明いただきたいなと思っているんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今資料をいただきましたが、ある程度の資料が出ていた段階で、この辺の応益と負担の問題というのは十分理解していたつもりです。我々の会派でもそのことは常に訴えておりますが、この議員提出第４号議案に関しましては賛同できないということで、我が会派の態度ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"三上委員","kind":"意見","question":"基本的には反対ということです。すべていろいろな施策の中でそういう子育て支援というものはされていくべきだろうと考えておりますので、またいずれ、私どもは賛成できないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"木下委員","kind":"質問","question":"これは前にも議論されていたところじゃないかなと思うんですよね。ですから、そういうのも含めまして賛同できないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"それから、いろんな要望等をお聞きした限り、確かに保育料を上げることに関しては、不満はあると思います、高くなるわけですから。今回の引き下げについては賛同できないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"三村委員","kind":"意見","question":"ごくごく薄いものであったりということで、やはりまずお金をかけるべきは待機児解消というところで優先順位をつけてきたというふうに考えております。なので、こちらの引き下げについては賛成をしませんということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"提案をさせていただいた立場で、今審議の中でさまざま出された意見もありますので、改めて意見を表明させてほしいと求めました。ただ、子育ての家庭に対して、在宅と保育園というのをこっち、あっちというふうにとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"はい、わかりました。そして、少子化が大変未曽有の状況になっている中、危機的な状況になっている中で改善させるためにということで提案をいたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところが一体１０月からの実施に当たってどうなるのかというところをお聞きしたいんですけれども、この仕組みもちょっと教えてください。この仕組みそのものが要綱か何かで決められているのか、そこもちょっと教えていただけないか尋ねました。","respondent":"西島障害者福祉課長","answer":"それから、移動支援が１,０００万円余です。都は住民税非課税者については３％の適用、均等割の方についても３％の適用ということで、これは要綱で定めてあります。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今ざっと聞いたところでは、国全体で４００億円というふうなところでは、これは国のほうは一般財源に繰り入れられるというふうなことですよね。そのところで、または今までよりも負担を増やすとか、そういうふうなところについては考えていないということでよろしいんか尋ねました。","respondent":"西島障害者福祉課長","answer":"地域生活支援事業そのものについて現在検討中ですので、現行のサービス水準は維持をしていきたいというのが基本的な考え方です。当然この中にはその４００億円も含まれているというふうに聞いてあります。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どれくらい出されているのかということをひとつ教えていただきたいのと、これは視覚障害の１・２級の方と、かなり数が少ないように思うんですねよ。視覚障害の方でも６６名、ここについては、もっと利用しやすくして使えるようにしてほしいという声も障害者の方からいただいているんですけれども。","respondent":"西島障害者福祉課長","answer":"たしか視覚が９０人ぐらい、知的も１５人ぐらい支給決定はしていますが、使われている数字が先ほどの数字です。地域生活支援事業全体の枠組みの中で、総合的に検討して、またお示しをしたいというふうに考えているところです。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"視覚障害の方からも前にお話をお伺いさせていただいて、また、ぜひそういう拡大の方向でご検討いただきたいというふうに思います。２万円、２万５,０００円というふうな形で負担が増えてしまって、ぜひそういうふうな方向でご検討いただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"木下委員","kind":"質問・要望","question":"そして、まだまだ今まで自体もサービスをもっと充実してほしいというお気持ちのあらわれじゃないかなと思っているんですが、国での４００億円のうち。いかがでしょうかということと、この辺もちょっと詳しくないものですから、ちょっとお教えしていただけないか尋ねました。","respondent":"西島障害者福祉課長","answer":"かなりそういう意味では、思っていたよりも負担を受けないで進んでいるんではなかろうかというふうに品川区の場合は考えてあります。日常生活用具給付事業の数値目標を定めてくださいという２番目の項目ですが、ちょっと理解できなかったので、先ほどそのように申し上げました。","id":"exchange-059"},{"speaker":"木下委員","kind":"質問・要望","question":"ただ、現行水準というのをできる限り自己負担が極端にならないような形で努力していらっしゃるというのをお聞きして、少し力強い気持ちになりました。そういう方々に対して応分なご配慮のほう、よろしくお願いしまして、質問を終了させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"三村委員","kind":"質問・要望","question":"どういった方が品川区の中で雇用されていて、企業に求めていくだけじゃなくて、その辺についてお伺いできますか。","respondent":"西島障害者福祉課長","answer":"現在もハローワークと連携をとっておりまして、二月に１回ですけれども、就労相談を実施しています。今年度は来週の４日だと思いましたけども、元気塾、今年度１回目の元気塾が開催をされる予定です。","id":"exchange-061"},{"speaker":"三村委員","kind":"質問・要望","question":"雇用しているからだけではなくて、庁舎内でもぜひそういう雇用の場を見つけられないか検討していただきたいなということで、要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"三上委員","kind":"確認","question":"いろいろご説明を伺いますと、一生懸命品川区はやっている。そのことについて聞くわけにもいかないので確認できませんけれども、皆さん方の、そこらあたりの状況をちょっとご説明いただけないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"三上委員","kind":"質問","question":"そのやりとりがどういうような形でやっているのか、簡単でいいですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、今この請願代表者の方を別として、視覚障害者協会と表現したらいいんでしょうか、そちらの皆さんからは同趣旨の要望書が出されたということで、それに対しては区としてはどういうふうにお答えされたんか尋ねました。","respondent":"西島障害者福祉課長","answer":"まちづくりにかかわる部分もありますので、所管のほうとも調整をしながら、現在回答の準備を進めているところです。現行のサービス水準は下回らない形で自立支援法に対処してまいりたいというふうに考えてありますので、その辺については明確にお答えするつもりです。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現在日常生活用具の給付の費用負担がどうなっているのかということを一つ教えていただきたいのと、それから４月以前、自立支援法が実施されるまでのときのガイドヘルパーの利用負担の状況というのを教えていただけますか尋ねました。","respondent":"西島障害者福祉課長","answer":"なお、地域生活支援事業総体を決めていく中で検討していく内容ですけれども、これから検討委員会を立ち上げて決めていく予定になってあります。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今度の地域生活支援事業が１０月から開始するに当たっては、今までと同じ考え方でいくということでいいんでしょうか。そこのところだけちょっと確認をお願いします。","respondent":"西島障害者福祉課長","answer":"地域生活支援事業につきましては、どのような形で展開するかということを総合的に検討してまいりますので、その中で負担についてもどういう割合でやっていくのかということについて検討していきたいというふうに考えてありますので。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"じゃあ、先ほども要望で申し上げましたけれども、改めてこの請願にあるようにガイドヘルパーにしても、それから日常生活用具にしても、今までどおりの応能負担というふうなことで、負担が増えないようなやり方をぜひとっていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"国のところの予算のベースが年間４００億円というところでは、今後どのくらいお金が要るのかというその辺の見通しなどはたっているんでしょうか。それを一つ伺いたいのと、この負担割合がどう変わってきたのかというのをちょっと具体的にわかったら教えていただきたい。","respondent":"西島障害者福祉課長","answer":"これを１０月以降引き続きやるかどうか、都はまだ検討中ということで、はっきりいたしておりません。どういう地域生活支援事業でどういう形で展開をしていくのかということを検討して、要綱で定めていきたいというふうに考えているところです。","id":"exchange-069"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"すみません、そこを教えていただきたいのと、金額的に幾らぐらい負担をしているのかというのをちょっと教えてほしいと求めました。状況を伺ったときに、毎日外に出ているお仕事をされている視覚障害者のうちの９割がホームから落ちたことがあるというのを聞いたことがあるんです。","respondent":"西島障害者福祉課長","answer":"後段のところはご意見ということで、負担割合のところだけでよろしいでしょうか。現在は、支援費制度の枠組みですので、国２分の１、都４分の１、区４分の１です。","id":"exchange-070"},{"speaker":"飯沼副委員長","kind":"質問","question":"さっき３％のところで、実際に幾らが幾らに変わったのかというお伺いをしたので、そこがわかったら。","respondent":"西島障害者福祉課長","answer":"今たしか１時間半でガイドヘルパーは１,４７０円か、単純にいきますと、４５円ぐらいの負担になっていると思います。ですから、１０時間お使いになれば、４５０円、２０時間お使いになれば９００円、そのような数字になるんではなかろうかというふうに思います。","id":"exchange-071"},{"speaker":"三上委員","kind":"質問・要望","question":"こちらのほうから出されている要望について今取りまとめているという動向があるとするならば、私はそれがまとまった段階で判断してもいいのかなと。ですから、本日のところは継続しておいていただいてもいいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"木下委員","kind":"意見","question":"私、三上委員と同じように継続でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問・要望","question":"私のほうとしては、今日決を採らせていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私どもも視覚障害者の団体の方ともお会いして、要望もお聞きをしております。私どもとしてはこの請願の趣旨を理解するということで、趣旨採択ということで、うちの結論とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"三上委員","kind":"意見","question":"非常に不明であるという点から考えて、どう努力したらいいのかということについて、これは区の理事者の皆さんにたがをはめるというわけにはいかない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国から、補助金というふうな仕組みになっていますので、これは本当に市町村格差がかなり広がってくるんじゃないかというふうにも言われています。ご検討いただきたいというふうなところで、採択ということでお願いしたいと思いますが、趣旨採択でも結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"木下委員","kind":"意見","question":"私としましては、趣旨採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"請願の理由のところを読みますと、非常にこれからの制度ということも含めまして心配されているんだろうなというふうに思います。お考えのほうは十分に理解できますので、これを踏まえて、これからの制度づくりをしていただきたいなというふうに趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"三村委員","kind":"質問","question":"請願の趣旨の１のところ、今まで皆様のご意見をお聞きしましたところ、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"}]},{"id":"topic-03","title":"平成１８年請願第６号、東品川３丁目愛宕倉庫跡地に開設予定のホテルの営業許可に関する請願","agenda":"平成１８年請願第６号、東品川３丁目愛宕倉庫跡地に開設予定のホテルの営業許可に関する請願","exchanges":[{"speaker":"三村委員","kind":"質問","question":"先ほど学校ですとか、保育園ですとかの意見照会をされたということだったんですけれども、どういった意見が上がってきているのか、その内容について、教えていただけますか。","respondent":"高橋品川区保健センター衛生課長","answer":"今のところ戻ってきているのが５カ所でございまして、基本的には問題ない。ただし、営業運営形態が変わったときについては留意されたいということが主な意見です。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっとよくわからなかったところがあったのでもう一度確認させていただきたいんですけど、１００メートル以内に学校等の教育施設があるというふうな場合は、営業許可を与えないことができるというふうなところなんか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"その１００メートル以内の教育施設等ですが、清純な環境が著しく害される恐れがあると認めるときということになっておりまして、先ほどの設置場所が公衆衛生上不適当であるとか、構造設備が政令の基準に適用しないということとは区別されております。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、区としては学校等が１００メートルにあって、清純な環境が著しく影響を受けるというところということでは判断できないということで考えているということか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"著しく清純な環境が害されるおそれがあると認めるときというのは、例えば風俗的営業が明らかなときとかということで、著しくということになっておりますので、その辺については考慮いただきたいと思います。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。概ね１００メートル以内に教育施設がある場合は、ここに対しては、品川区としてはどういうふうに考えられているんか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"指導基準ですので、この要綱の趣旨を業者のほうに説明しまして、ご理解をいただくということで翻意を促すということをやってきたものです。したがいまして、行政手続法もありますので、あくまでも業者にお願いを申し上げるということの要綱です。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうふうな点では、その事前協議をされている時点からこういう品川区には指導要綱があるよということはきちんと指導されていたんでしょうか。それが１点と、また、保健所のほうからの指導というのは１月からどういう形でどれぐらいされてきたのかということを教えていただけないか尋ねました。","respondent":"須藤委員長、高橋品川区保健センター衛生課長","answer":"所管がちょっと違うところがあるので、わかる範囲のところで結構です。逆に変に説明しちゃうと誤解を得ますので、今、衛生課長のほうでおわかりになる範囲でお答えを願いたいと思います。 それと、私のほうで１月からこの業者が来たときに何回も説明しました。具体的な説明でぜひこの辺の考えをお願いしたいということで、区の立場、いわゆる区民の立場を説明したところです。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区としてはこの「スーパーホテル」というホテルをどういうホテルだというふうに認識されて、できればそれを取りやめてほしいということで指導されているのか、ちょっとお伺いさせてください。","respondent":"高橋品川区保健センター衛生課長","answer":"全国５８店舗を展開するビジネスホテルということで、低価格の宿泊場所ということで展開しているホテルというふうに考えております。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これも地域の方からお伺いすると、ご夫婦の２人が夜の９時までしかいなくて、かなり地域の方々は心配されているというふうに思うんですね。それからまた、かなり心配をされていますけれども、そういうところに対してのご見解はいかがか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"もし営業許可をして、営業開始になれば、そういうことになっていくかと思います。同様にその辺についても十分フロントも設置しておりますので、ならないようにしていただきたいということで指導していきたいと思います。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうだけではなくて、せっかくこういうふうな要綱もあるわけですから、そういう環境を守るというためにつくったのがこの要綱だと思うんですね。ぜひ強力に指導していただいて、きちんとした立場で指導をして環境を守っていただきたいというふうに思うんですけど、いかがか尋ねました。","respondent":"谷田部健康課長","answer":"営業許可申請が出され、その申請が旅館業法の法律に照らして許可に値するかどうかというのは、これからさまざまな観点から最終的な判断をするです。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、地域でこれだけの大きな声になっているということと、品川区がこれだけの要綱を持っているということと、このホテルがこういうような実態だというふうなことを踏まえて、ぜひ地域の皆さんの要望に沿える形でどうしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"三村委員","kind":"確認","question":"平成１８年５月２４日、品川区保健センター衛生課に対し、このような事実があったのかを確認いたしました。ホテル経営をされる会社、そういった点について、お考えをお聞きしたいんですけれども。","respondent":"高橋品川区保健センター衛生課長","answer":"行政指導ですので、行政手続法に基づく行政指導の範疇で私どもは何回も説明をし、翻意できないかということで促してまいったところです。その辺については、随時日本開発のほうに説明をさせていただき、また翻意できないかということで指導をしています。","id":"exchange-090"},{"speaker":"三村委員","kind":"質問・要望","question":"その際に間に入っている会社だけではなく、その先にどういった説明をされているか、その辺の確認のところもきちんとしてほしいと求めました。業者の方は、区の行政指導には従いますというふうにおっしゃっておりましたので、ぜひきちんと区の意向を業者のほうに伝えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ほかのところで、こういう名簿をそろえているかどうかというのは、確認を事前にすることはできないんでしょうか。この部分で引っかかっていれば、既に品川のこの旅館業法でおろすことができなくなってくる可能性もあるんではないかと思うんですが。","respondent":"高橋品川区保健センター衛生課長","answer":"かなり１００％近いですが、今ちょっと手元にないんですが、記憶によると少ないところもあります。外国人の不法就労の問題とかいろいろのことがありますので、その辺については宿泊者名簿を必ず備えているホテルがすべてになってくるかと思います。","id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"確認","question":"行政指導できないのかもしれないですけど、やはり先に確認をしておいてほしいなという気が、私はそれは思っています。何人か指導要綱を確認に来たというお話があった中で、ちゃんとその先へ伝わっていったのかどうか、そこら辺の確認はとられているんか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"委任状につきましては、コンサルのところからは写しをいただいております。ただ、この委任状を提出しないと、この申請書を受け付けないということではございませんが、今のところ委任状を確認しております。","id":"exchange-093"},{"speaker":"鈴木（真）委員","kind":"質問","question":"新聞の記事ですから、どこまでも続けていってほしいというのが一つあるんですけど、これから対応としてどのような形をとっていかれるのか。それ以上やりようがないのかもしれないけど、ペーパーベースでこの辺を指摘しておくとか、そういうことはできないんか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"行政指導についてはきちっとした考え方を持って全国的に展開しているものなので、私どももこれから先も十分にやっていきたいと思います。","id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"殊に第４条２項ですか、地域住民との間のトラブルの解消というのは、非常に大きなこれからの課題になっていくと思うんですよね。この上で、この辺のところ、行政指導を続けていっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問したいんですが、そういうのがあったんですが、品川区にはそういうセキュリティに関する規定みたいなものはないんか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"利用者との対応に使うフロント、具体的な指導基準のところにも書いてありますので、その辺については守っていただきたいというふうに思います。どこまで宿泊者を守っていくかということは、十分いろんなところでの経験を生かして建設していただきたいというふうに考えております。","id":"exchange-096"},{"speaker":"西本委員","kind":"確認","question":"もちろん商売ですから、ただ、事前に確認はできる項目だと思うんですよね。そこまで区として安全ですから、それから概ね１００メートル以内に教育施設があるということでは、いかがか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"やはり交通量が多いということ、見通しの問題ということでは、安全性の問題を十分に留意してほしいということを業者の方には伝えております。先ほどフロントの設置ということでは、入口からすぐ目の前、その辺については安全かというふうに思います。","id":"exchange-097"},{"speaker":"西本委員","kind":"確認","question":"そういう仕組み的なものもきちんと確認をした上でセキュリティはどうなんだろうかというところまでお聞きになることができるんじゃないかなと。将来的にはどういう方向に持っていくつもりなのかということは確認しながら、いかがか尋ねました。","respondent":"高橋品川区保健センター衛生課長","answer":"ちょっとこれに当たりまして、私「スーパーホテル」の都内にありますホテルを２カ所視察というか、見学に行ってまいりました。２４時前に何らかのチェックイン、またはホテルに戻ってこざるを得ないのかなというふうなことでは、安全は確保されているのかなと思います。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問・要望","question":"納得いくような方策があるのかどうかということを話し合いを続けていただきたいなというような指導をぜひしていただきたいと思っているんですね。ですから、きちんとそれに応じて話し合いを続けていって、納得いく形で進めていただきたいという指導をぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"三村委員","kind":"質問・要望","question":"ただ、将来的には自動チェックインシステムでテレビカメラで確認すればというような社長の「上質サービス企業に迫る」というようなコメントの中で。ぜひこのホテルの現状を、実態をきちんと把握していただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"後で名前がどう書かれていても、その人が本当に本人かどうかも確認できないわけですよね、写真との照会もできないし。安心というのは品川区の掲げているところですから、部長になるでしょうか、。","respondent":"谷田部健康課長","answer":"私ども旅館業法の許可という部分でしか今回相手方に対する計画の変更を含めた地域住民の皆さん方の意向がどの程度相手方に伝えられるかといったら。","id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区のほうも進めていただきたいということと、私はこの建物そのものもいろいろと精査をしていけば不備があるんじゃないかなという気がするんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"三上委員","kind":"意見","question":"保健所が許認可事項としてどうできるのかと、こういうふうに今現実思っているところですので、もうしばらくこれは私は調査したいな。今後の問題にかかわるかわかりませんけれども、今受けとめている段階ではそういうところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"三上委員","kind":"意見","question":"私は本日のところは継続していきたいなと考えています。一つはやはり、そのものが多少なりとも理解してきたと思っていますけれども、現実どういうものなのかということを１００％承知しておりませんのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は結論を今日出してほしいと求めました。こういうところでは、早いうちに結論を出して、業者に対してもそれが住民の側からの力になるような形で今日結論を出していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"木下委員","kind":"意見","question":"私のほうとしては、継続でやってほしいと求めました。業者のほうが行政のほうのお話、あと業者のほうがどういう対応をするのかというのはまだわかりませんので、私としては継続でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"それは時間がないと思うんですよね。ですから、やはりここで一度決を採らせていただいてという時期かなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"三村委員","kind":"質問・要望","question":"私のほうでも、やはり今日決を採っていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それによって、業者が指導基準の中にもありますけど、営業許可申請を翻意するように勧奨するという部分を強く出していただきたいと思っています。翻意を、ひるがえすような形をとっていただきたいなという意味で、趣旨採択ということで結論を出していただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"三上委員","kind":"質問・要望","question":"結論を出すという話ですから、私は趣旨採択ということで、本日のところは申し上げたいと思います。これは建てるなというわけにはいかないという前提から考えたときに、それはきちっとやっていっていただきたいと、私は趣旨採択でお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はここの請願事項は極めて当然だなというふうに思います。指導要綱および同指導基準に対して明確に違反をしているわけですから、お願いしたいと思いますけれども、趣旨採択でも結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"木下委員","kind":"質問・要望","question":"継続でというお話をさせていただいたんですが、採択ですので、本当に住民の方々の不安を解消するためにも、要綱に沿った形で強く要望していただいて、業者の方の考え方を少しでも変えていただきたいという願いを込めまして、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"要は、どういう環境にしていったらいいのかという中での、それがいろいろこれからいろんな業者が入ってくると思うんですね。私としては、お気持ちは非常にわかりますので、趣旨採択という形にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ指導要綱をきちんと守ってほしいということを業者のほうに伝えてほしいと求めましたので、全会一致を見ることになると思いますので、趣旨採択でも構いません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285470?Template=document&Id=3148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":73150,"voices":258}},{"id":"h18-20060626-8","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"建設委員会","time":"午前１０時０３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件整理しています。","topics":[{"id":"topic-01","title":"第５３号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第５３号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"２５カ所全体であると思うんですけれども、今回対象になっている２０施設ということで、その辺を教えていただきたい。指定管理者は期間５年間というところで、導入時期が６段階にずれているということで、その辺のところをちょっと教えてほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"これは先ほど条例の改正の部分でご説明をしたんですけれども、その２０施設が、指定管理者に導入するという２０施設です。したがいまして、それまでの間は現行どおりに単年度契約による業務委託を継続したいと考えております。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"残りの有料５カ所と、無料１０カ所の管理については、現行どういうふうに考えていけばいいのか。その有料の５カ所、その辺の考え方を教えてほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"大崎駅につきましては、これは全体の中で、今、再開発を実施をしておりまして、地下駐輪場の予定もあります。そういった関係で３月に終わってしまいますので、これは導入をしないです。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"今、２０カ所を指定管理者にするというところと、その先はどういうふうに見通しを立てられているのかということが１点。先ほど条例のほうの説明のところで、それは具体的にはどういう意味なのかということがよくわからなかったので、まずその２点をお願いします。","respondent":"松嶋交通安全担当課長","answer":"下神明であれば２６号線の整備、戸越公園につきましては駅の改良を検討しているということでありまして、それぞれに新たな駐輪場ができる予定です。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"２０カ所一括の指定管理者を予定していると言われていましたけれども、この２０カ所と同じように、ここにどういうふうに指定管理制度を導入していく予定なんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"これも今後、協議を進めていきたいと考えております。続きまして、無料駐輪場が新たな整備をされた後ということなんですけれども、そのときに改めてプロポーザルは実施をしたいと思っておるところです。","id":"exchange-004"},{"speaker":"井上委員","kind":"確認","question":"いいのかどうかの１つ確認と、どういうことで一括にしようとされたのか、そのことは決定なのかどうなのかということ。","respondent":"松嶋交通安全担当課長","answer":"２点目のサービスの向上の部分で、一括した理由ですけれども、実は導入時期によりまして私どものほうもいろいろ検討いたしました。そういった検討もしたんですけれども、１社で導入する理由がすごくメリットがあるという考えのもとで１社にしていきたいです。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"改修にした場合には、改修の限度額をどうするのかという、その辺のところの確認をさせていただきたい。は料金制度をどうするのかということと、どれだけの裁量が事業者にされていくのかという、とりあえず２点お願いします。","respondent":"松嶋交通安全担当課長","answer":"これは検討した結果として、利用料金制度はとらないという方向で進めていきます。例えばこういう改修をやったときに莫大な費用がかかるとかということも可能性として考えられますので、そういったものもあわせて検討をしています。","id":"exchange-006"},{"speaker":"井上委員","kind":"意見","question":"途中で１回切りますけれども、１つだけ。今まで区がそういう改善策をとられてこなかったんだと思うんですけれども、そういうところはどのように考えているのか、考え方だけお願いしますとの意見を述べました。","respondent":"松嶋交通安全担当課長","answer":"これは今後、指定管理者となったときに、効果が上がるのかというものもあわせて提案を受けていきたいということで考えております。例えば、そういった施設自体の変更、そういったものが経費の縮減なんかにもつながっていくのではないかというように考えております。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"今の課長答弁の中で、戸越公園駅に新たな駐輪場ができる、急行がとまるのでというように聞こえたんですが、その点、間違いないか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"これは、戸越公園に急行ということではございませんで、現在のところ、電車が出てしまうので、そこのところの改修がどうしても必要になってくるだろうです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"区にお考えを伺いたいのは、腐敗を防ぐ仕組みには何が必要だと思っているのか、まずそのお考えを伺いたいんです。なので、まず不正、腐敗、どのように考えているのかお聞かせほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"日報、月報、それぞれによって上げてもらいまして、その辺が不正ができないように十分にこちらで監視をしていきたいと考えております。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"第４回定例会になるのでしょうか、指定管理者の選定になれば、議会のチェック、そのときの仕組みづくりが大事だと思うんですよね。もう一度お伺いしたいことと、どれぐらいの区の管理費というんですか、具体的にそれはどういう意味なのか教えていただけますか。","respondent":"松嶋交通安全担当課長","answer":"１点目、それをよく精査をして、そういったことのないように十分に検討を重ねた上で選定をしていきたいというように考えております。今、２人でやっているものを１人にするとか、人的なものはそういったところが考えられようかと思います。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、結局、その民間は一定の利益を上げなければ会社として運営できませんよね。真ん中に１つ会社を置く、その指定管理者の先ほどから言っている３つの導入の理由がよくわからないので説明いただきたいんです。","respondent":"福田まちづくり事業部長","answer":"現在、２つの企業がこの駐輪場の業務委託を受託しておりますけれども、我々はそこではなくて、広く公募をするという方針を持っております。しかし、そのことに期待したいと思っています。","id":"exchange-011"},{"speaker":"中塚委員","kind":"意見","question":"安かろう、悪かろうの流れをどう住民の信頼にこたえて目的に沿って事業を進めていくか、そのことを僕は話しているんですよね。そういう中でどうあるべきなのかということを指定管理者の中で延べました、意見としてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"三伺いたいんですが、ちょっとそこのところを具体的にどういう中身なのか、ちょっとお伺いしたい。ちょっと、今後の考え方はどういうふうになるのか、具体的に今がどういうふうに変わるのかということを具体的なところで聞いておきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"これはまだこれから検討するところですから、ちょっとじゃあどこへという話ではないんですけれども、それはまだ検討の段階です。第３で、ちょっとウナギの寝床のように３カ所でやっているんですけれども、それを１つに集約をして駐輪場としたいと考えているところです。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと確認したいのは、中延のエレベーターとの関係での説明なんですけれども、この中延は３カ所あるんですけれども、実際にどこをこれによって廃止されることになるのか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"中延の第１、場所的にちょっと今、地図をお持ちしていないのでちょっとわかりませんけれども、もし必要であれば後でお答えします。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問・要望","question":"第１だと、定期のほうだったか。どこかというのは、ちょっと後で確認させてほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"２０カ所を一括で委託したいと、どちらがいいのかと、そういうことが通常行われると思うんです。民間の競争原理、これがどういうふうに働くのだろうかと思うんですけれども、そこのところはどうなるんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"選定委員会を開催いたしまして、現在の今の予定では、第１次、第２次審査でやっていきたいと考えています。おおむね３社ぐらいに絞りまして、第２次審査で、このときにはヒアリングを実施してやっていきたいと考えております。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、この１社にやるとなると、これは保証されないと思うんですけれども、そこをどうかということを改めて伺いたい。具体的にわかりやすい基準をどうつくるかということと、もう１つ、そこのところをちょっとお伺いしたいと思います。","respondent":"福田まちづくり事業部長","answer":"利用料金、何らかのそれに報いるような方法、そういうものもこれから具体的に検討していきたいというふうに思っています。そういう具体的な検討の中で、民間の活力、これを発揮してもらいたい、これが我々の考えです。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"もう１つは、やっぱり市場原理の一番のメリットであることが生かされてこなくなると、今の説明だと、どうもやっぱり納得できる話ではないんですよね。そこのところでもうちょっとわかりやすくお願いしたいと思いますとの意見を述べました。","respondent":"福田まちづくり事業部長","answer":"この前のご質問にお答えする形になるんですが、そういう選考基準を用意し、これは公開をする予定でおります。これは区全体の方針でありますけれども、そういうふうに考えておりますので、そのときに明らかにさせていただきたいと思います。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"もう１つは、その指定管理者の下請けになる、そういう可能性も出てきますよね。実際に同じ仕事をやっていて、そういう場面は実際にあり得ると考えているのかどうなのか、ちょっとお伺いしたいんです。","respondent":"岩田まちづくり事業部次長","answer":"ちょっとお答えになるかどうかわからないんですが、今日の説明資料の裏面にも書いてありますけれども、このとき大井町を口火にやり始めました。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"確認","question":"最後の１点なんですけれども、ちょっと確認しておきたいことがあります。ほかのところも同じになりますけれども、どういうふうに考えているのか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"これは例えば中延第２、第３のほうに鞍がえができるのかどうか、それはもう今後早急に検討していく課題かなと考えているところです。","id":"exchange-020"},{"speaker":"藤田委員","kind":"質問","question":"目的はやはり利用者、要するに、区民のサービスがどうあるべきだろう、これがやっぱり一番の根本になると思うんです。こうした場合の保険というんですか、やはりどういうふうになるのかなということを疑問に思っているんですが、それだけちょっとお話しいただけると。","respondent":"松嶋交通安全担当課長","answer":"区に設置者、例えばそういった自転車が壊された云々の場合には、やはり管理責任として指定管理者が賠償責任を負うと。区はどうするかと言ったら、そういったものをやらなかったりした場合に、その管理者に対しての設置者としての責任を負うということで考えております。","id":"exchange-021"},{"speaker":"井上委員","kind":"意見","question":"１社にすることも含めて、この２０駐車場の中で入っている業者というか、そこのところはどうなるのかということをとの意見を述べました。","respondent":"松嶋交通安全担当課長、岩田まちづくり事業部次長","answer":"新たな業者、別の業者が入ったときに、そういったシステムを新たに構築をしていかなくてはならない。そうすれば、莫大な金額も当然出てきますよという話です。そういうことですので、どちらにしても、機械については新しいものに変更していかざるを得ないだろうというふうに考えております。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"業務だけではなく、システムがいかにすごく大きな今度は指定管理になると思うんですけれども、そういうことか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"５年もすれば旧態依然としたタイプになってしまいますので、一応、リース期間は５年で償却という考えで当初からやっています。より使いやすい、そういった機械にしますし、よりきちっとした管理ができるようなシステムも導入させたいというふうに考えております。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"平成２４年３月までですから、また２年間残るということは、そういうお金とかというのはまだこれからか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"１つは、それとも５年間だけのものですから、それぞれを含めて業者のほうから提案を受けたい。それで判定をしたいというふうに考えております。","id":"exchange-024"},{"speaker":"井上委員","kind":"提案","question":"当日が１２４％とか、提案として、定期のところを縮小して当日の部分を多くしたほうが利用率が上がりますよというような個々の提案があった場合に。そこはしないまま何かいい案があれば受けますよというわけにはいかないと思うんですけれども、そこのところの対策はまずはどうしていくのか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"今回、当然やはり駐車場、駐輪場の関係について素人というわけではないと私は考えております。それにかわるものとしてこんなものもありますよとか、そういったものも提案の中に出てくるのではないかと、私はそのように考えているわけです。","id":"exchange-025"},{"speaker":"井上委員","kind":"提案","question":"提案以前に、一昨年も提案をしていますけれども、区として利用が上がるような設置をぜひしていっていただきたいというふうに要望したいと思います。お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"意見表明ですけれども、この第５３号議案には反対です。指定管理者の選考も不明確だし、民間の活力と言いますけれども、なぜ１社かというのも理解しがたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]},{"id":"topic-02","title":"平成１８年請願第４号、南品川３丁目５番地１５号の防災広場に関する請願","agenda":"平成１８年請願第４号、南品川３丁目５番地１５号の防災広場に関する請願","exchanges":[{"speaker":"宮崎委員","kind":"確認","question":"請願のほうは防災広場にしてほしいという請願ですけれども、今回はマンション建設ですけれども、そういうものの制限というのはあるのかどうなのか。今回は木のすぐ横の大きなマンション計画なんですけれども、そういうものは全く制限されないものなのかどうなのか確認したいんですけれども。","respondent":"藤田道路公園課長","answer":"幹周りが５ｍ３５、高さが２５ｍということで、樹齢は約６００年ほどあるという大変立派なイチョウです。今、教育委員会のほうでは、極力この木を今後も成長よく育てて守っていくための話し合いをしているというふうに聞いてあります。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"何か規則とか、そういうものをどういうふうに守って後世に伝えていくのかというところの規則、今回は木ですから当然根が張っています。今、協議で話し合っているその根拠、そんなものはあるのか尋ねました。","respondent":"齋藤住宅課長","answer":"ただ、あまりにやってしまうと今度は木が枯れてしまう。そこで我々教育委員会も住民の方のほうも、枯れないように何とかできないかということで苦労している、こういうことです。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"そういう意味では、しっかり整備がされていないというのが非常に問題かなというように思うんです。もっとわかりやすいものをつくっていくことも必要ではないかなと思うんですけれども、そこら辺のところは区のお考えというのはどうか尋ねました。","respondent":"福田まちづくり事業部長","answer":"ですから、これを法律で、あるいは条例によって規制しようというのであれば、それはよほど慎重に検討しなければならないと思っています。例えば国が法律をつくるときも、やはりそういうようないろいろなことを考えながらつくっていくと聞いております。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとあまり具体的な中身ではなくなってしまったところもあるんですけれども、感想も含めて質問させていただきました。何かあったらどうぞ。","respondent":"岩田まちづくり事業部次長","answer":"実際は例えば８階建つ地区でも５階にしようとか、４階を限度にしようとか、それはなかなか難しいのが現状です。したがって、委員がおっしゃったことも含めて、こういったことがいろいろ考えられますよということをきちっと区が説明をし。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"民民の話し合いというか、対応してきたんですが、今回のこれはその中に大イチョウがあるということで大変苦労していると思います。建主のほうがある程度それを考慮したいと考えているのか、単に答えが出ないので窮して長引いているのかどうか、この辺のところはどうか尋ねました。","respondent":"齋藤住宅課長","answer":"教育委員会には、うちの道路公園課でとめているというわけではございませんで、事業者のほうで、若干話し合いの場が持たれているという現状ですので、話し合いの場は持たれていると聞いてあります。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"古い建物ですから、相当昔からいるのでしょうから、今さら協議して４階しかいけませんよというのは無理ですから。その辺はどうか尋ねました。","respondent":"齋藤住宅課長、岩田まちづくり事業部次長","answer":"法律上、そのようなことを申し上げる権限はございません。ただ、話し合いの場を持つように、こういうことは条例に基づいて設定はできますけれども、権限はございません。当然、これだけ大きな記念物ですから、枯れさせたりしないような十分な養生をしていただくのは当然だと考えています。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"本当に緑のイチョウが大事なら、私はお寺のほうも早く話し合いに応じて、実際に木がどうなのか調べるべきだと思うんです。実際に法律的には何のあれもないんですから、話し合いに、調査に応じないと何もできませんよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"本多委員","kind":"意見","question":"この南品川地区におきましては、品川地区全体で見てもマンションがかなり増えていて、人口も相当伸びていると思うんです。そういう近隣のいろいろな貯水槽とか、そういうものとあわせて、この地区の防災機能を上げるというところで改めて見解を聞きたいと思いますとの意見を述べました。","respondent":"久保田防災課長","answer":"ということは、先ほどまちづくり事業部のほうから説明したとおりです。１つは防災機能の強化ということはあるんですが、今、それで防災上全体の強化になるというふうな考え方にはなかなかなり得ないことではあるんです。","id":"exchange-035"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほどから出ております品川区が認定している天然記念物第２号の大イチョウですけれども、それを守っていくというんですか、ケアをしていくという。その４００年以上、もっと古くて６００年というところですから、そのところをもう一度お願いしたいと思います。","respondent":"藤田道路公園課長","answer":"私ども、同様な制度で保存樹という、大きな木をこれからも大切にしていきましょうというような形での事業をやってあります。それをお手伝いするということの意味で、おおむね３年に一度ぐらいの剪定、引き続き緑を守っていくというような観点で事業を進めていくものです。","id":"exchange-036"},{"speaker":"本多委員","kind":"質問・要望","question":"緑比率の話も当然考えて、この請願につきましては、やはりこの権利の話だけではなくて、行政としてもできる限り対応していただきたいという意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"そうじゃない、品川区のみどりの条例は、品川区の天然記念物の趣旨はどういうふうに区自身が理解しているのかということを伺いたいんです。そこに込められている住民の気持ち、そこがその条例にあるのではないかなと僕は思っているんですけれども、区の見解を聞かせていただけますか。","respondent":"藤田道路公園課長","answer":"今まであったものを大切にし、なおかつ新しく増やしていく、これが緑の条例の中で私どもは考えていますし、進めていくものです。お手伝いはできますけれども、すべて私どもができているというふうには考えてございませんので、そういった考えを国や東京都のほうへ申し入れるです。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"どうもあるものを切っちゃだめ、それは新しいものを増やすにはしようがない、そういうものでしょう。もっと中身のある、趣旨のある条例ではないのかなというふうに僕は思っているわけですけれども、違うんか尋ねました。","respondent":"藤田道路公園課長","answer":"ただ、私権というものがある中でのお話ですので、そういった観点を忘れてはいけないのかなというふうに考えてあります。今、国のほうも検討しているというふうに聞いてありますので、そういった動きを重視していきたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"だから、良好な住環境を確保する責任を建築主に求めているわけですよね。だから紛争予防条例が建築主に対して一定の責任を説明、住環境への配慮を求めて、その関係をどう理解していいのかなと。","respondent":"齋藤住宅課長、岩田まちづくり事業部次長","answer":"話し合いの場を持つようにということでお願いをしております。現在、事前協議が長引いているのも、こういった区のお願いのあらわれだと思います。 だから、所有者が同意しなければ、区だけで一方的に天然記念物に指定することはできない仕組みになっております。条例に基づく所有者義務があるわけですから、品川寺がまず説明を聞くという段階に来ている、まだそこだという段階です。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"やっぱり私たちの感性が経済優先の効率だけを求めたまちづくりから少し視点を変えていきましょうよという区民の方、そんなに高い建物が建っていない。品川区も力を入れてほしいと思うんですけれども、その辺について何かご意見があればお伺いしたいなと思うんですけれども。","respondent":"阿部都市計画課長","answer":"ただいまの旧東のお話ですけれども、ご承知のように、あの地区をモデル地区として景観まちづくりをしていこうという考えです。そこでは私権の制限もありますので、なかなか難しいというふうに考えます。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"高さ規制は行政がこういう方針でやろうよという形で出して、そこに地域の住民の議論が巻き起こってできるものというふうに聞いていますが、その辺はどうなんか尋ねました。","respondent":"片田建築課長","answer":"中央区等々で、それを一部適用したところの考え方として認識していますので、合意形成というものが基本になってくるのかなと考えています。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"地域の方たちの合意とか、区長には要望として出されているわけですから、もっともっとこの地域をどういうまちづくりにしていきたいかということを。もう一つ、「え、そういったところでまちづくりをもっともっと区民を含めて考えていくという取り組みに力を入れていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"藤田委員","kind":"質問","question":"ですから、これは私たちとしてはこれは十分関係者で話し合ってもらわなきゃいけない。あるわけですから、もう一度この住民の皆さんの意向を確かめて、今後施策を進めていってもらいたいなというふうに考えざるを得ないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと１点確認したいんですけれども、電波障害とかたくさんあるんですけれども、このイチョウの木に対する対策というのはここにないんですよね。業者の方、こういうイチョウの木が存在するということは知っていてこういう計画を出されたのかどうなのか、その辺の事情はわかりますか。","respondent":"齋藤住宅課長","answer":"ただ、文化財に指定されていた樹木だというふうには認識はなかったと思います。来て相談されて初めて品川寺のイチョウの木が指定されている木だというふうに理解したと思います。","id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"それで、じゃあ、どうするのかということが問われてくるんじゃないかなというふうに思うんです。大きな一流企業ですから、建設する権利というか、かなり主張されているというところなんか尋ねました。","respondent":"齋藤住宅課長","answer":"ここは地区としても近隣商業で第３種高度地区ですので、かなり資産価値が高いもので、もし時価で買おうとすると、かなり高額のものになります。","id":"exchange-046"},{"speaker":"宮崎委員","kind":"意見","question":"私も最初に言いましたように、やっぱり区としてどう考えるかというのは、やっぱりそこは問われているところだなというふうに思います。以上、感想ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"２ですから、どう考えても品川区の必要な財源を危険度２のところで使うのかということになると、なかなか採択というところまでいかないと思います。防災広場、公園にはできなくても低層の住宅なら根っこは大丈夫ですから、あるいは陣屋の跡地等々を復元したって可能なことは可能なわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"大西副委員長","kind":"質問・要望","question":"およそ２回、３回との話し合いは行ったということにおいての恐さも私の推測ですから、そういうところもあろうかというふうに思います。品川寺の求めるものというのは、あとは行政がよい知恵を出していただくことを強く求めるところですが、いかがなものか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"区は買うとも買わないともまだ今の時点では全く検討もしていない段階ですが、議会の委員の皆様方に説明をするに当たって。区のほうでどんな対応をできるか、副委員長のご趣旨に沿えるかどうかわかりませんが、いろいろ検討してみたいと考えています。","id":"exchange-049"},{"speaker":"大西副委員長","kind":"質問・要望","question":"およそ、今、事情が少しわかりました。命ともどもに守るべきものを行政がうまく区民の方々にアドバイスしていくという存在であっていただくことを強く求めるところで、伝統であったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、何回も同じ発言になるかと思うんですけれども、ぜひ区のほうも今の意見を酌み取っていただいて対応していただければと。事業者の方もやっぱりこういう重要なイチョウの木を、また住民の方々もぜひ酌み取っていただければなと、感想も含めて言いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"藤田委員","kind":"質問・要望","question":"３丁目には防災広場が一つもないというふうに書いていますし、周辺を見て、ぜひとも検討していただきたいなというふうに要望しております。ですから、ぜひ区としてもできることなら最大限の行政指導をしていただきたいと、このように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-03","title":"の「平成１８年度 区民・都・区合同立会川環境美化運動について」","agenda":"の「平成１８年度 区民・都・区合同立会川環境美化運動について」","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"毎年何人ぐらい参加されているのかというのを教えていただけますか。","respondent":"原田下水道河川課長","answer":"毎年総勢で１５０人ぐらいです。","id":"exchange-053"}]},{"id":"topic-04","title":"の「区営住宅（空き家）入居予定者登録募集について」","agenda":"の「区営住宅（空き家）入居予定者登録募集について」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"建物ごとの登録をしているというようなことを伺ったかと思うんですけれども、困窮度のある人が品川区内だったらいいんだというようなこともできるような仕組みに変えることも検討してほしいというのが建設委員会で出たかと思うんですけれども、変更がなっている部分というのはあるんか尋ねました。","respondent":"齋藤住宅課長","answer":"どこでもいいというふうな選択のされ方をしても、この住宅がいいという選択をされる方がいる以上は、公平にお呼びができないんです。その方との調整というのが、あきが少ないのにできない、それが実態です。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"その前に登録をした段階でどういう状況かというのはデータとしてあると思うんですけれども、そうなのかもしれないんですけれども、できないんか尋ねました。","respondent":"齋藤住宅課長","answer":"それとゼロから２５の階層の方には、必ずしも公平には当たらないというふうに考えておりますので、区の今の実情では難しいと。２ＤＫ、３ＤＫにお住まいの方で、なかなかそこまでは細かくできないというのが実情です。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問","question":"ちなみに、昨年度、今、空き家１２戸ぐらいとおっしゃっていて、昨年は何人申し込んで、何人登録できて、そして何人入れたのかということか、どういう状況だったんか尋ねました。","respondent":"齋藤住宅課長","answer":"今のところ、１４人の方が入居しています。応募の戸数は、家族向けが５００世帯で、単身が約２２０世帯ぐらいです。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"いずれにしても、転居をしたり、亡くなられた方もおりまして、１４ぐらいしか空かない中で、競争率が非常に高くなっているということですけれども、改めて、区営住宅、都営住宅の移管なんかも含めて、区営住宅の増設等についてどういうふうな考えなのか、改めて伺っておきたいと思います。","respondent":"齋藤住宅課長、福田まちづくり事業部長","answer":"現在、新たな区営住宅の新設についての考えはありません。いつかもお答えいたしましたけれども、品川区の区営住宅対１世帯、品川区はその平均値を上回っている状況にあります。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"提案","question":"そういうお話だったらあえて聞きますけれども、やっぱり、住民の要望ということで、近隣区と比較ということよりも、住民の要望を非常に考えるべきだということを改めて提案したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"松澤委員","kind":"質問","question":"区営住宅についてはわかったんですけれども、区民住宅は現在、どれくらいの入居率か尋ねました。","respondent":"齋藤住宅課長","answer":"９８％くらいの入居率でございまして、併設型区民住宅では空きが１０戸出て、建設型が２戸です。借上型のほうにつきましては１４戸ぐらいということになっております。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点目の、この辺は予定登録者の募集をするんですけれども、昨年募集して、今年も募集する、それに同じ人が募集する割合、そういうのは調査されているのかどうか教えていただきたいのと、募集する人の年齢、そういうのはつかんでいらっしゃるのか、つかんでいたら教えていただきたいんですけれども。","respondent":"齋藤住宅課長","answer":"入居者のデータはとっておりますが、入居登録者等のデータはとっておりません。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"いろいろと改善すべきで、埋まるように何とか対策をとるべきじゃないんですかというご意見があったような気がするんですけれども、入居を進める対策みたいなものはどうやっていらっしゃるんか尋ねました。","respondent":"齋藤住宅課長","answer":"空きは、若干増えているのが現状です。区といたしましても、オーナーの方に働きかけをいたしまして、下げる方向で交渉を頑張っているです。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"具体的に増えているというのは、今現在１４戸で、その少し前の４年くらい前のデータというのは、今あったりするんか尋ねました。","respondent":"齋藤住宅課長","answer":"すいません、区民住宅のほう、ちょっと持ってきていません。","id":"exchange-062"},{"speaker":"井上委員","kind":"確認","question":"じゃあ、後でいいです。それの確認なんですが、毎年か毎月毎月、区がそこを補てんしているという状況か尋ねました。","respondent":"齋藤住宅課長","answer":"はい、そのとおりです。","id":"exchange-063"},{"speaker":"井上委員","kind":"質問","question":"そこに対して何らか、家賃を下げてください、下げませんということでは、契約が何年間というのであるんだけれども、そのことに対して、このままでいいとは思っていらっしゃらないと思うんですけれども、どういうふうに考えていらっしゃるんか尋ねました。","respondent":"齋藤住宅課長","answer":"抜本的な見直しを検討しておりまして、まだ検討段階なんですけれども、国の施設は収入がないと入れないんです。区でもそういったことを導入して、今は収入がないけれども、資産があるから入れるということも検討しております。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"そもそも、この借上住宅というのは、目的が住宅を増やしてほしいというものなのか、それとも、区民に対して優良な住宅をあっ旋するというというものなのか、区民住宅の借り上げというのは何かを補てんするためにこういう制度ができたのか、そのところは何なんか尋ねました。","respondent":"齋藤住宅課長","answer":"ワンルームマンションが１５万、２０万の家賃ということがありまして、中堅ファミリー層に住み続けていただきたいということが本来の目的でした。バブルがはじけて家賃が下がってまいりまして、現在の、委員からご指摘いただいた部分が出てきているです。","id":"exchange-065"}]},{"id":"topic-05","title":"の都営住宅（地元割当）入居者募集","agenda":"の都営住宅（地元割当）入居者募集","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"同じような質問なんですが、今回２戸ということで、地元割当って一体何戸ぐらいになってきているのかというのがわかったら教えていただきたいんです。年度ごとでもいいんですけど。","respondent":"齋藤住宅課長","answer":"大体、２戸か３戸です。","id":"exchange-066"},{"speaker":"宮崎委員","kind":"意見","question":"２戸というのは珍しいぐらいだったんじゃないかと思うんですけど、最近はこのぐらいが当たり前みたいな感じなんですよね。そういうところを聞いているんで、欲しいとか欲しくないということじゃなくて、実際の動きがどうかということの意見を述べました。","respondent":"齋藤住宅課長","answer":"３件ぐらいしかありません。","id":"exchange-067"}]},{"id":"topic-06","title":"の平成１８年度マンション管理セミナー（第１回）の開催","agenda":"の平成１８年度マンション管理セミナー（第１回）の開催","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"６０名なんですけど、これより多く来た場合、どうするんか尋ねました。","respondent":"齋藤住宅課長","answer":"若干であればいすを用意して対応したいと思います。１０名、２０名であれば対応できます。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"マンションの管理の中で、相談の中で、先ほどもお話の中で理事長も持ち回りとのお話がありましたけれども、そのほかにもどんな相談内容が多いのか、割合などももしわかりましたら説明を求めました。","respondent":"齋藤住宅課長","answer":"割合まではちょっとあれですが、最近多いのは近隣のペットですとか、ペットを飼っちゃいけないのに飼っているとか、組合そのものがつくられていない。１０年目、２０年目、こういったお話が来ております。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"２０年後にどういう修繕をするかというお話で、１点だけ区のお考えを伺いたいんですけれども、被害が拡大するわけですよね。そういうのは、区としてはどんなふうに働きかけているのか、それだけ説明を求めました。","respondent":"齋藤住宅課長、片田建築課長","answer":"実は、品川区では、震災のときに倒壊の危険のあるマンションというのはありません。ただ、その中で耐震の問題にどう対処すればいいのかという話も出てくると思いますので、そういった相談にも応じてくださるようにお願いしております。 マンションの耐震ですけれども、５月からは民間のマンションについて、構造の相談ということで、毎週水曜日、開設しています。管理業協会との連携の中で、専門家に来ていただいて、９時から１４時までということでやってあります。","id":"exchange-070"},{"speaker":"大西副委員長","kind":"質問","question":"ちょっと１つだけお伺いしたいんですが、その部分というのはどういうふうに、進めていこうというふうに考えられていますか。","respondent":"齋藤住宅課長","answer":"今のマンションで町会運営をしたいというふうなご要望もございました。３年ぐらい活動してみて、分譲マンションではなかなか、一般の町会と同じような取り組みというのは難しいことではないかというふうに思います。","id":"exchange-071"}]},{"id":"topic-07","title":"の大崎駅東口第３地区における地区計画区域内事業の現況","agenda":"の大崎駅東口第３地区における地区計画区域内事業の現況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今回、１点目のＣ地区と、２点目のデッキの拡幅ですけれども、税金や補助金の関係はどういう関係にあるのか教えていただけますか。","respondent":"上野都市開発課長","answer":"Ｃ地区の開発につきましては、補助金の投入はございません。それから、今回のデッキの拡幅工事につきましても、組合側の自費工事で行う予定ですので、補助金の投入はございません。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"Ｃ地区のほう、ペデストリアンデッキが横に、それぞれ左右に最後に出ていますけれども、それはそれぞれの再開発につなげるためのものなんでしょうか。どういうものなのか教えていただきたい。","respondent":"上野都市開発課長","answer":"お手元、地元説明会資料を１枚めくっていただきますと、Ｃ地区の業務棟の左右にペデストリアンデッキを整備する計画となっています。あるいは現在工事中の第３地区とそれぞれペデストリアンデッキを結ぶ予定ですけれども、千代田グラビヤ側で整備する予定となっています。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問","question":"今日はもう時間がないので、あしたにでも説明していただければなと思います。東急から地元には説明が行っているようなんですけれども、やっぱり議会のほうにあっていいんじゃないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965541?Template=document&Id=3852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":61483,"voices":207}},{"id":"h18-20060626-9","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"文教委員会","time":"午前１０時０３分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"第５４号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第５４号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"以前問題になったこういう仕事をする人たちの確認、前、高齢で仕事をされていない薬剤師がそのまま指定されていたことがあったんですよ。あるいは失礼な方法かもわからないけれども、確認の連絡をとるとか、そういうことはされているんか尋ねました。","respondent":"古里学務課長","answer":"これが１年のうちに、いろいろな調査を含めて数回行われます。必ず全学校私どものほうに上がってまいりますので、そういうチェックは、必ず働いていただいているという確認はとってあります。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"教育委員会が、Ａ先生をＢ小学校の学校医、あるいは歯科医、あるいは薬剤師という形で指名するんですか。その仕組みをちょっと。","respondent":"古里学務課長","answer":"それから歯科医、それと薬剤師につきましては、それぞれ医師会のほうに学務課のほうから依頼を申し上げます。そのようなことを入れて医師会のほうに推薦をお願いして、推薦に基づいて私どもと学校と相談して、委嘱をするという手続をとってあります。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"確認","question":"それで、毎年の役割というか、仕事がなされていることで確認がされている、そういう理解ですね。２人ずつ契約というか、配置されているんですか、その辺だけ最後に聞かせてください。","respondent":"古里学務課長","answer":"学校保健に関するさまざまな医師、薬剤師等の配置につきましては、学校保健法という法律で定められてあります。学校保健法に基づいて、小学校、中学校それぞれ配置をしております。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、品川は４・３・２とやっていっても２人ということになるわけですね。全国的に小中は６・３という形の中でいけば２人という、そういう考え方でいいか尋ねました。","respondent":"古里学務課長","answer":"検討を始めるということになってございまして、間もなく検討を開始したいと思ってありますが、そこを抜けるということにはならないかと思います。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"８級にするというんですか。それを今度変えたのは、世界的な流れなんだという説明があるんですけど、そこらをもう少し詳しく説明していただけるとありがたいんですけれども。","respondent":"古里学務課長","answer":"その中では、世界的な整形学会での障害の考え方等も取り入れて論議をしたということで、二十数ページにわたる論議の経過が書いてあります。それを見ましたところ、最終的な結論としては、お医者さんを含めてそういう検討をして上で結論を出したと聞いてあります。","id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"少ないとは思うんですけれども、そういうのがあって災害補償のランクづけがあったと思うんですけれども、諸外国の事例というのは手元にありますかとの意見を述べました。","respondent":"古里学務課長","answer":"それらしい情報については手持ちはございません。いずれにしましても、この災害補償法の大もとの論議の結果ですが、上位法にそういう規定が出てきたというところから所与の改正を行うですので。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"品川での学校関係でも、公務災害というのは件数ですと大体どれぐらいあるのか、状況がわかったら教えていただきたい。","respondent":"古里学務課長","answer":"過去の都立、公立学校で６件合計で５２６万円余の支払いがあり、私立学校につきましては１件で２３３万円余の支払いがされていると聞いてあります。","id":"exchange-007"},{"speaker":"武内委員","kind":"確認","question":"ちょっと確認だけしたいんですけれども、これは公務災害についての改定なんですけれども、先ほどもいろいろご説明があったとおり、民間のいわゆる労災が変わったということに基づいてこういう形になっているということでよろしいんか尋ねました。","respondent":"古里学務課長","answer":"労働基準法およびそれに基づく労働者災害補償保険法が最上位規定でございまして、そちらが変更になったということから、所与の自治体で順次改定作業に入っていったです。","id":"exchange-008"},{"speaker":"武内委員","kind":"意見","question":"手の指についてそういう形で変わるということで、わかるような気もするんですね。変わっていないと思うんですけれども、多分そういうことで変わっていないのかなと思うんですけれども、手だけということでよろしいんですねとの意見を述べました。","respondent":"古里学務課長","answer":"今回の件につきましては、手にかかわる障害と、それから複視、目のほうですね。この２つの点についての改正でございまして、足のほうについては情報がございませんので、ちょっと勉強不足で済みません。","id":"exchange-009"}]},{"id":"topic-02","title":"平成１８年度「通学区域の弾力化」に関するアンケート調査結果","agenda":"平成１８年度「通学区域の弾力化」に関するアンケート調査結果","exchanges":[{"speaker":"武内委員","kind":"意見","question":"なぜそういう形で、１回下がって上がったんだという、その辺はどう見ていますかとの意見を述べました。","respondent":"古里学務課長","answer":"平成１７年度の数字を見ないで、１６年と１８年を比較するという形で、今回検討させていただいた。１５年度についても、１７年度の数値については今、もうちょっと調査をしたいと思います。","id":"exchange-010"},{"speaker":"武内委員","kind":"質問・要望","question":"じゃ、またわかったときに、何かの機会にまた教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"中学校の小中一貫教育・連携教育が８.０５％に上がった要因というのは、６校構想が出ただとかというような、一歩具体化が進みましたよね。そういう影響なのかどうなのか、伸びた要因をどう区教委として判断しているのか、わかったら教えていただけますか。","respondent":"古里学務課長","answer":"これにつきましては、やはり小中一貫教育要領の発表ですとか、そういうところがかなり大きく影響していると思ってあります。この教育要領の発表以降、各学校の学校説明会においても、来年度からは小中一貫教育を全校展開するということを説明しているやに聞いてありますので。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"ここに変化が出ているというのは、施設一体型の一貫校だからというのはわかるんですけれども、その辺はどうなんでしょうか。安心してくださいというか、実態的には一貫校に関心がずっと高まっているということのあらわれじゃないのかなと思うんですが、いかがか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"もう１つ考えられるのは、学校によっては、そういった内容についても聞きながら判断したということも考えられます。大きいのは一体型だと思いますけれども。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"聞くのがいいのかどうなのかと思うんですが、いかがでしょうか、取り扱いとして。ければ別にその他でも構わないんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"私が１人になるならばほかを選ぶしかないと、そういう場面があったんだと思うんですけど、その辺の状況はどうなのか。その辺について、今日はちょっと別のところなんですけど、もしあったら出してほしいと求めました。","respondent":"古里学務課長、吉村小中一貫教育担当課長","answer":"八潮地区の問題については、別途改めて報告をします。その時点で、そういった点についてもまたご論議いただければと思います。５人を切ってくるであるとか、例えばその人数で来年度教育課程を実施したときに、これは学校の説明責任として説明する必要があると思うんですね。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"意見","question":"子どもの場合は学校で書き入れるということが可能なんでしょう。Ｑ２のところは複数回答とか、あるいは３つまでとか、その辺を最初に聞かせてくださいとの意見を述べました。","respondent":"古里学務課長","answer":"学校のほうでは一切集計をせずに、学務課のほうへ持ってきた時点で集計をしているというふうにしています。それからＱ２つきましては、Ｑ３もそうなんですけれども、複数回答、特に数の制限は設けてございません。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"意見","question":"なぜかというと、持って帰ると、親子で相談しながら記入していく。別々に回収するというのも１つの方法じゃなかったかなと思うんだけど、その辺について聞かせてくださいとの意見を述べました。","respondent":"古里学務課長","answer":"技術的な問題以外に、回答内容の問題についても少し検討をするべきものではないかと思います。ちょっと今、軽々にここでは何か申し上げられるということではありませんけれども、検討させていただきたいと思います。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"保護者への質問と書いてあるから保護者なんだね。これは６ページが、私立とは限らず、区立以外を選択した、５ページと６ページは親子という意味で見ればいいのかな。","respondent":"古里学務課長","answer":"全く同じですので、左側が保護者の回答、右側が児童の回答というふうになってあります。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"意見","question":"この部分の３７４名の方が書いてくれたわけですけれども、品川区教育委員会はどういうふうに受けとめていらっしゃるのか。総括的でもいいですし、個別にここが非常に興味深いという形でもいいので、その辺をお答えくださいとの意見を述べました。","respondent":"古里学務課長","answer":"Ｑ２ですけれども、学力というのが上位に上がってきているという点、この点が大きく異なる部分だろうと思ってあります。学力を考えてというところに対応するところから見れば、区立中学校を選んだと思われる者のアンケートとは大きく異なる部分だろうと考えております。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"意見","question":"区立中に入学というのが、そうあってほしいということを考えて、品川の教育ということをいろいろお考えになっているはずだと僕は思っています。小中一貫というのをやるときに、この区立以外を選択する人たちにとっては、魅力がないというふうに受け取っていいのかなとの意見を述べました。","respondent":"吉村小中一貫教育担当課長","answer":"ただ一番私どもが注目しているのは、例えば私立のほうの５ページの中学校の親が学校の特色ある教育活動を考えてというのは２７.２７％ですよね。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、もう少し平べったいことを言うと、これは私立とは限らない、国立も全部含めてなんでしょう。今言われた学校の特色、私立を選ぶ人が区立と比べて、一般的に言えばそういう品川の中学校になってきたというふうに幾らか考えてもいいわけですかね。","respondent":"吉村小中一貫教育担当課長","answer":"こういうふうに選択制は７年かかっているわけなんですけれども、実は最初はなかなか浸透して伸びてこなかったんですね、この特色の数字というのは。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"この数字、２７と２２を同じにするのは教育委員会の目標ですか。並べたいというか、同じように上げていきたいというのが。","respondent":"若月教育長","answer":"したがいまして、決して教員をかばうわけでも何でもないわけですけれども、私はこの７年間、品川の先生方、それから職員の方もそうです。私立と公立を対比して、うちは自分のスタンスを決めるということはこれからも一切ないだろうと、こう思っております。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"意見","question":"こういうアンケートをこれからも毎年やっていかれるとしたら、ある意味こういうところに結果が出てくるというのは、１つの成果だと僕は思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"築舘委員","kind":"質問・要望","question":"それから品川区の区外から品川区立小学校、中学校へぜひ入らせてくださいというような要望というか、そういうのはあるのかどうか。","respondent":"古里学務課長","answer":"３ページのＱ１の４の数字のところを言っていると思うのですが、これは養護学校ですとか、そういう学校もあります。文字どおりこれは品川区以外の公立中学校、いろいろな形の公立中学校がありますが、そちらへ入学するという数字だと考えております。","id":"exchange-024"},{"speaker":"築舘委員","kind":"質問","question":"クラブ活動のこととか、そういうことも絡んでくるわけなので、そういった選び方をしているのかなと。中学校の選び方と小学校の選び方というのは多少違ってくると思うんですけれども、その辺のことはアンケートに出ているんか尋ねました。","respondent":"古里学務課長","answer":"きちんとすべての学校が取り組まなければいけないということを逆に言っているのかなというふうにも思っております。きちんとした教育が受けられる環境をそれぞれの関係者が邁進していくということが基本になろうかなと、私は全体から読ませていただきました。","id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"林委員が言われたように、進学の問題を考えたときに、公立学校でもしっかりした学力をつけられるのだということを僕は目指すべきだと思うんですね。","respondent":"吉村小中一貫教育担当課長","answer":"いろいろな自治体がありますけれども、特に品川については、最低限の学力についてはすべての者に身につけたい。そのことを重点的にこの小中一貫教育では取り組んでいきたい、こんなふうに思っております。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"とすると、片方で特色あるというのを勧めながら、どうしてもそれに乗れていない部分がある学校というふうにとらえることもできるだろう。プライバシーの問題があってわからないのかもわからないけど、行きたくないと指定された学校は知っておくべきだと思うんだなとの意見を述べました。","respondent":"吉村小中一貫教育担当課長","answer":"指定校に入学したくないからと、これは一応全体のデータなんですけど、当然個別のデータというのがあるんですね。これから個別のデータを分析して、そういった要因がどこにあるのかというのをこれからやっていくところでございまして、今まさに準備しております。","id":"exchange-027"}]},{"id":"topic-03","title":"伊藤中学校の心障学級の設置","agenda":"伊藤中学校の心障学級の設置","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"確認だけします。希望的観測しかできないのかどうかわかりませんけど、申請して認可というか、おりる可能性について教育委員会はどう考えていますか。","respondent":"河野指導課長","answer":"区内の中学校に設置されている心障学級は全部で５校に設置していますが、八潮中学校については在籍者がゼロということで、休級です。それから認可の可能性ですが、一応都の内諾を得たということで、都のほうから準備は進めてくださいという連絡はいただいております。","id":"exchange-028"}]},{"id":"topic-04","title":"小中一貫教育全国サミット","agenda":"小中一貫教育全国サミット","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、日本の義務教育が９年制、枠は９という数字は変えないんでしょう。とすると、４・３・２という形が文部科学省が、方向はそうなってきているんだというふうに理解しておくほうがいいんですかね。","respondent":"吉村小中一貫教育担当課長","answer":"８０２という特区を受けて、平成２０年度を目途に、制度改正も含めて検討していくという方向は出ておりますので。そういった意味で、このサミットの議論も参考になるのかなと考えています。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"この小中一貫教育全国連絡協議会の正会員と賛助会員の違いは、読んで字のごとしなんだろうけど、正会員は自治体しかなれませんよと。賛助会員の場合、どこまでどういう参加の仕方ができるのか、もうちょっと細かく説明をお願いいたしますとの意見を述べました。","respondent":"吉村小中一貫教育担当課長","answer":"そして第３回目もまたそのほかの自治体ということで、これはある程度、何年か継続的に続けていくということで考えております。この小中一貫教育の全国的な動きであるとか、全国の情報、そういったものについては会報を通じて共有するということで考えております。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"例えば団体に入っていると５,０００円の年会費を納めて、何カ月かに一遍やるときに１人参加できるというふうに考えておいていいわけですか。それとも個人個人、１人ずつ、Ａさん、Ｂさん、Ｃさんと入っているという人は、別々の個人的な賛助会員というふうにとらえられるんか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"この小中一貫教育全国サミットに関しては、先ほど２,０００円と申し上げましたけど、そういったお金を払わずに参加ができる。基本的には年１回の連絡協議会、そして年１回の全国サミットということを中心に活動していくというふうに考えております。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"１つは左側のシンポジウムについては、どちらかというと校長であったり、教育委員会であったりというような対象を考えていらっしゃる。真ん中はそれぞれ分科会ということなんだけれども、一番のターゲットはどういうところに置かれてこれを開かれるんか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"ですから、当然自治体レベルで日本の義務教育をどうするのかという考え方が根底にないと、そういった意味での内容は午前中に入れします。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問","question":"今の質疑の中で、国のほうは小中一貫教育、あるいは一貫校というんですか。それはどういう理由で盛り込んでいるんか尋ねました。","respondent":"吉村小中一貫教育担当課長、若月教育長","answer":"ですから、それを今回、昨年の１０月２６日の答申の中に具体的に盛り込んで、検討を進めていきますよと。義務教育学校の設置に向けた検討を具体的に進めていきますよということで今、話が進んでいるです。担当課長が答えたとおりなんですけれども、方向性としては、要するに今の６・３制そのものはそのものとして存続させる。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問・要望","question":"その中の教育課程審議会での議論だったでしょうかね、案として、それから一番トップにかかっているのは学力テストの全国的な実施なんですね。子どもたちの学校の状況はどうなのか、また別の機会に質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"築舘委員","kind":"意見","question":"それともどういうふうになるのかというのが１点と、やっぱり少しでも多くの人に知ってもらいたいということがあると思うんですね。さまざまなところに呼びかけをされるとは思うんですが、どういったところを対象に呼びかけするか、以上２点との意見を述べました。","respondent":"吉村小中一貫教育担当課長","answer":"今のところあと４つと申し上げましたけれども、ずっと募集は続けていくということで考えておりまして、その段階で正会員に入っていただく。その辺、状況を見ながら、声かけ等も考えていきたいと考えております。","id":"exchange-035"},{"speaker":"築舘委員","kind":"質問","question":"そうすると、分科会のところに三笠市とか郡山市というところも入っているんですけど、そういう市も小中一貫ということでやっているということか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"ここの分科会を実践する自治体については、かなり進めている自治体と考えていただいて結構だと思います。","id":"exchange-036"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"ここに載せていただいている特別支援教育ということと、図書館サービスの向上という２点について要望させてほしいと求めました。今のところ、検索したときに区立図書館のほうから借りられる体制なんかがどうなっているかとか、その辺のところで２点挙げさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"もともと１回しか学びの時期というのはないですから、取り返しのつかないことになるんじゃないかというのが１つありまして、やっていることは。全国で約８００人に当たるあれを、ぜひ文教委員会でも調査テーマにしていただければありがたいなと思って、ご意見を掲げさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"本間委員","kind":"質問・要望","question":"研究課題にしてほしいと求めました。２つ目、小学校１年生からの英語教育が、どこまで必要なのかということも含めて追求していこうじゃないかということが２つ目のテーマです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"築舘委員","kind":"意見","question":"今、教育ということ、これは幼稚園教育の大切さというものをさらに見直していくということも必要なことだと思います。最近親が子どもを殺害するとか、そういった形の子どもの安全というのはしっかりと見ていかなければいけないということで、提言をしておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-06","title":"今定例会の一般質問に関する所管質問ですが、今定例会の一般質問の中で、文教委員会にかかわる項目","agenda":"今定例会の一般質問に関する所管質問ですが、今定例会の一般質問の中で、文教委員会にかかわる項目","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"２中学校、３小学校、もう少し詳しく説明いただければありがたいなと思います。そのことを聞きたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ここを直せとかそういう話ではなくて、知っておかなきゃいけない部分ですから、明日報告をいただきたい。だから、その資料提供だけでもしてほしいと思うので、ぜひお願いをしておきたいと思うんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"沢田委員","kind":"意見","question":"前回やっていたら大変申しわけないので結構なんですが、先日、都教委で学力到達度テストをやりましたよね。その結果がどうなのか、どう見たらいいのかというのを、どこかで説明をお願いしたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/670410?Template=document&Id=4574#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":31541,"voices":117}},{"id":"h18-20060626-5","meetingId":"h18-cm06","date":"2006年6月26日","dateIso":"2006-06-26","committee":"総務委員会","time":"午前１０時０３分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"の２、議案審査","agenda":"の２、議案審査","exchanges":[{"speaker":"山村委員","kind":"質問","question":"外国旅行の旅費のところなんですが、鉄道賃と船賃があるんですけれども、これは飛行機の場合はどう変わっているんですか。これがどれに該当するのか説明を求めました。","respondent":"榎本人事課長","answer":"今回、この条例の改正の中で等級が変わったのが鉄道賃と船賃ということで、航空賃につきましては、３等級以上も２等級以上も、分かれる場合に管理職、係長と同じ等級となりますので、級別で分けておりませんので、今回は改正がなかったという形です。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"基本的なところでよくわからないんですけれども、職員の給与に関する条例の改正というところはわかるんですけれども、そのことと市町村合併に伴ってというところがちょっとよく理解しがたいところなんですけれども、その辺のところをもう少しとの意見を述べました。","respondent":"榎本人事課長","answer":"市町村合併が一段落した段階ということで、この別表を改正するということで、内国旅行の近接地は旧条例とは関係ございません。市町村合併ということで名称を整理したという形です。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"役所の中では内国旅行というのが一般的なのかというのが１点と、直近でいいんですけれども、大体何人ぐらいの職員の方が海外旅行には行っているんか尋ねました。","respondent":"榎本人事課長","answer":"それから、もう１つの外国旅行の事例ですけれども、去年がたしか議会の海外調査の同行に理事者が行っているという部分が去年あります。それから、その前につきましては研修で行っているということで、一応、研修の中で年１組、大体二、三人が外国旅行に行くという事例があるです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"これは何年ごろこういう制度ができたのかということをちょっと１点聞きたいのと、例えばこういうのが適当なのかどうなのかという議論もあるかと思うので、その辺のところのご見解を説明を求めました。","respondent":"榎本人事課長","answer":"対応するところに応じたものをきちんと用意していかなければいけない、要はどういうレセプションなり、こういう規定が定められているという形です。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"総務委員会ですから、これから約１年やっていく中で契約についての議案というのを多く取り上げてくると思うので、最初なので質問しますが、品川区でという意味ではなくして、いわゆる談合とよく聞かれますが、談合というのはどういうものか、まず説明をしてくださいますか。","respondent":"中島経理課長","answer":"談合についてのご説明ですけれども、事前に打ち合わせたとおりの形で落札をして仕事をしていくというようなことが、一般的に談合と言われているものです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"独占禁止法が出てきましたけれども、法律では、当たり前ですが、談合というのはいけないよ、してはいけないという形になっていると思うんですけれども、実質、相談をして、価格を決めて、入札するというのは、何が問題なのか尋ねました。","respondent":"中島経理課長","answer":"価格を決める際には一般競争入札、その中で談合をするということは、いわゆる公平な形での入札が行われないです。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"予定価格よりそんなに差が出ないような高い部分で話し合いをして、いわゆる金額を決めていくから、それがまずいということでいいんでしょうか。業者の大体の値段がわかるわけですから、談合で高い価格で工事等を落としてしまうというか、とってしまうということが問題だということか尋ねました。","respondent":"中島経理課長","answer":"談合によって結果的に落札価格が高くなる場合もありますし、場合によっては安くなる場合もあるのではないのかなと考えています。発注件数等を決めるということは、いわゆる法の趣旨の公平な価格競争というものに反するというのが一番の問題であると考えています。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと私もお聞きしたいんですけれども、その積算の単価の基準ですか、それをちょっと説明を求めました。","respondent":"中島経理課長","answer":"それをつくって金額、予定価格等を算出するわけですけれども、そのもととなっている基準は、国土交通省からの積算基準というものがあります。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"いわゆる実際は国交省の基準より何％か低い基準で出しているとか、そういうことなんでしょうか。品川区の施設に関して、お願いします。","respondent":"宍戸施設担当課長","answer":"最近ではかなり、かなりというか、近づいた線で来ているのではないかと思います。検討は、その差額については小さいというか、限りなく民間に近い金額で今は発注していると考えています。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"一応、品川区の施設担当ではそういう専門の知識を持った経験者というんですか、そういう方がいて積算をされると考えていてよろしいんでしょうか。それとも外注に出して、積算を依頼というか、相談して協力してもらっているという形なんか尋ねました。","respondent":"宍戸施設担当課長","answer":"それぞれの専門がおりますが、積算の専門家が国交省の基準などを、東京都の地域特性も踏まえたもので積算を出してきます。それを我々職員も、一級建築士がおりますので、チェックするといったような形で金額を決めているところです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"３.３％の範囲で大体入札金額が出ているということに対して、そういう単純な感覚で入札価格、金額がやっぱり出てきちゃうものでしょうか。ちょっとご見解だけ説明を求めました。","respondent":"中島経理課長","answer":"今、資本金と入札価格のご質問がございましたけれども、資本金が大きいところというんですか、が必ずしも入札価格が安くなるといったことは一概には言えないのではないのかなと考えています。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"ですからそんなに大きな会社が安くなるとか、一般的な企業から考えた場合に、ほとんど建設というのは人件費がほとんど占めていると思うんです。この範囲でおさまって、なおかつちょっと金額が上下するというのは不思議なような気もするんですけれども、それは別に当たり前の話か尋ねました。","respondent":"中島経理課長","answer":"制限付き一般競争入札の場合は予定価格を公表していますので、どちらの企業も、入札する際にはこの予定価格をまず頭に入れて入札価格を決めてくる。いろいろな工事のやり方を検討しまして、利益をどのぐらい出すというのを考えた上で、予定価格以内の入札価格を決めてくる。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"なぜその予定価格というのは出さないといけないんでしょうか。２０社なら２０社、その１点だけ、なぜ予定価格を決めなきゃいけないんか尋ねました。","respondent":"中島経理課長","answer":"予定価格の公表は、要するに契約の透明性とか、公平性を確保するというのが一番の目的なのかなと考えています。制限つきの競争入札というのはもうすべての会社が全部参加できるというようなことで、公平性も透明性も担保できる制度だと考えています。","id":"exchange-013"},{"speaker":"藤原委員","kind":"確認","question":"予定価格があるんだから、それで区がちゃんと審査をするわけですから、工事に関しても安かろう悪かろうにはならないわけですよね。だから予定価格より安くなったほうがいいのは間違いないと思うんですが、まずそこは確認したいんですが、お願いします。","respondent":"中島経理課長","answer":"私ども発注者側とすれば、それはよい仕事を安くしてもらえれば、それが一番いいと考えています。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"この目黒川右岸低地部というこの議案なんですけれども、これは予定価格の何％でこの７番目の業者は落としているんか尋ねました。","respondent":"中島経理課長","answer":"予定価格が１２億４,２２６万４,０００円に対しまして、１１億５,５００万円ですので、いわゆる落札率といいますけれども、これは９２.９７％になってあります。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"例えば、申し込んだところが１０社あったと、その１０社がどこだかわからなければ、談合というのは起きようがないわけですよね。その１０社はわからないシステムになっているのか、調べようによっては１０社がわかります、それはどっちか尋ねました。","respondent":"中島経理課長","answer":"入札に参加する人を第１グループ、第２グループに分けて募集するわけですけれども、いわゆる大きいほうの会社です。事前に２社で組んでもらった形で参加していただくということになってありますので、どこが参加しているかというのはわかるようになってあります。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"競争の透明性とかもあるから談合をしてはいけないわけですから、システム上、談合をとめるということはできないということか尋ねました。","respondent":"中島経理課長","answer":"委員の言われた部分というのは確かに大きいと思います。そういった方向で、今、動いてきているというのが現状です。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"一番大きいのはそのシールド機ですか、今回の１１億５,５００万円という契約金額の中で終結してしまうものなのか、ちょっとその辺を教えていただけますか。","respondent":"原田下水道河川課長、石田委員長","answer":"シールドマシンを動かすときに、ああいう防音ハウスのような仮設物は、この工事が終わるまで最初に設置したらそのままずっと使うということになります。今の話は、シールド掘進機のリサイクルの話を言っていると思うんだ、価格の。だからその説明をしないと、その話をしているんだと思うから… シールドマシンの今回使ったものについては、この工事は最後まで使うわけですけれども、その後、別に転用できる場合は転用します。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"ということは、この１１億５,５００万円の価格の中に、減価償却分というのか、ここで使う機械が新しいものか古いものかはわかりませんけれども、予定価格をつくるときに、その辺がどういうふうに加味されるのかをちょっと教えていただけますか。","respondent":"原田下水道河川課長","answer":"六年前に東京都下水道局で技術開発して、今回使うシールドマシンについては、最初の工事ではまず丸々買い取るという形で設計金額を見ています。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、ちょっと次の工事がよくわからないんですけれども、その３工事でまたシールド、全体計画のまだ半分ぐらい残るんですかね。そのときには、今回のように、概要書にあるように、このシールド機というのは含まれないことになっていくと解釈していいんか尋ねました。","respondent":"原田下水道河川課長","answer":"例えば、その３工事でいけば、今のところシールドマシンは設計金額に入れてません。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと工事についてお聞きしたいんですけれども、昨今、地球温暖化ということで水位がこれからだんだん上がってくるのではないかと思うんです。いずれ流れなくなれば、その貯留管というんですか、その管の中にたまりっ放しという事態も将来起こり得るというふうな考え方でよろしいんか尋ねました。","respondent":"原田下水道河川課長","answer":"そのポンプの能力が河川、それは海の水位が上がれば、それなりのまたポンプを増強するということで対策はとれるのではないかと思います。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"発想として、やはりそういう事業のほうがいずれは大切になってくるような状況もなる、それとも別の方法論というのがやっぱり出てくるんでしょうかね。その辺は何か将来的なビジョンとして、こういうふうに考えていますよというのは出ているんか尋ねました。","respondent":"原田下水道河川課長","answer":"そういう取り組みを少しずつ進めていまして、そちらは今後、本格的に進めていくものと思われます。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"今、問題が出たのでついでにお聞きしたかったんですけれども、その先々の考えというのは何か出ているんでしょうか。構想というのは。","respondent":"原田下水道河川課長","answer":"水位が上がることに対して、その次にどういう事業をするかというところまでは検討しておりません。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"今回は第２期解体という、１,９３０m2入っていますけれども、考え方を教えていただきたいというのが１つです。大きなというとおかしいかな、この辺の区内の業者にやらせるという考え方はどうなのかというのを、その２点をお聞きしたいんですけれども。","respondent":"宍戸施設担当課長、中島経理課長","answer":"解体だけすればいいだろうというふうな施工業者の対応の問題等もございまして、今回は外構工事と一緒に発注させていただいたという部分もあります。… 困難性があるというようなこともありますので、対象業者を品川区内の業者に限らないで、いわゆる格付Ａの業者ということで公告をしております。そういった意味では、今回はたまたま区外の業者が落札したです。","id":"exchange-024"},{"speaker":"菊地委員","kind":"意見","question":"区としての責任のところをもう少しはっきり示してほしいなというのと、どうして格付Ａのところだったら迅速に進んで、その辺がよくわからないのでとの意見を述べました。","respondent":"宍戸施設担当課長、中島経理課長","answer":"解体工事業者の対応の悪さという点ですけれども、その点でいえば、全く委員のおっしゃるとおりだと思います。解体業者の対応の悪さという意味ではない責任の一本化というのが図れるという意味で申し上げたところです。そういった部分では、現在やっている業者との調整が非常に困難性があるというようなこともありますし、さらに工期の問題もあります。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問・要望","question":"そこはどういう契約状況、内容であるにかかわらず、区がぜひ住民の方とのところは責任を持っていただきたいなと思っています。もう１つ、これも調整云々と言われちゃうと確かに全然見えないところですから、超高層をやれといったって無理な話ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"菊地委員","kind":"意見","question":"直接の内容についてどうのこうのというのは聞けない内容ですけれども、本体工事についても反対をしておりますので、この外構工事についても反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"山村委員","kind":"質問・要望","question":"ちゃんと確認してほしいと求めました。それと、最近、防火扉の話があったと思ったんですが、そこら辺はいかがか尋ねました。","respondent":"宍戸施設担当課長","answer":"防火シャッターですけれども、面積の区画などの際、小山小学校でも使うことを予定しております。で、そのまま閉まるというふうな仕組みが義務づけられておりまして、小山小学校の防火シャッターにつきましてもそういう仕組みとなっています。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"最初の委員会ですので再度お伺いしたいんですけれども、次に２１ページにも、さすがプロが見積もりしているなと考えています。やっぱりこれでまず大丈夫でしょうかという質問と、そこの大丈夫ですかが１点と、区にとっては一番いいことなんですよねという２点の質問です。","respondent":"中島経理課長","answer":"１点目の大丈夫ですかというご質問ですけれども、これは予定価格からいたしますと、落札率が７６.８６％となっています。ただ、繰り返しになりますけれども、区としましては、なるべく安くいい仕事していただく、それが競争入札の本旨ではないかと考えています。","id":"exchange-029"},{"speaker":"須貝委員","kind":"意見","question":"というのは、これが５年なり１０年したら、また耐震の安全基準が変わって、それに適合しなくなるとか、そういう心配もあるわけですよね。その辺の、まず安全基準度は現在の安全基準度に対してどのぐらい高い設定の建物を建てようとしているのか、それを説明を求めました。","respondent":"宍戸施設担当課長","answer":"昭和５６年にいわゆる新耐震基準というのができまして、それまでの建物の強度という考え方に、基準が大きく変わりました。今回の学校につきまして、新耐震基準はかなり厳しい内容になっておりますので、大きな地震が来ても大丈夫と思っているところです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"意見","question":"先を見越して新耐震基準をさらに上回った割合で想定して建てていると思うんですけれども、その割合というのは今、出ませんか。大体これぐらいのめどでというものがとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"余裕は見ての設計はしていると思いますが、きちっとクリアをしているという内容です。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"４０年、まだこれから取りかかるわけですから、耐震基準をさらに上回るものを設計して建ててほしいと思います。なぜ１つの、１社に発注して、その辺を説明を求めました。","respondent":"中島経理課長","answer":"ただ、私どもこの間ずっとご説明しておりますが、契約の基本はまずは業種単位に発注していくというのが基本になってあります。それともう１つは、そういった意味で区内の中小企業者の受注機会を広げていくという２つの面がございまして、今回みたいな契約方法をとっているです。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点だけちょっと教えてもらいたいんです。現地を見たときに、現状のスペースと、これから新しい設計でのスペースの違いをまず教えていただきたい。","respondent":"宍戸施設担当課長","answer":"考え方ですが、学校側もこのマルチルームを使うということで、相乗りをしようというふうな考えで進めていると聞いております。","id":"exchange-033"},{"speaker":"菊地委員","kind":"意見","question":"児童数で３００人弱ぐらいになっているんですけれども、区の施設としてどうなのかなという感じがしましたので、その辺はちょっとぜひご報告を願えればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"若林副委員長","kind":"質問","question":"２点ほど伺わせていただきます。いわゆる歩道橋という言い方でいいんでしょうか、それはご検討されたのかどうか、この２点ほどをお聞かせいただければと。","respondent":"宍戸施設担当課長","answer":"この度建築基準法が改正になりましたので、天井高については３ｍを切る形に今後はなっていくのではないかなと考えております。安全性で、相当掘らないとクリアできないんじゃないかというふうなこともございまして、歩道橋で渡すという選択になったものです。","id":"exchange-035"},{"speaker":"菊地委員","kind":"質問・要望","question":"２点お聞きしたいんですけれども、今回の場合、下はポンプ所ということで東京都の下水道局が管理するんですか。ちょっとこういうものはどうなるのか教えていただきたいのと、もう１点、その辺の現状というのがわかれば教えていただければと。","respondent":"中島経理課長、日下部企画財政課長","answer":"大家はポンプ所になろうかと思いますけれども、公園について整備していくのは当然区で管理をしていくということで考えてあります。私は詳しく承知しておりませんので、後ほど誤解を招いてしまうといけませんので… 橋本産業につきまして、今、ご質問にございました。天王洲側あるいは反対側から回り込むと、もうそういう形をとらざるを得ない、そういう状況です。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"もちろんポンプ所ですから東京都の下水道局が管理するんでしょうけれども、区として管理するのはどの部分に当たっているのか、もう少し細かいところをお願いします。","respondent":"日下部企画財政課長、中島経理課長","answer":"ですから、単純に申し上げれば、ポンプ所はこれはあくまでも下水処理施設です。上部の公園に相当する部分については、あくまでも区で一括して管理をすると、そういう形です。 これは区と下水道局の間で、屋上等を公園として利用するということになっておりますけれども、いわゆる都市計画法を適用しない公園とするという条件のもとで下水道局と文書が交わされているです。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"都市計画公園として整備をするということをしてきたということと、そういう契約は交わしていないという話をしているんです。どっちが正しいか尋ねました。","respondent":"日下部企画財政課長","answer":"経理課長の発言がまさしく、いわば都市計画公園とは分離する形でという形、そちらのほうが正しい中身です。失礼いたしました。","id":"exchange-038"},{"speaker":"山路委員","kind":"質問・要望","question":"平成８年に一般質問でお願いしていたあずまやとか、昨年の決算特別委員会でお尋ねしたときに、パラソルか何かをつけるという答弁をされていますね。これによりますと載っていないので、ご検討されたか、ちょっと聞かせてほしいと求めました。","respondent":"中島経理課長","answer":"大変申しわけありません。後ほど管理工事課長に確認して、改めてご答弁させていただきたいと考えています。","id":"exchange-039"},{"speaker":"塚本委員","kind":"意見","question":"あれはどういうコストアップがあって、それはどっちが負担しているのかということが１点と、維持管理費はおよそどんな概算をしているのかという点をとの意見を述べました。","respondent":"中島経理課長","answer":"先ほどもちょっと菊地委員からの説明もございましたけれども、エレベーター等につきましても、品川区で管理していくです。維持管理費についてはちょっとまだ把握してございませんので、別な機会に改めてご答弁させていただければと、このように思っております。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"余計な心配だと思うけれども、メンテナンスという意味でも、それはどういうことになっているのかということを。コストアップ、駆体はもちろん強くしなきゃいけないという、メンテ費も余計にかかるだろうということはどういうふうな考えを持っているんか尋ねました。","respondent":"日下部企画財政課長","answer":"上部を使う、そういった意味では、通常の維持管理よりもおそらくこれはコスト的にも確かに若干高目になるという可能性が非常にあります。私もちょっとその辺について実情を把握しておりませんので、その辺は早急にまた調べまして、ご報告をさせていただきたいと思います。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816536?Template=document&Id=1722#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":36040,"voices":157}}]);
